/* Alpha 1.5.69 — garde réseau cloud-only
   Réduit les boucles public_missions héritées sans toucher aux autres systèmes. */
(function(){
  if(window.__stellarionCloudNetworkGuard1569) return;
  window.__stellarionCloudNetworkGuard1569 = true;
  var oldFetch = window.fetch ? window.fetch.bind(window) : null;
  if(!oldFetch) return;
  var cacheText = null, cacheAt = 0, publishAt = 0;
  function isPublicMissions(url){ return String(url||'').indexOf('/rest/v1/public_missions') >= 0; }
  function methodOf(init){ return String((init && init.method) || 'GET').toUpperCase(); }
  window.fetch = async function(input, init){
    var url = (typeof input === 'string') ? input : (input && input.url) || '';
    var method = methodOf(init);
    if(isPublicMissions(url)){
      var now = Date.now();
      if(method === 'GET'){
        if(cacheText !== null && now - cacheAt < 15000){
          return new Response(cacheText, {status:200, statusText:'OK', headers:{'content-type':'application/json', 'x-stellarion-cache':'public_missions_1569'}});
        }
        try{
          var res = await oldFetch(input, init);
          try{ var clone = res.clone(); clone.text().then(function(t){ cacheText=t; cacheAt=Date.now(); }).catch(function(){}); }catch(e){}
          return res;
        }catch(e){
          if(cacheText !== null) return new Response(cacheText, {status:200, statusText:'OK', headers:{'content-type':'application/json', 'x-stellarion-cache':'public_missions_fallback_1569'}});
          throw e;
        }
      }
      if(method === 'POST' || method === 'PATCH' || method === 'PUT'){
        if(now - publishAt < 8000){
          return new Response('[]', {status:200, statusText:'OK', headers:{'content-type':'application/json', 'x-stellarion-throttle':'public_missions_1569'}});
        }
        publishAt = now;
      }
    }
    return oldFetch(input, init);
  };
})();

