  function S(){ try{return window.state || (typeof state !== "undefined" ? state : null);}catch(e){return window.state || null;} }
  function now(){ return (window.performance && performance.now) ? performance.now() : Date.now(); }
  function mark(ms){ editingUntil = Math.max(editingUntil, now() + (ms || 2600)); }
  function isAllianceView(){ var s=S(); return !!(document.body && document.body.classList.contains("view-alliance")) || !!(s && s.view === "alliance"); }
  function isEditable(el){ return !!(el && el.matches && el.matches("input,textarea,select,[contenteditable='true']")); }
