 G.alliancePromote1560=function(i){const ranks=["Recrue","Membre","Officier","Bras droit","Fondateur"],m=S().alliance&&S().alliance.members[i];if(!m)return;const idx=Math.max(0,ranks.indexOf(m.rank));m.rank=ranks[(idx+1)%ranks.length];S().allianceLogs.unshift((m.name||"Membre")+" passe "+m.rank+".");syncOwn();saveRender()};
