 G.allianceApply1560=function(id){const a=baseAlliances().find(function(x){return String(x.id)===String(id)});if(!a)return;modal('<span class="pill">CANDIDATURE</span><h2>['+esc(a.tag)+'] '+esc(a.name)+'</h2><textarea id="allianceCxApplyMsg" class="alliance-cx-field alliance-cx-textarea">Bonjour, je souhaite rejoindre votre alliance.</textarea><div class="alliance-cx-modal-actions"><button class="btn btn-gold" type="button" onclick="allianceSendApply1560(\''+esc(a.id)+'\')">Envoyer</button><button class="btn btn-ghost" type="button" onclick="closeAllianceModal1560()">Annuler</button></div>')};
