window.addEventListener("error", function(e){
  const app = document.getElementById("app");
  if(app){
    app.innerHTML = '<div style="padding:24px;color:white;background:#020510;min-height:100vh;font-family:Arial"><h1 style="color:#ff8a80">Erreur Stellarion</h1><p>'+String(e.message)+'</p><pre style="white-space:pre-wrap;color:#90caf9">'+String(e.filename||"")+' ligne '+String(e.lineno||"")+'</pre><button onclick="localStorage.clear();location.reload()" style="padding:12px 16px;border-radius:10px;border:0;background:#4FC3F7;color:white;font-weight:bold">Réinitialiser sauvegarde</button></div>';
  }
});

