// tick (timer) peut enregistrer l'empire neuf initial par-dessus la vraie sauvegarde
// pendant l'await du chargement -> reset au rechargement.
let __stellarionReady=false;
const SAVE_KEY_BASE="stellarion_save_v1";
// La sauvegarde est propre à chaque joueur connecté : on suffixe la clé avec son id.
function setSaveKeyForUser(user){
 if(user && user.id){
  SAVE_KEY = SAVE_KEY_BASE + "_" + String(user.id).replace(/[^a-zA-Z0-9_-]/g,"_");
  window.__stellarionAuthenticatedMode = true;
 } else {
  SAVE_KEY = SAVE_KEY_BASE + "_invite";
  window.__stellarionAuthenticatedMode = false;
 }
}
