/*
 ALPHA 1.3.70 — RÈGLE RENFORT ALLIÉ IMPORTANT

 Un allié peut envoyer en soutien / renfort des vaisseaux que le joueur receveur
 n'a PAS encore débloqués dans son propre chantier spatial.

 Principe :
 - Le déblocage par bâtiments/recherches limite uniquement la CONSTRUCTION LOCALE.
 - La réception d'un renfort allié ne doit jamais appeler isShipUnlocked() côté receveur.
 - Le receveur doit seulement vérifier :
   1) vitesse de déplacement disponible,
   2) règles diplomatiques/alliance,
   3) mission de type soutien/renfort valide.
 - Les vaisseaux reçus gardent leur type d'origine et peuvent défendre la planète,
   même si le joueur ne sait pas encore les produire lui-même.

 Cette règle évite de bloquer la coopération d'alliance et permet à un joueur avancé
 de protéger un joueur plus faible avec des unités supérieures.
*/
const ALLY_REINFORCEMENT_RULES={
  allowShipsNotUnlockedByReceiver:true,
  unlockRequirementAppliesTo:"local_construction_only",
  receiverChecks:["orbital_capacity","diplomacy_or_alliance","valid_support_mission"],
  forbiddenReceiverCheck:"isShipUnlocked"
};

function canReceiveAllyReinforcementShip(shipId,receiverPlanetId,fromAlly=true){
  // IMPORTANT : ne jamais bloquer ici avec isShipUnlocked(shipId, receiverPlanetId).
  // Un vaisseau non débloqué par le receveur peut quand même être reçu en soutien.
  const def=SHIPS.find(s=>s.id===shipId);
  if(!def)return {ok:false,reason:"Vaisseau inconnu"};
  if(!fromAlly)return {ok:false,reason:"Renfort non allié interdit"};
  if(typeof canStoreShipsOnPlanet==="function"){
    const cap=canStoreShipsOnPlanet(receiverPlanetId,shipId,1);
    // Alpha 1.5.30 : stationnement illimité, plus de blocage par capacité orbitale.
  }
  return {ok:true,reason:"Renfort allié autorisé même si le vaisseau n'est pas débloqué par le receveur"};
}

function receiveAllyReinforcementShips(receiverPlanetId,shipsPayload,fromAlly=true){
  // Fonction utilitaire serveur/client pour futures alliances :
  // ajoute les vaisseaux en renfort sans vérifier les prérequis de construction du receveur.
  if(!fromAlly)return {ok:false,reason:"Renfort refusé : joueur non allié"};
  state.planetShips=state.planetShips||{};
  state.planetShips[receiverPlanetId]=state.planetShips[receiverPlanetId]||{};
  const received=[];
  for(const [shipId,qtyRaw] of Object.entries(shipsPayload||{})){
    const qty=Math.max(0,Math.floor(Number(qtyRaw)||0));
    if(qty<=0)continue;
    const check=canReceiveAllyReinforcementShip(shipId,receiverPlanetId,true);
    if(!check.ok)return {ok:false,reason:check.reason,shipId,details:check};
    state.planetShips[receiverPlanetId][shipId]=(state.planetShips[receiverPlanetId][shipId]||0)+qty;
    received.push({shipId,qty});
  }
  try{save&&save()}catch(e){}
  return {ok:true,received};
}


