function scanPowerFromFleet(f){
 let power=0;
 const ships=f.ships||{};
 for(const [id,n] of Object.entries(ships)){
  const def=SHIPS.find(s=>s.id===id);
  if(!def)continue;
  if(id==="scout_probe")power+=120*n;
  else power+=Math.max(5,(def.attack||0)*0.15)*n;
 }
 return Math.max(1,Math.round(power));
}
function scanSuccessChance(system, fleet){
 const scanPower=scanPowerFromFleet(fleet);
 const defense=(system.enemyPower||0)*0.35+(system.counterIntel||0)*8+(system.danger||1)*60;
 let chance=scanPower/(scanPower+defense);
 if(system.type==="colonizable")chance+=0.18;
 if(system.type==="hostile")chance-=0.08;
 chance=Math.max(0.08,Math.min(0.95,chance));
 return chance;
}
function scanOutcomeText(chance){
 if(chance>=0.75)return "Risque faible";
 if(chance>=0.45)return "Risque moyen";
 if(chance>=0.25)return "Risque élevé";
 return "Risque critique";
}

/* Alpha 1.5.30 — préservation scroll flotte galaxie à la racine */
function fleetScrollSnapshot149(){
 try{
  const nodes=[window,document.scrollingElement,document.documentElement,document.body];
  document.querySelectorAll(".app,.main,.center,.side,.side.right,.panel,.galaxy-selected-card,.galaxy-mission-wrap,.mission-compact,.mission-ship-list,.mission-panel,.fleet-drawers,.ship-selector,.ship-list").forEach(el=>{
   try{
    if(el && (el.scrollTop>0 || el.scrollLeft>0 || el.scrollHeight>el.clientHeight+2))nodes.push(el);
   }catch(e){}
  });
  return [...new Set(nodes.filter(Boolean))].map(el=>{
   if(el===window)return {win:true,x:window.scrollX||0,y:window.scrollY||0};
   return {el,x:el.scrollLeft||0,y:el.scrollTop||0};
  });
 }catch(e){return []}
}
function fleetScrollRestore149(snap){
 try{
  for(const s of snap||[]){
   if(s.win)window.scrollTo(s.x,s.y);
   else if(s.el){s.el.scrollLeft=s.x;s.el.scrollTop=s.y;}
  }
 }catch(e){}
}
function fleetNoScroll149(fn){
 const snap=fleetScrollSnapshot149();
 const active=document.activeElement;
 let out;
 try{out=fn&&fn()}finally{
  fleetScrollRestore149(snap);
  requestAnimationFrame(()=>fleetScrollRestore149(snap));
  setTimeout(()=>fleetScrollRestore149(snap),0);
  setTimeout(()=>fleetScrollRestore149(snap),80);
  try{if(active&&active.blur)active.blur()}catch(e){}
 }
 return out;
}

function selectedShips(){
 const out={};
 for(const s of SHIPS){
  const n=Math.max(0,Math.min(activePlanetShips()[s.id]||0,parseInt((state.missionDraft.ships||{})[s.id]||0)||0));
  if(n>0)out[s.id]=n;
 }
 return out;
}
function selectedShipPower(){
 const ships=selectedShips();
 let attack=0,cargo=0,count=0,hasScout=false,hasColon=false,hasCargo=false;
 for(const [id,n] of Object.entries(ships)){
  const def=SHIPS.find(s=>s.id===id);
  if(!def)continue;
  attack+=(def.attack||0)*n;
  cargo+=(def.cargo||0)*n;
  count+=n;
  if(id==="scout_probe")hasScout=true;
  if(id==="colon_ship")hasColon=true;
  if((def.cargo||0)>1000)hasCargo=true;
 }
 return {attack,cargo,count,hasScout,hasColon,hasCargo};
}
