// ============================================
// SON D'ALERTE (Web Audio API)
// ============================================
function playAttackAlert() {
  try {
    const audioContext = new (window.AudioContext || window.webkitAudioContext)();
    const oscillator = audioContext.createOscillator();
    const gainNode = audioContext.createGain();
    
    oscillator.connect(gainNode);
    gainNode.connect(audioContext.destination);
    
    // Son aigü qui pulse
    oscillator.type = 'sine';
    oscillator.frequency.setValueAtTime(800, audioContext.currentTime);
    oscillator.frequency.exponentialRampToValueAtTime(1200, audioContext.currentTime + 0.1);
    
    gainNode.gain.setValueAtTime(0.3, audioContext.currentTime);
    gainNode.gain.exponentialRampToValueAtTime(0.01, audioContext.currentTime + 0.3);
    
    oscillator.start(audioContext.currentTime);
    oscillator.stop(audioContext.currentTime + 0.3);
    
    // 2ème bip
    setTimeout(() => {
      const osc2 = audioContext.createOscillator();
      const gain2 = audioContext.createGain();
      osc2.connect(gain2);
      gain2.connect(audioContext.destination);
      
      osc2.type = 'sine';
      osc2.frequency.setValueAtTime(600, audioContext.currentTime);
      osc2.frequency.exponentialRampToValueAtTime(1000, audioContext.currentTime + 0.1);
      
      gain2.gain.setValueAtTime(0.3, audioContext.currentTime);
      gain2.gain.exponentialRampToValueAtTime(0.01, audioContext.currentTime + 0.3);
      
      osc2.start(audioContext.currentTime);
      osc2.stop(audioContext.currentTime + 0.3);
    }, 400);
  } catch(e) {
    console.log('Audio non disponible:', e);
  }
}

// ============================================
// SIMULATION COMBAT DÉFENSE vs ATTAQUANTS
// ============================================
function simulateCommandementCombat(enemyShips, defendingPlanetId) {
  const targetPlanet = state.planets.find(p => p.id === defendingPlanetId) || state.planets[0];
  const defenseCount = Object.values(state.defenses || {}).reduce((a,b) => a + Number(b||0), 0);
  
  // Puissance de défense
  const defensePower = defenseCount * 150;  // Chaque défense = 150 puissance
  
  // Puissance d'attaque (vaisseaux ennemis)
  let attackPower = 0;
  for(const [shipId, count] of Object.entries(enemyShips || {})) {
    const ship = SHIPS.find(s => s.id === shipId);
    if(ship) {
      attackPower += (ship.attack || 0) * (count || 0);
    }
  }
  
  // Combat
  const attackRoll = attackPower * (0.85 + Math.random() * 0.30);
  const defenseRoll = defensePower * (0.85 + Math.random() * 0.30);
  const defenseWins = defenseRoll > attackRoll;
  
  // Calcul pertes et butin
  let defenseLosses = 0;
  let stolenResources = { titanium: 0, xenite: 0, antimatter: 0 };
  
  if(!defenseWins) {
    // Attaquants gagnent - vol de ressources
    defenseLosses = Math.max(1, Math.floor(defenseCount * 0.4));
    
    // Capacité cargo des vaisseaux ennemis
    let totalCargo = 0;
    for(const [shipId, count] of Object.entries(enemyShips || {})) {
      const ship = SHIPS.find(s => s.id === shipId);
      if(ship) {
        totalCargo += (ship.cargo || 0) * (count || 0);
      }
    }
    
    // Vol proportionnel
    const titaniumAvail = Math.max(0, (state.resources.titanium || 0) * 0.8);
    const xeniteAvail = Math.max(0, (state.resources.xenite || 0) * 0.8);
    const antimatterAvail = Math.max(0, (state.resources.antimatter || 0) * 0.4);
    
    stolenResources.titanium = Math.min(titaniumAvail, Math.floor(totalCargo * 0.5));
    stolenResources.xenite = Math.min(xeniteAvail, Math.floor(totalCargo * 0.3));
    stolenResources.antimatter = Math.min(antimatterAvail, Math.floor(totalCargo * 0.2));
    
    // Réduire les ressources
    state.resources.titanium = Math.max(0, (state.resources.titanium || 0) - stolenResources.titanium);
    state.resources.xenite = Math.max(0, (state.resources.xenite || 0) - stolenResources.xenite);
    state.resources.antimatter = Math.max(0, (state.resources.antimatter || 0) - stolenResources.antimatter);
    
  } else {
    // Commandements gagnent
    defenseLosses = Math.max(0, Math.floor(defenseCount * 0.15));
  }
  
  // Détruire les défenses
  if(defenseLosses > 0) {
    const defenseIds = DEFENSES.map(d => d.id);
    for(let i = 0; i < defenseLosses && i < defenseIds.length; i++) {
      const defId = defenseIds[Math.floor(Math.random() * defenseIds.length)];
      state.defenses[defId] = Math.max(0, (state.defenses[defId] || 1) - 1);
    }
  }
  
  return {
    victory: defenseWins,
    defenseCount,
    defensePower,
    attackPower,
    defenseLosses,
    stolenResources,
    attackRoll: Math.round(attackRoll),
    defenseRoll: Math.round(defenseRoll)
  };
}

// ============================================
// TRAITER UNE ATTAQUE ENTRANTE
// ============================================
function processIncomingAttack(attackData) {
  const targetPlanetId = attackData.targetPlanetId || state.activePlanetId;
  
  // Simuler le combat
  const combatResult = simulateCommandementCombat(attackData.ships, targetPlanetId);
  
  // Créer le rapport de combat
  const reportTitle = `⚔️ Rapport de combat: Attaque de ${attackData.attacker || 'Inconnu'}`;
  const reportBody = `
ATTAQUE DÉTECTÉE ET COMBATTUE

Attaquant: ${attackData.attacker || 'Inconnu'}
Vaisseaux ennemis: ${Object.entries(attackData.ships || {}).map(([id, count]) => {
  const ship = SHIPS.find(s => s.id === id);
  return ship ? `${count}x ${ship.name}` : '';
}).filter(Boolean).join(', ')}

RÉSULTAT DU COMBAT:
${combatResult.victory ? '✅ VICTOIRE - Commandements tiennent bon!' : '❌ DÉFAITE - Ressources volées!'}

Puissance d'attaque: ${combatResult.attackPower} (roulé ${combatResult.attackRoll})
Puissance de défense: ${combatResult.defensePower} (roulé ${combatResult.defenseRoll})

Commandements détruites: ${combatResult.defenseLosses}/${combatResult.defenseCount}

${!combatResult.victory ? `
RESSOURCES VOLÉES:
- Titane: ${combatResult.stolenResources.titanium}
- Xénite: ${combatResult.stolenResources.xenite}
- Antimatière: ${combatResult.stolenResources.antimatter}
` : ''}

Heure de l'attaque: ${new Date().toLocaleTimeString('fr-FR')}
`;
  
  // Ajouter le message
  addMessage('combat', reportTitle, reportBody, {
    context: 'incoming_attack',
    attacker: attackData.attacker,
    combat: combatResult
  });
  
  // Log
  addLog(combatResult.victory ? 
    `✅ Attaque repoussée par ${combatResult.defenseCount} défenses!` : 
    `❌ Base attaquée! ${combatResult.stolenResources.titanium} titane volé.`
  );
  
  save();
  render();
}

// ============================================
// CHECKER LES ATTAQUES DEPUIS SUPABASE
// ============================================
async function checkIncomingAttacks() {
  const now = Date.now();
  
  // Limiter à 1 check par 5 secondes max
  if(now - window.lastIncomingCheck < 5000) return;
  window.lastIncomingCheck = now;
  
  if(!supa) return; // Supabase pas initialisé
  if(!state.userId) return; // Pas d'utilisateur connecté
  try {
    // 1. Récupérer toutes les flottes en vol qui nous ciblent
    const { data: incomingFleets, error } = await supa
      .from('fleets')
      .select('*')
      .eq('target_user_id', state.userId) // Flotte ciblant CE joueur
      .eq('mission', 'attack')
      .eq('state', 'in_flight');
    
     if(error) {
     console.error("Code :", error.code);
     console.error("Message :", error.message);
     console.error("Details :", error.details);
     console.error("Hint :", error.hint);
      return;
    }
    
    if(!incomingFleets || incomingFleets.length === 0) return;
    
    // 2. Pour chaque flotte entrante, vérifier si elle est arrivée
    for(const fleet of incomingFleets) {
      const elapsedSeconds = (now - fleet.sent_at) / 1000;
      const travelTime = fleet.travel_time_seconds || 60;
      
      if(elapsedSeconds >= travelTime) {
        // LA FLOTTE EST ARRIVÉE!
        
        // Vérifier si on l'a déjà traitée
        if(state.processedIncomingAttacks && state.processedIncomingAttacks.includes(fleet.id)) {
          continue;
        }
        
        // Marquer comme traitée
        if(!state.processedIncomingAttacks) state.processedIncomingAttacks = [];
        state.processedIncomingAttacks.push(fleet.id);
        
        // Afficher alerte
        showIncomingAttackAlert({
          attacker: fleet.attacker_name,
          shipCount: Object.values(fleet.ships || {}).reduce((a,b) => a + b, 0),
          targetPlanet: state.activePlanetId
        });
        
        // Traiter le combat
        setTimeout(() => {
          processIncomingAttack({
            attacker: fleet.attacker_name,
            ships: fleet.ships,
            targetPlanetId: state.activePlanetId
          });
        }, 2000);
        
        // Marquer la flotte comme reçue en DB
        await supa
      .from('fleets')
          .update({ state: 'arrived', arrived_at: new Date().toISOString() })
          .eq('id', fleet.id);
      }
    }
    
  } catch(e) {
    console.log('Erreur check incoming attacks:', e);
  }
}

// ============================================
// INTÉGRATION DANS LA BOUCLE PRINCIPALE
// ============================================
// À appeler régulièrement (dans la boucle de render ou processFleets)
function incomingAttackLoop() {
  checkIncomingAttacks();
}

// Auto-démarrer le polling toutes les secondes
if(!window.incomingAttackInterval) {
  window.incomingAttackInterval = setInterval(incomingAttackLoop, 1000);
}
function simulateCombat(attackerPower=0, defenderPower=0, opts={}){
 attackerPower=Number(attackerPower||0);
 defenderPower=Number(defenderPower||0);
 const attackRoll=attackerPower*(0.85+Math.random()*0.30);
 const defenseRoll=defenderPower*(0.85+Math.random()*0.30);
 const victory=attackRoll>=defenseRoll;
 const lossRatio=victory?Math.min(.35, defenderPower/Math.max(1,attackerPower+defenderPower)*.45):Math.min(.85, defenderPower/Math.max(1,attackerPower)*.55);
 return {
  victory,
  attackerPower,
  defenderPower,
  attackRoll:Math.round(attackRoll),
  defenseRoll:Math.round(defenseRoll),
  attackerLossRatio:lossRatio,
  defenderLossRatio:victory?.65:.18,
  captured:victory?0:Math.max(0,Math.floor((opts.shipCount||0)*0.08)),
  ransom:victory?0:Math.max(0,Math.round(attackerPower*1.5))
 };
}

function processFleets(){
 const now=performance.now()/1000;let changed=false;
 for(const f of state.fleets){
  if(!f.done&&now-f.startTime>=f.duration){
   if(f.returning){
    f.done=true;changed=true;
    if(f.ships){for(const [id,n] of Object.entries(f.ships)){planetShips(f.originPlanetId||state.activePlanetId)[id]=(planetShips(f.originPlanetId||state.activePlanetId)[id]||0)+n}}
    const lootToCreditV6=f.pendingLoot||((f.mission==="attack"&&f.cargo&&((Number(f.cargo.titanium)||0)+(Number(f.cargo.xenite)||0)+(Number(f.cargo.antimatter)||0)+(Number(f.cargo.fragments)||0)>0))?f.cargo:null);
    if(lootToCreditV6&&typeof stellarionCreditLootToActivePlanet==="function"){
      const lootPlanetV6=f.originPlanetId||state.activePlanetId;
      stellarionCreditLootToActivePlanet(lootToCreditV6,{planetId:lootPlanetV6,source:"fleet_return"});
      addLog("Butin livré à la base : "+(typeof rewardText==="function"?rewardText(lootToCreditV6):"ressources récupérées")+".");
      f.pendingLoot=null;
      if(f.mission==="attack")f.cargo={titanium:0,xenite:0,antimatter:0,fragments:0};
    }
    addLog("Flotte revenue de "+(f.to&&f.to.name?f.to.name:"mission")+".");
    continue;
   }
   f.done=true;changed=true;
   if(f.mission==="scan"){
    const chance=scanSuccessChance(f.to,f);
    const roll=Math.random();
    const rep=planetProfile(f.to);
    if(roll<=chance){
      state.scanReports[f.to.id]=rep;
      state.scannedToday++;
      f.returnShips=true;
      addLog("Rapport complet reçu pour "+f.to.name+".");
      addMessage("scan","Rapport d’espionnage complet : "+f.to.name,scanReportBody(f.to,rep)+"\n\nRésultat : sonde revenue intacte.\nChance de réussite estimée : "+Math.round(chance*100)+"%.",{systemId:f.to.id,report:rep,success:true,to:playerNameForSystem(f.to),context:"scan"});
    } else if(roll<=chance+0.25){
      const partial={...rep,slots:{mining:"?",industrial:"?",military:"?",energy:"?",research:0},bonus:{label:"Inconnu"}};
      state.scannedToday++;
      addLog("Rapport partiel reçu : la sonde a été détruite.");
      addMessage("scan","Rapport partiel : "+f.to.name,
        "Reconnaissance interrompue.\\n\\n"+
        "La sonde a transmis un signal incomplet avant sa disparition.\\n\\n"+
        "Données récupérées :\\n"+
        "- Présence d’activité confirmée dans le système.\\n"+
        "- Niveau de menace : indéterminé.\\n"+
        "- Flotte ennemie : inconnue.\\n"+
        "- Commandements orbitales : inconnues.\\n"+
        "- Ressources et slots planétaires : non récupérés.\\n\\n"+
        "Conclusion : informations insuffisantes. Envoyer plusieurs sondes ou une flotte mieux protégée pourrait améliorer les chances de transmission.",
        {systemId:f.to.id,partial:true,to:playerNameForSystem(f.to),context:"scan"});
    } else {
      addLog("Signal perdu près de "+f.to.name+" : aucun rapport.");
      addMessage("scan","Signal perdu : "+f.to.name,
        "Votre sonde éclaireuse a disparu avant toute transmission.\\n\\n"+
        "Aucune donnée n’a été récupérée.\\n"+
        "Cause inconnue : interception, anomalie, défense orbitale ou destruction instantanée.\\n\\n"+
        "Statut : mystère total.",
        {systemId:f.to.id,destroyed:true,noIntel:true,to:playerNameForSystem(f.to),context:"scan"});
    }
   }
   else if(f.mission==="attack"){const result=simulateCombat(f.to,f.ships||{});f.returnShips=true;f.ships=result.playerRemaining;f.pendingLoot=result.loot||{};f.pendingLootLabel=f.to&&f.to.name?f.to.name:"combat";if(result.victory){state.hostileKills++;addLog("Victoire sur "+f.to.name+" : butin sécurisé, livraison au retour de la flotte.");if(Math.random()<.22){const drop=COSMETICS[Math.floor(Math.random()*COSMETICS.length)];state.cosmetics.push(drop);addLog("Drop : "+drop.icon+" "+drop.name+" ["+drop.rarity+"].")}}else{addLog("Défaite sur "+f.to.name+" : rapport dans la messagerie.");registerCapturedEquipment(f.to,result.playerLost||f.ships||{});}const isAiQuestReport=!!(f.to&&f.to.aiThreat);
if(isAiQuestReport&&typeof window.markThreatVictory1328==="function")window.markThreatVictory1328(f.to,result);
const reportTitle=(isAiQuestReport?"Mission galactique : ":"Rapport de combat : ")+f.to.name;
const reportBody=safeCombatReportBody(f.to,result)+(isAiQuestReport?"":"\n\nAction disponible : ouvre ce rapport puis clique sur Répondre / Envoyer message.");
addMessage("combat",reportTitle,reportBody,{systemId:f.to.id,result,to:playerNameForSystem(f.to),context:isAiQuestReport?"ai_quest":"combat"});} 
   else if(f.mission==="transfer"){addLog("Transfert livré à "+f.to.name+" : "+fmt((f.cargo&&f.cargo.titanium)||0)+" titane, "+fmt((f.cargo&&f.cargo.xenite)||0)+" xénite.")}
   else if(f.mission==="colonize"){const report=state.scanReports[f.to.id];if(report){const id="col_"+Date.now();const newPlanet={id,name:report.name,type:report.archetype,rarity:report.rarity,isHomeworld:false,slots:report.slots,bonus:report.bonus}; reserveUniqueCoord(newPlanet,getPersistentCoord(activePlanet()),8); newPlanet.x=Math.round(Number(newPlanet.galaxyX)||0); newPlanet.y=Math.round(Number(newPlanet.galaxyY)||0); state.planets.push(newPlanet);state.buildings[id]=[{building_id:"command_center",level:1}];state.colonies++;addLog("Colonie fondée : "+report.name+" ["+report.rarity+"].")}else addLog("Colonisation échouée : rapport absent.")}
   else {state.resources.artifacts++;state.explored++;addLog("Exploration terminée : +1 artefact.")}
   if(f.ships && (f.mission!=="scan" || f.returnShips)){
    f.done=false;
     f.returning=true;
     f.startTime=now;
     f.duration=Math.max(6,Math.round((f.duration||10)*0.75));
     try{publishPublicMissionV1(f,true);}catch(e){}
     addLog("Retour en cours depuis "+(f.to&&f.to.name?f.to.name:"mission")+".");
   }
  }
 }
 if(changed){state.fleets=state.fleets.filter(f=>!f.done);save();render()}
}
function buildCommandement(id){
 const def=DEFENSES.find(d=>d.id===id), c=def.cost;
 if(!isCommandementUnlocked(id,state.activePlanetId)){addLog("Commandement bloquée : prérequis non validés.");render();return}
 if(state.resources.titanium<c.titanium||state.resources.xenite<c.xenite||state.resources.antimatter<c.antimatter){addLog("Ressources insuffisantes pour "+def.name+".");render();return}
 state.resources.titanium-=c.titanium;state.resources.xenite-=c.xenite;state.resources.antimatter-=c.antimatter;
 state.defenses[id]=(state.defenses[id]||0)+1;
 addLog(def.name+" construite sur Nova Prime.");
 save();render();
}
function defenseHtml(d){
 const c=d.cost;
 const unlocked=isCommandementUnlocked(d.id,state.activePlanetId);
 const ok=unlocked&&state.resources.titanium>=c.titanium&&state.resources.xenite>=c.xenite&&state.resources.antimatter>=c.antimatter;
 return `<div class="ship-compact-card ${unlocked?"":"locked-card"}">
  <div>
   <strong>${d.icon} ${d.name}</strong>
   <div class="ship-compact-meta">Commandement planétaire · possédé : ${state.defenses[d.id]||0}</div>
   <div class="ship-compact-stats"><span>⚔️ ${fmt(d.attack||0)}</span><span>🛡️ ${fmt(d.hull||0)}</span><span>⚡ ${fmt(d.energy||0)}</span></div>
   <div class="tiny muted" style="margin-top:5px">${fmt(c.titanium)} Ti · ${fmt(c.xenite)} Xe · ${fmt(c.antimatter||0)} AM</div>
   ${unlocked?"":`<span class="unlock-pill">🔒 À débloquer</span>`}
   ${requirementsHtml(defenseRequirement(d.id),state.activePlanetId)}
  </div>
  <button class="btn" ${!ok?"disabled":""} onclick="buildCommandement('${d.id}')">${unlocked?"Construire":"Bloqué"}</button>
 </div>`;
}

function buildShip(id){
 const ship=SHIPS.find(s=>s.id===id), c=ship.cost;
 // Déblocage appliqué uniquement à la construction locale.
 // Ne pas réutiliser ce test pour les renforts alliés : voir ALLY_REINFORCEMENT_RULES.
 if(!isShipUnlocked(id,state.activePlanetId)){addLog("Vaisseau bloqué : prérequis non validés.");render();return}
 if(state.resources.titanium<c.titanium||state.resources.xenite<c.xenite||state.resources.antimatter<c.antimatter){addLog("Ressources insuffisantes pour "+ship.name+".");render();return}
 const shipyard=(state.buildings[state.activePlanetId]||[]).find(b=>b.building_id==="shipyard")?.level||0;
 if(shipyard<=0 && id!=="scout_probe"){addLog("Chantier Spatial requis pour former ce vaisseau.");render();return}
 const cap=canStoreShipsOnPlanet(state.activePlanetId,id,1);
 if(!cap.ok){addLog("Base Orbitale pleine sur "+activePlanet().name+" : "+cap.used+"/"+cap.cap+" capacité utilisée. Améliore la Base Orbitale pour stationner plus de vaisseaux.");render();return}
 state.resources.titanium-=c.titanium;state.resources.xenite-=c.xenite;state.resources.antimatter-=c.antimatter;
 const now=Date.now(),starts=state.shipQueue.length?Math.max(...state.shipQueue.map(q=>q.finishAt)):now,speedBonus=Math.max(1,1+shipyard*0.04),duration=Math.max(12,Math.round(ship.time/speedBonus))*1000;
 const existing=state.shipQueue.find(q=>q.planetId===state.activePlanetId&&q.ship_id===id);
 if(existing){
  existing.qty=(existing.qty||1)+1;
  existing.duration=(existing.duration||duration)+duration;
  existing.finishAt+=duration;
 }else{
  state.shipQueue.push({id:"sq"+now+Math.random(),planetId:state.activePlanetId,ship_id:id,qty:1,startAt:starts,finishAt:starts+duration,duration});
 }
 addLog(ship.name+" ajouté/regroupé dans la file de formation sur "+activePlanet().name+".");save();render();
}

function buildingNodeClass(id){
 if(id==="embassy")return "node-embassy";
 if(id.startsWith("titanium_mine_")){const n=parseInt(id.split("_").pop(),10)||2;return "node-titanium node-titanium-extra"+n;}
 if(id.startsWith("xenite_extractor_")){const n=parseInt(id.split("_").pop(),10)||2;return "node-xenite node-xenite-extra"+n;}
 const map={command_center:"node-command",titanium_mine:"node-titanium",xenite_extractor:"node-xenite",fusion_plant:"node-fusion",antimatter_refinery:"node-antimatter",quantum_lab:"node-lab",academy:"node-academy",shipyard:"node-shipyard",shield_generator:"node-shield",orbital_base:"node-orbital_base"};
 return map[id]||"node-command";
}
function activeBuildingRow(id){
 const rows=state.buildings[state.activePlanetId]||[];
 return rows.find(b=>b.building_id===id)||{building_id:id,level:0};
}
function queuedForBuilding(id){
 return state.buildQueue.filter(q=>q.planetId===state.activePlanetId&&q.building_id===id).length;
}
function buildingUpgradeInfo(def){
 ensureBuildingCatalogForPlanet(state.activePlanetId);
 const row=activeBuildingRow(def.id);
 const queued=queuedForBuilding(def.id);
 const effective=(row.level||0)+queued;
 const next=effective+1;
 const c=cost(def,next);
 const allowed=canBuildOnPlanet(def,activePlanet());
 const max=false;
 const ok=allowed.ok&&state.resources.titanium>=c.titanium&&state.resources.xenite>=c.xenite&&state.resources.antimatter>=(c.antimatter||0)&&state.buildQueue.filter(q=>q.planetId===state.activePlanetId).length<canQueue();
 return {row,queued,effective,next,c,allowed,max,ok};
}
function buildingNodeProduction(def, level){
 const p=activePlanet();
 if(def.produces==="titanium")return {text:"+"+fmt(resourceProduction(def.baseRate,level)*(1+(p.bonus.titanium||0)))+" Ti/h",kind:"res"};
 if(def.produces==="xenite")return {text:"+"+fmt(resourceProduction(def.baseRate,level)*(1+(p.bonus.xenite||0)))+" Xe/h",kind:"res"};
 if(def.produces==="antimatter")return {text:"+"+fmt(resourceProduction(def.baseRate,level))+" AM/h",kind:"res"};
 if(def.produces==="energy")return {text:"+"+fmt(energyProduction(level)*(1+(p.bonus.energy||0)))+" MW",kind:"energy"};
 if(def.id==="embassy")return {text:"Récolte max niv. "+(level||0),kind:"none"};
 return {text:slotName(def.slot),kind:"none"};
}
function constructionBuildingsForPlanet(){
 const p=activePlanet();
 const spots=ensureHarvestSpots(p);
 const groupWeight={energy:10,administration:20,support:30,economy:40,military:50,orbital:55,defense:60,research:70};
 return BUILDINGS.filter(def=>{
  if(isHarvestBuilding(def))return def.variantIndex <= (spots[def.mineType]||0);
  if(def.slot==="research"&&!p.isHomeworld)return false;
  return true;
 }).sort((a,b)=>{
  const ga=groupWeight[a.category]||99, gb=groupWeight[b.category]||99;
  if(ga!==gb)return ga-gb;
  if(isHarvestBuilding(a)&&isHarvestBuilding(b)){
   if(a.mineType!==b.mineType)return a.mineType==="titanium"?-1:1;
   return (a.variantIndex||1)-(b.variantIndex||1);
  }
  return String(a.name).localeCompare(String(b.name),'fr');
 });
}
function buildingNodeHtml(def){
 const info=buildingUpgradeInfo(def);
 const selected=state.selectedBuildingId===def.id;
 const prod=buildingNodeProduction(def,info.row.level||0);
 return `<div class="building-node ${buildingNodeClass(def.id)} ${selected?"selected":""}" onclick="__stellarionKeepConstructionScroll(()=>{state.selectedBuildingId='${def.id}';save();render()})">
  <span class="ico">${def.icon}</span>
  <strong>${def.name}</strong>
  <div class="lvl">Niv. ${info.row.level||0}/∞${info.queued?` · +${info.queued}`:""}</div>
  <div class="node-prod ${prod.kind==="energy"?"energy":(prod.kind==="none"?"none":"")}">${prod.text}</div>
  <div class="cost">${info.max?"MAX":`${fmt(info.c.titanium)} Ti · ${fmt(info.c.xenite)} Xe`}</div>
 </div>`;
}

function buildingBlockReason(def,info){
 if(info.max)return "Niveau maximum atteint";
 if(!info.allowed.ok)return info.allowed.reason;
 const miss=[];
 if(state.resources.titanium<info.c.titanium)miss.push(`${fmt(info.c.titanium-state.resources.titanium)} Titane`);
 if(state.resources.xenite<info.c.xenite)miss.push(`${fmt(info.c.xenite-state.resources.xenite)} Xénite`);
 if(state.resources.antimatter<(info.c.antimatter||0))miss.push(`${fmt((info.c.antimatter||0)-state.resources.antimatter)} Antimatière`);
 return miss.length?`Ressources manquantes : ${miss.join(" · ")}`:"Prêt";
}

