function constructionLevelMax(def){
 if(isHarvestBuilding(def)){
  const emb=activeBuildingRow('embassy');
  return emb ? (emb.level||0) : 0;
 }
 return '∞';
}
function productionValueForDef(def, level){
 const p=activePlanet();
 if(def.produces==='titanium') return resourceProduction(def.baseRate,level)*(1+(p.bonus.titanium||0));
 if(def.produces==='xenite') return resourceProduction(def.baseRate,level)*(1+(p.bonus.xenite||0));
 if(def.produces==='antimatter') return resourceProduction(def.baseRate,level);
 if(def.produces==='energy') return energyProduction(level)*(1+(p.bonus.energy||0));
 return 0;
}
function productionUnitForDef(def){return def.produces==='energy'?' MW':'/h'}
function productionLabelForDef(def, level){
 const v=productionValueForDef(def,level);
 if(def.produces) return '+'+fmt(v)+productionUnitForDef(def);
 if(def.id==='embassy') return 'Plafond récolte : niv. '+(level||0);
 if(def.id==='shipyard') return 'Construction vaisseaux';
 if(def.id==='orbital_base') return 'Vitesse flotte +'+orbitalBaseSpeedBonus(state.activePlanetId)+'%';
 if(def.id==='shield_generator') return 'Puissance bouclier';
 if(def.id==='quantum_lab') return 'Vitesse recherche';
 if(def.id==='academy') return 'Déblocages avancés';
 if(def.id==='command_center') return 'Gestion planète';
 return slotName(def.slot);
}
function buildCardHtml(def, kind='standard'){
 const info=buildingUpgradeInfo(def);
 const level=info.row.level||0;
 const max=constructionLevelMax(def);
 const selected=state.selectedBuildingId===def.id;
 const cur=productionLabelForDef(def,level);
 const nextProd = def.produces ? productionValueForDef(def, info.next) : 0;
 const curProd = def.produces ? productionValueForDef(def, level) : 0;
 const gain = def.produces ? Math.max(0,nextProd-curProd) : 0;
 const blocked = !info.allowed.ok;
 const title = def.name.replace('Extracteur de Xénite','Extracteur Xénite');
 return `<div class="build-card ${kind} ${selected?'selected':''} ${blocked?'blocked':''}" onclick="__stellarionKeepConstructionScroll(()=>{state.selectedBuildingId='${def.id}';save();render()})">
   <div class="build-name">${title}</div>
   <div class="build-img">${def.icon}</div>
   <div class="build-level">Niveau ${level} / ${max}</div>
   <div class="build-prod">${cur}</div>
   <div class="build-meta">${def.produces?`Prochain : +${fmt(nextProd)}${productionUnitForDef(def)}<br><span class='ok'>Gain +${fmt(gain)}${productionUnitForDef(def)}</span>`:productionLabelForDef(def,level)}</div>
   <div>
    <button class="btn build-action" ${info.max?'disabled':''} onclick="event.stopPropagation();queueBuilding('${def.id}')">Améliorer</button>
    <div class="build-cost"><span>🏗️ ${fmt(info.c.titanium)}</span><span>💠 ${fmt(info.c.xenite)}</span></div>
   </div>
  </div>`;
}
function emptySpotCard(type, i, available){
 return `<div class="build-card empty ${available?'available':''}"><div><div class="plus">+</div><div>${available?'Emplacement disponible':'Emplacement inexistant'}</div>${available?`<div class='small muted'>Coût de base<br>🏗️ 150 · 💠 75</div>`:''}</div></div>`;
}
function harvestGroupHtml(type){
 const spots=ensureHarvestSpots(activePlanet());
 const max=spots[type]||0;
 const defs=BUILDINGS.filter(b=>isHarvestBuilding(b)&&b.mineType===type).sort((a,b)=>(a.variantIndex||1)-(b.variantIndex||1));
 const label=type==='titanium'?'MINES DE TITANE':'EXTRACTEURS DE XÉNITE';
 const icon=type==='titanium'?'⛏️':'💠';
 let cards='';
 for(let i=1;i<=ECONOMY_V2.maxHarvestSpots;i++){
  if(i<=max){
   const def=defs.find(d=>(d.variantIndex||1)===i);
   if(def) cards+=buildCardHtml(def,type);
  }else cards+=emptySpotCard(type,i,false);
 }
 return `<div class="harvest-group ${type}"><h3>${icon} ${label} (${max} / ${ECONOMY_V2.maxHarvestSpots})</h3><div class="harvest-cards">${cards}</div><div class="tiny muted" style="text-align:center;margin-top:8px">Niveau maximum déterminé par l'Ambassade.</div></div>`;
}
