/* Alpha 1.5.30 — Planet Switch Global Fix
   Source unique pour changer de planète. */
function activePlanetIndex(){
 state.planets = Array.isArray(state.planets) && state.planets.length ? state.planets : [];
 const idx=state.planets.findIndex(p=>p.id===state.activePlanetId);
 return idx>=0?idx:0;
}
function normalizePlanets1512(){
 state.planets = Array.isArray(state.planets) && state.planets.length ? state.planets : [
  {id:"home",name:"Nova Prime",type:"homeworld",rarity:"Home",isHomeworld:true,x:0,y:0,sector:1,system:1,slots:{mining:2,industrial:2,military:1,orbital:1,defense:1,energy:1,research:2},bonus:{label:"Planète mère",titanium:0,xenite:0,energy:0}}
 ];
 if(!state.activePlanetId || !state.planets.find(p=>p.id===state.activePlanetId)){
  state.activePlanetId=state.planets[0].id;
 }
 return state.planets;
}
function __setActivePlanetCore(id){
 const planets=normalizePlanets1512();
 const target=planets.find(p=>p.id===id);
 if(!target){
  addLog("Planète introuvable : "+id);
  save();
  render();
  return false;
 }
 const previous=state.activePlanetId;
 if(previous===target.id){
  state.activePlanetId=target.id;
  if(typeof syncActiveResources==="function")syncActiveResources();
  save();
  render();
  return true;
 }
 if(typeof commitActiveResources==="function")commitActiveResources();
 state.activePlanetId=target.id;
 if(typeof syncActiveResources==="function")syncActiveResources();
 if(state.view==="galaxy" && typeof activePlanetSystem==="function"){
  try{state.selected=activePlanetSystem()}catch(e){}
 }
 save();
 render();
 return true;
}
function setActivePlanet(id){
 const ok=__setActivePlanetCore(id);
 if(ok && state.view==="galaxy" && typeof gwmCenterOnPlanetId==="function"){
  try{requestAnimationFrame(()=>gwmCenterOnPlanetId(id,true))}catch(e){}
 }
 return ok;
}
function switchPlanet(delta){
 const planets=normalizePlanets1512();
 if(planets.length<=1){
  addLog("Aucune autre planète disponible.");
  render();
  return false;
 }
 const idx=activePlanetIndex();
 const next=(idx+(parseInt(delta)||0)+planets.length)%planets.length;
 return setActivePlanet(planets[next].id);
}
