function orbitStyle(index,pid){
 const duration={o1:28,o2:42,o3:64}[index] ?? 36;
 const seed=String(pid||"").split("").reduce((a,c)=>a+c.charCodeAt(0),0)%duration;
 const elapsed=(Date.now()/1000 + seed)%duration;
 return `--orbit-duration:${duration}s;--orbit-delay:${-elapsed}s`;
}


function orbitRuntimeSeed(pid){
 return String(pid||"").split("").reduce((a,c)=>a+c.charCodeAt(0),0);
}
function startPlanetOrbitRuntime(){/* CSS orbit handles visible motion. */}


function forceVisibleOrbitMotion(){
 if(window._stellarionForceOrbitRaf)cancelAnimationFrame(window._stellarionForceOrbitRaf);
 const seedFor=(pid)=>String(pid||"").split("").reduce((a,c)=>a+c.charCodeAt(0),0);
 const tick=()=>{
  if(state.view==="planet"){
   const wrap=document.querySelector(".rotating-planet-wrap.clean");
   const planet=document.querySelector(".rotating-planet-wrap.clean .rotating-planet");
   if(wrap&&planet){
    const pr=planet.getBoundingClientRect();
    const base=Math.max(pr.width,pr.height)/2;
    const now=performance.now()/1000;
    const cfg={
     1:{r:base+42,speed:.58,base:.2,spin:0},
     2:{r:base+86,speed:-.38,base:2.1,spin:32},
     3:{r:base+128,speed:.25,base:4.2,spin:-18}
    };
    document.querySelectorAll(".orbit-apparat").forEach(el=>{
     const id=Number(el.dataset.apparat||1);
     const pid=el.dataset.planetId||"";
     const c=cfg[id]||cfg[1];
     const seed=(seedFor(pid)%360)*Math.PI/180;
     const angle=c.base+seed+now*c.speed;
     const x=Math.cos(angle)*c.r;
     const y=Math.sin(angle)*c.r;
     const tangent=(angle*180/Math.PI)+(c.speed>=0?90:-90);
     const selfSpin=id===1?tangent:(now*c.spin);
     el.style.transform=`translate(${x}px, ${y}px) rotate(${selfSpin}deg)`;
    });
   }
  }
  window._stellarionForceOrbitRaf=requestAnimationFrame(tick);
 };
 tick();
}

function planetAuraClass(p){
 if(p.bonus&&p.bonus.energy)return "water";
 if(p.bonus&&p.bonus.artifacts)return "relic";
 if(p.bonus&&p.bonus.titanium)return "fire";
 if(!p.isHomeworld)return "void";
 return "water";
}
