/* Alpha 1.3.65 — Source coordonnée fiable des planètes possédées
   Racine du bug : certaines colonies ont galaxyX/galaxyY mais pas p.x/p.y.
   La carte utilisait p.x/p.y, donc la colonie pouvait disparaître. */
function stellarionNormalizeCoordValue(v){
 const n=Number(v);
 if(!Number.isFinite(n))return null;
 if(Math.abs(n)<=200)return Math.round(n);
 // Anciens formats rencontrés : coord*18 ou coord*90.
 if(Math.abs(n)>5000)return Math.round(n/90);
 return Math.round(n/18);
}
function stellarionOwnedPlanetCoord(p){
 if(!p)return {x:0,y:0};

 // 1) Source moderne fiable.
 if(Number.isFinite(Number(p.galaxyX))&&Number.isFinite(Number(p.galaxyY))){
  return {x:Math.round(Number(p.galaxyX)),y:Math.round(Number(p.galaxyY))};
 }

 // 2) Si le panneau / la sélection connaît la planète, on récupère sa vraie position.
 try{
  const s=state&&state.selected;
  if(s&&(s.planetId===p.id||s.name===p.name)){
   if(Number.isFinite(Number(s.galaxyX))&&Number.isFinite(Number(s.galaxyY))){
    return {x:Math.round(Number(s.galaxyX)),y:Math.round(Number(s.galaxyY))};
   }
   if(Number.isFinite(Number(s.x))&&Number.isFinite(Number(s.y))){
    return {x:stellarionNormalizeCoordValue(s.x),y:stellarionNormalizeCoordValue(s.y)};
   }
  }
 }catch(e){}

 // 3) Ancien format p.x/p.y.
 if(Number.isFinite(Number(p.x))&&Number.isFinite(Number(p.y))){
  return {x:stellarionNormalizeCoordValue(p.x),y:stellarionNormalizeCoordValue(p.y)};
 }

 // 4) Si c'est la planète active et que la caméra est dessus, on sauve la coordonnée.
 try{
  if(state&&state.activePlanetId===p.id&&state.uiState&&state.uiState.gwmCamera){
   const cam=state.uiState.gwmCamera;
   if(Number.isFinite(Number(cam.x))&&Number.isFinite(Number(cam.y))){
    return {x:Math.round(Number(cam.x)),y:Math.round(Number(cam.y))};
   }
  }
 }catch(e){}

 return {x:0,y:0};
}
function stellarionRepairOwnedPlanetCoordinates(silent=true){
 try{
  if(!state||!Array.isArray(state.planets))return false;
  let changed=false;
  for(const p of state.planets){
   if(!p)continue;
   const c=stellarionOwnedPlanetCoord(p);
   if(!Number.isFinite(Number(c.x))||!Number.isFinite(Number(c.y)))continue;

   if(Math.round(Number(p.galaxyX))!==c.x||Math.round(Number(p.galaxyY))!==c.y){
    p.galaxyX=c.x;
    p.galaxyY=c.y;
    changed=true;
   }

   // Pour compatibilité ancienne : p.x/p.y restent en coordonnées simples, pas en pixels.
   if(!Number.isFinite(Number(p.x))||!Number.isFinite(Number(p.y))||Math.abs(Number(p.x))>200||Math.abs(Number(p.y))>200){
    p.x=c.x;
    p.y=c.y;
    changed=true;
   }
  }
  if(changed){
   try{save&&save()}catch(e){}
   if(!silent&&typeof addLog==="function")addLog("Coordonnées colonies réparées.");
  }
  return changed;
 }catch(e){return false}
}

