function getBuildingLevel(pid,bid){
 const row=(state.buildings[pid]||[]).find(b=>b.building_id===bid);
 return row?Number(row.level||0):0;
}
function orbitalBaseLevel(pid){
 return getBuildingLevel(pid,"orbital_base");
}
function orbitalBaseSpeedBonus(pid){
 const lvl=orbitalBaseLevel(pid);
 // Nouvelle règle : plus de limite de stationnement.
 // La Base Orbitale devient un centre de logistique/hypernavigation.
 // Bonus volontairement fort mais progressif : niveau 0 = +0%, niveau 10 ≈ +75%, niveau 30 ≈ +225%.
 return Math.round((Math.pow(Math.max(0,lvl),0.92)*9.5)*10)/10;
}
function orbitalBaseSpeedMultiplier(pid){
 return 1 + orbitalBaseSpeedBonus(pid)/100;
}
function orbitalBaseNextSpeedGain(pid){
 const lvl=orbitalBaseLevel(pid);
 const now=orbitalBaseSpeedBonus(pid);
 const nextLvl=Math.min(30,lvl+1);
 const fake=Math.round((Math.pow(Math.max(0,nextLvl),0.92)*9.5)*10)/10;
 return Math.max(0,Math.round((fake-now)*10)/10);
}
function orbitalBaseTravelDuration(pid,dist,mission){
 const lvl=orbitalBaseLevel(pid);
 const mult=orbitalBaseSpeedMultiplier(pid);
 const missionFactor=mission==="scan"?.72:mission==="transfer"?1.05:mission==="colonize"?1.25:1;
 // Rework temps de trajet :
 // Avant : très court et plafonné à 70 s.
 // Maintenant : la distance compte vraiment, puis la Base Orbitale réduit le temps.
 const raw=(45 + Math.pow(Math.max(1,dist),0.92)/4.8) * missionFactor;
 const duration=raw/mult;
 return Math.max(25,Math.min(900,Math.round(duration)));
}
function orbitalBaseCapacity(pid){
 // Compatibilité interne seulement : aucune limite réelle.
 return Number.POSITIVE_INFINITY;
}
function orbitalBaseNextGain(pid){
 // Compatibilité ancienne UI : la capacité n'existe plus.
 return 0;
}
function shipUnitSize(id){
 const values={
  scout_probe:1,
  small_cargo:2,
  light_fighter:2,
  interceptor:2,
  large_cargo:5,
  heavy_fighter:4,
  frigate:6,
  cruiser:8,
  battleship:12,
  destroyer:16,
  bomber:14,
  siege_cruiser:20,
  titan:60,
  carrier:75,
  mothership:180,
  colon_ship:30
 };
 return values[id]||1;
}
function shipStationLabel(id){
 return "Stationnement illimité";
}
function planetShips(pid){
 state.planetShips=state.planetShips||{};
 state.planetShips[pid]=state.planetShips[pid]||{};
 return state.planetShips[pid];
}
function activePlanetShips(){return planetShips(state.activePlanetId)}
function planetShipUsage(pid){
 let used=0;for(const [id,n] of Object.entries(planetShips(pid))){used+=shipUnitSize(id)*(Number(n)||0)}return used;
}
function canStoreShipsOnPlanet(pid,shipId,qty){
 const used=planetShipUsage(pid),add=shipUnitSize(shipId)*(Number(qty)||0);
 return {ok:true,used,cap:Number.POSITIVE_INFINITY,add,unlimited:true,reason:"Stationnement illimité"};
}
function migrateGlobalShipsToPlanets(){
 state.planetShips=state.planetShips||{};
 if(!state._shipsMigratedToPlanets){
  state.planetShips[state.activePlanetId||"home"]={...(state.ships||{})};
  state.ships={};
  state._shipsMigratedToPlanets=true;
 }
 for(const p of state.planets||[]){state.planetShips[p.id]=state.planetShips[p.id]||{}}
}
function baseCapacityHtml(pid){
 const used=planetShipUsage(pid);
 const lvl=orbitalBaseLevel(pid);
 const bonus=orbitalBaseSpeedBonus(pid);
 const mult=orbitalBaseSpeedMultiplier(pid);
 const nextGain=orbitalBaseNextSpeedGain(pid);
 const pct=Math.max(0,Math.min(100,Math.round(bonus/225*100)));
 return `<div class="base-capacity-card orbital-speed-card">
  <strong>🛰️ Base Orbitale — Hypernavigation</strong>
  <div class="small muted">Niveau ${lvl}/30 · stationnement illimité · vitesse flotte x${mult.toFixed(2)}</div>
  <div class="base-capacity-bar"><div style="width:${pct}%"></div></div>
  <div class="tiny muted">Bonus actuel : +${bonus}% vitesse. Prochain niveau : +${nextGain}% vitesse.</div>
  <div class="base-capacity-details">
   <div><strong>🚀 Déplacement</strong><br><span class="tiny muted">temps de trajet réduit</span></div>
   <div><strong>📦 Flotte stationnée</strong><br><span class="tiny muted">${fmt(used)} capacité utilisée · aucune limite</span></div>
   <div><strong>🛸 Grandes flottes</strong><br><span class="tiny muted">plus aucun blocage de hangar</span></div>
   <div><strong>🌌 Longue distance</strong><br><span class="tiny muted">trajets de base plus longs</span></div>
  </div>
 </div>`;
}

function shipPowerValue(id){
 const def=SHIPS.find(s=>s.id===id);
 if(!def)return 0;
 return Math.round((def.attack||0)*1.15 + (def.hull||0)*0.08 + (def.cargo||0)*0.002);
}
function planetFleetPower(pid){
 const ships=planetShips ? planetShips(pid) : (state.ships||{});
 let total=0;
 for(const [id,n] of Object.entries(ships||{})) total+=shipPowerValue(id)*(Number(n)||0);
 return Math.round(total);
}
function planetCommandementPower(pid){
 const shield=getBuildingLevel ? getBuildingLevel(pid,"shield_generator") : 0;
 const base=getBuildingLevel ? getBuildingLevel(pid,"orbital_base") : 0;
 const command=getBuildingLevel ? getBuildingLevel(pid,"command_center") : 0;
 return Math.round(shield*85 + base*45 + command*20);
}
function planetTotalPower(pid){
 return planetFleetPower(pid)+planetCommandementPower(pid);
}

/* Alpha 1.5.30 — liaison directe image planète galaxie -> panneaux droite */
function galaxyLinkedPlanetData1399(p=activePlanet()){
 const c=(typeof stellarionOwnedPlanetCoord==="function")?stellarionOwnedPlanetCoord(p):{x:(p.galaxyX??p.x??0),y:(p.galaxyY??p.y??0)};
 const x=Math.round(Number(c.x)||0), y=Math.round(Number(c.y)||0);
 let mapPlanet=null;
 try{ if(typeof gwmPlanetAt==="function") mapPlanet=gwmPlanetAt(x,y); }catch(e){}
 if(!mapPlanet || !mapPlanet.owned || mapPlanet.planetId!==p.id){
  mapPlanet={...p,kind:"player",name:p.name,owned:true,planetId:p.id,hostile:false,type:p.isHomeworld?"home":"owned_colony",galaxyX:x,galaxyY:y,x:x,y:y};
 }else{
  mapPlanet={...mapPlanet,planetId:p.id,owned:true,galaxyX:x,galaxyY:y,x:x,y:y};
 }
 let asset=null;
 try{ if(typeof vlibAssetFor==="function") asset=vlibAssetFor(mapPlanet,x,y); }catch(e){}
 return {p,x,y,coord:(typeof gwmCoordText==="function"?gwmCoordText(x,y):`[${x} | ${y}]`),mapPlanet,asset};
}
function galaxyLinkedPlanetVisual1399(p=activePlanet(), extraClass=""){
 const d=galaxyLinkedPlanetData1399(p);
 const asset=d.asset||{};
 const kind=(typeof gwmKind==="function")?gwmKind(d.mapPlanet,d.x,d.y):(d.p.isHomeworld?"ocean":"crystal");
 const signature=asset.signature||"leviathan";
 // Important : priorité à asset.html, exactement comme la carte galaxie.
 // Si asset.src est vide, on ne crée PAS d'image cassée.
 const visual=asset.html
  ? asset.html
  : (asset.src
    ? `<img class="gwm-planet-img" src="${asset.src}" alt="${d.p.name}">`
    : `<div class="gwm-planet ${kind}"></div>`);
 return `<div class="right-galaxy-linked-preview ${extraClass}" data-planet-id="${d.p.id}" data-coord="${d.coord}">
  <div class="right-galaxy-linked-object ${d.mapPlanet.owned?"owned":""}">
   <div class="gwm-asset-signature ${signature}"></div>
   <div class="gwm-asset-wrap">${visual}</div>
  </div>
 </div>`;
}
