function armamentOpsDraft(){
 state.armamentOpsDraft=state.armamentOpsDraft||{
  from:state.activePlanetId,
  coord:"",
  mission:"attack",
  ships:{},
  cargo:{titanium:0,xenite:0,antimatter:0}
 };
 state.armamentOpsDraft.ships=state.armamentOpsDraft.ships||{};
 state.armamentOpsDraft.cargo=state.armamentOpsDraft.cargo||{titanium:0,xenite:0,antimatter:0};
 if(!state.armamentOpsDraft.from)state.armamentOpsDraft.from=state.activePlanetId;
 return state.armamentOpsDraft;
}
function setArmamentOpsField(k,v){
 const d=armamentOpsDraft();
 d[k]=v;
 rerenderPreserveScroll();
}
function setArmamentOpsShip(id,val){
 const d=armamentOpsDraft();
 const from=d.from||state.activePlanetId;
 const max=(planetShips(from)||{})[id]||0;
 d.ships[id]=Math.max(0,Math.min(max,parseInt(val||0)||0));
 rerenderPreserveScroll();
}
function armamentOpsShipDelta(id,delta){
 const d=armamentOpsDraft();
 setArmamentOpsShip(id,((d.ships||{})[id]||0)+delta);
}
function armamentOpsShipMax(id){
 const d=armamentOpsDraft();
 const from=d.from||state.activePlanetId;
 setArmamentOpsShip(id,(planetShips(from)||{})[id]||0);
}
function setArmamentOpsCargo(k,val){
 const d=armamentOpsDraft();
 d.cargo[k]=Math.max(0,parseInt(val||0)||0);
 rerenderPreserveScroll();
}
function parseCoordInput(txt){
 const m=String(txt||"").match(/-?\d+/g);
 if(!m||m.length<2)return null;
 return {x:parseInt(m[0]),y:parseInt(m[1])};
}
function findTargetByCoord(txt){
 const c=parseCoordInput(txt);
 if(!c)return null;
 const all=[...(state.systems||[]),...(state.planets||[])];
 return all.find(o=>{
  const pc=getPersistentCoord(o,false);
  return pc && Number(pc.galaxyX)===c.x && Number(pc.galaxyY)===c.y;
 })||{id:"coord_"+c.x+"_"+c.y,name:"Position "+coordTextFromXY(c.x,c.y),galaxyX:c.x,galaxyY:c.y,x:c.x*90,y:c.y*90,type:"unknown",sector:"?",system:"?",enemyPower:0,counterIntel:0,danger:1,richness:1};
}
function armamentOpsSelectedShips(){
 const d=armamentOpsDraft();
 const from=d.from||state.activePlanetId;
 const out={};
 for(const s of SHIPS){
  const max=(planetShips(from)||{})[s.id]||0;
  const n=Math.max(0,Math.min(max,parseInt((d.ships||{})[s.id]||0)||0));
  if(n>0)out[s.id]=n;
 }
 return out;
}
function armamentOpsPower(){
 const ships=armamentOpsSelectedShips();
 let attack=0,cargo=0,count=0,hasScout=false,hasCombat=false,hasCargo=false;
 for(const [id,n] of Object.entries(ships)){
  const s=SHIPS.find(x=>x.id===id);
  if(!s)continue;
  attack+=(s.attack||0)*n;
  cargo+=(s.cargo||0)*n;
  count+=n;
  if(id==="scout_probe")hasScout=true;
  if((s.attack||0)>0)hasCombat=true;
  if((s.cargo||0)>0)hasCargo=true;
 }
 return {attack,cargo,count,hasScout,hasCombat,hasCargo};
}
function armamentOpsCargoTotal(){
 const c=armamentOpsDraft().cargo||{};
 return (Number(c.titanium)||0)+(Number(c.xenite)||0)+(Number(c.antimatter)||0);
}
function armamentOpsShipSelectorHtml(){
 const d=armamentOpsDraft();
 const from=d.from||state.activePlanetId;
 const ships=planetShips(from);
 const rows=SHIPS.map(s=>{
  const owned=ships[s.id]||0;
  if(owned<=0)return "";
  const qty=(d.ships||{})[s.id]||0;
  return `<div class="ops-ship-line">
   <div>
    <strong>${s.icon} ${s.name}</strong>
    <div class="tiny muted">Disponible : ${owned} · attaque ${fmt(s.attack||0)} · cargo ${fmt(s.cargo||0)}</div>
   </div>
   <div>
    <div class="ops-qty-controls">
     <button class="btn btn-ghost" onclick="armamentOpsShipDelta('${s.id}',-1)">−</button>
     <input type="number" min="0" max="${owned}" value="${qty}" onchange="setArmamentOpsShip('${s.id}',this.value)">
     <button class="btn btn-ghost" onclick="armamentOpsShipDelta('${s.id}',1)">+</button>
    </div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:4px;margin-top:4px">
     <button class="btn btn-ghost" style="padding:5px" onclick="armamentOpsShipMax('${s.id}')">Max</button>
     <button class="btn btn-ghost" style="padding:5px" onclick="setArmamentOpsShip('${s.id}',0)">0</button>
    </div>
   </div>
  </div>`;
 }).join("");
 return `<div class="ops-ship-selector">${rows||`<p class="small muted">Aucun vaisseau disponible sur la planète de départ.</p>`}</div>`;
}
function launchArmamentOperation(){
 const d=armamentOpsDraft();
 const fromP=(state.planets||[]).find(p=>p.id===d.from)||activePlanet();
 const target=findTargetByCoord(d.coord);
 const ships=armamentOpsSelectedShips();
 const power=armamentOpsPower();
 const cargoTotal=armamentOpsCargoTotal();
 if(!target){addLog("Coordonnée cible invalide. Exemple : [46 ; 32].");render();return}
 if(power.count<=0){addLog("Aucun vaisseau sélectionné.");render();return}
 if(d.mission==="scan"&&!power.hasScout){addLog("Espionnage impossible : sélectionne au moins une sonde.");render();return}
 if(d.mission==="attack"&&!power.hasCombat){addLog("Attaque impossible : sélectionne au moins un vaisseau offensif.");render();return}
 if((d.mission==="support"||d.mission==="transfer")&&cargoTotal>0&&!power.hasCargo){addLog("Transport impossible : sélectionne un vaisseau avec cargo.");render();return}
 if(cargoTotal>power.cargo){addLog("Cargo insuffisant : "+fmt(cargoTotal)+" / "+fmt(power.cargo)+".");render();return}
 for(const k of ["titanium","xenite","antimatter"]){
  const amount=Number((d.cargo||{})[k]||0);
  if(amount>(state.resources[k]||0)){addLog("Ressource insuffisante : "+k+".");render();return}
 }
 for(const [id,n] of Object.entries(ships)){
  planetShips(fromP.id)[id]=(planetShips(fromP.id)[id]||0)-n;
 }
 for(const k of ["titanium","xenite","antimatter"]){
  state.resources[k]-=Number((d.cargo||{})[k]||0);
 }
 const fromCoord=getPersistentCoord(fromP), toCoord=getPersistentCoord(target);
 const dist=Math.hypot(Number(toCoord.galaxyX)-Number(fromCoord.galaxyX),Number(toCoord.galaxyY)-Number(fromCoord.galaxyY));
 const duration=Math.max(8,Math.min(120,dist*3));
 const mission=d.mission==="support"?"transfer":d.mission;
  const fleet={
   id:"f"+Date.now(),
   originPlanetId:fromP.id,
   from:{id:"owned_"+fromP.id,name:fromP.name,x:fromP.x||0,y:fromP.y||0,galaxyX:fromCoord.galaxyX,galaxyY:fromCoord.galaxyY},
  to:target,
  startTime:performance.now()/1000,
   duration,mission,ships,
   cargo:{...(d.cargo||{})},
   attack:power.attack,cargoCap:power.cargo,done:false
  };
  state.fleets.push(fleet);
  try{publishPublicMissionV1(fleet,false);}catch(e){}
 d.ships={}; d.cargo={titanium:0,xenite:0,antimatter:0};
 addLog((d.mission==="scan"?"Espionnage":d.mission==="attack"?"Attaque":"Soutien / transfert")+" lancé vers "+coordText(target)+" depuis "+fromP.name+".");
 save();render();
}

function fleetMissionLabel(m){
 return m==="scan"?"Espionnage":m==="attack"?"Attaque":m==="transfer"?"Soutien / transfert":m==="colonize"?"Colonisation":"Exploration";
}
function fleetPhase(f){
 const now=performance.now()/1000;
 if(f.returning)return "Retour";
 if(f.done)return "Terminé";
 return "Aller";
}
function fleetRemainingSeconds(f){
 const now=performance.now()/1000;
 return Math.max(0,Math.ceil((f.startTime||0)+(f.duration||0)-now));
}
function fleetProgressPct(f){
 const now=performance.now()/1000;
 const elapsed=Math.max(0,now-(f.startTime||0));
 return Math.max(0,Math.min(100,Math.round(elapsed/Math.max(1,f.duration||1)*100)));
}
function fleetShipSummary(ships){
 const parts=[];
 for(const [id,n] of Object.entries(ships||{})){
  if(!n)continue;
  const s=SHIPS.find(x=>x.id===id);
  parts.push(`${s?s.icon:"🚀"} ${s?s.name:id} x${n}`);
 }
 return parts.join(" · ")||"Aucun vaisseau";
}
function liveFleetOperationsHtml(){
 const active=(state.fleets||[]).filter(f=>!f.done);
 return `<div class="live-ops-box">
  <h3>🛰️ Opérations en cours</h3>
  <p class="small muted">Suivi en temps réel : trajet aller, retour éventuel, cible et flotte engagée.</p>
  <div class="live-ops-list">
   ${active.length?active.map(f=>{
    const phase=fleetPhase(f);
    const remain=fleetRemainingSeconds(f);
    const pct=fleetProgressPct(f);
    const returnText=f.returning?"Retour vers "+(((state.planets||[]).find(p=>p.id===f.originPlanetId)||{}).name||"base"):(f.mission==="attack"||f.mission==="scan"?"Retour possible après résolution":"Pas de retour prévu");
    return `<div class="live-op-card">
     <div class="live-op-head"><strong>${fleetMissionLabel(f.mission)} → ${f.to&&f.to.name?f.to.name:"Cible"}</strong><span class="live-op-badge">${phase}</span></div>
     <div class="live-op-route">${f.from&&f.from.name?f.from.name:"Origine"} → ${f.to&&f.to.name?f.to.name:"Cible"} · ${coordText(f.to||{})}</div>
     <div class="bar"><span data-fleet-progress data-start-at="${f.startTime}" data-duration="${f.duration}" style="width:${pct}%"></span></div>
     <div class="live-op-time">
      <div><span class="muted">Temps restant</span><br><strong data-fleet-time data-start-at="${f.startTime}" data-duration="${f.duration}">${fmtTime(remain)}</strong></div>
      <div><span class="muted">Retour</span><br><strong>${returnText}</strong></div>
     </div>
     <div class="tiny muted" style="margin-top:6px">${fleetShipSummary(f.ships)}</div>
    </div>`;
   }).join(""):`<p class="small muted">Aucune flotte en déplacement.</p>`}
  </div>
 </div>`;
}
function capturedRansomValue(ships){
 let value=0;
 for(const [id,n] of Object.entries(ships||{})){
  const s=SHIPS.find(x=>x.id===id);
  if(!s)continue;
  value+=((s.cost.titanium||0)+(s.cost.xenite||0)*1.4+(s.cost.antimatter||0)*3)*n;
 }
 return Math.max(5,Math.round(value*0.35/100));
}
function registerCapturedEquipment(target,ships){
 state.capturedEquipment=state.capturedEquipment||[];
 const capturable={};
 for(const [id,n] of Object.entries(ships||{})){
  if(n>0&&Math.random()<0.35)capturable[id]=Math.max(1,Math.floor(n*0.35));
 }
 if(!Object.keys(capturable).length)return;
 const ransom=capturedRansomValue(capturable);
 state.capturedEquipment.push({
  id:"cap_"+Date.now()+"_"+Math.floor(Math.random()*9999),
  captor:target&&target.name?target.name:"Ennemi",
  targetId:target&&target.id,
  ships:capturable,
  ransom,
  createdAt:Date.now()
 });
 addLog("Équipement capturé par "+(target&&target.name?target.name:"l’ennemi")+" : rançon proposée "+ransom+" 💠.");
}
function payCapturedRansom(id){
 const item=(state.capturedEquipment||[]).find(x=>x.id===id);
 if(!item)return;
 if(!spendFragmentsPremium(item.ransom,"payer la rançon"))return
 
 const pid=state.activePlanetId;
 for(const [sid,n] of Object.entries(item.ships||{})){
  planetShips(pid)[sid]=(planetShips(pid)[sid]||0)+n;
 }
 state.capturedEquipment=state.capturedEquipment.filter(x=>x.id!==id);
 addLog("Rançon payée : équipement récupéré sur "+activePlanet().name+".");
 save();render();
}
function abandonCapturedEquipment(id){
 state.capturedEquipment=(state.capturedEquipment||[]).filter(x=>x.id!==id);
 addLog("Équipement capturé abandonné.");
 save();render();
}
function capturedEquipmentHtml(){
 const items=state.capturedEquipment||[];
 return `<div class="ransom-box">
  <h3>⛓️ Équipements capturés</h3>
  <p class="small muted">Prototype : certains équipements peuvent être capturés après une défaite. La rançon reste inférieure au coût de reconstruction.</p>
  ${items.length?items.map(item=>`<div class="ransom-card">
   <strong>Capturé par ${item.captor}</strong>
   <div class="tiny muted">${fleetShipSummary(item.ships)}</div>
   <div class="ransom-price">Rançon : ${item.ransom} 💠</div>
   <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px">
    <button class="btn btn-gold" onclick="payCapturedRansom('${item.id}')">Payer et récupérer</button>
    <button class="btn btn-ghost" onclick="abandonCapturedEquipment('${item.id}')">Abandonner</button>
   </div>
  </div>`).join(""):`<p class="small muted">Aucun équipement capturé.</p>`}
 </div>`;
}

