function armamentOpsSelectPreset1524(kind){
 const d=armamentOpsDraft();
 const from=d.from||state.activePlanetId;
 const owned=planetShips(from)||{};
 const next={};
 if(kind==="all"){
  for(const s of SHIPS){
   const n=owned[s.id]||0;
   if(n>0)next[s.id]=n;
  }
 }
 if(kind==="attack"){
  for(const s of SHIPS){
   const n=owned[s.id]||0;
   if(n>0&&(s.attack||0)>0)next[s.id]=n;
  }
  d.mission="attack";
 }
 if(kind==="scan"){
  const n=owned.scout_probe||0;
  if(n>0)next.scout_probe=Math.min(n,1);
  d.mission="scan";
 }
 if(kind==="cargo"){
  for(const s of SHIPS){
   const n=owned[s.id]||0;
   if(n>0&&(s.cargo||0)>0)next[s.id]=n;
  }
  d.mission="support";
 }
 d.ships=next;
 rerenderPreserveScroll();
}
