function scheduleRealtimeQueueTick(){
 if(window._stellarionQueueTick)clearTimeout(window._stellarionQueueTick);
 const active=(state.buildQueue&&state.buildQueue.length)||(state.shipQueue&&state.shipQueue.length);
 if(active){
  window._stellarionQueueTick=setTimeout(()=>{
   try{
    if(typeof renderLiveTimers==="function")renderLiveTimers();
    else if(typeof updateQueueTimers1583==="function")updateQueueTimers1583();
    scheduleRealtimeQueueTick();
   }catch(e){console.error(e)}
  },1000);
 }
}


function captureScrollState(){
 const selectors=[
  "html","body",".layout","#center",
  ".side",".side.left",".side.right",
  ".card",".panel",
  ".planet-left-panel",".planet-mid-panel",".planet-right-panel",
  ".planet-showcase",".planet-ui",".planet-board",".building-context",
  ".armament-grid",".armament-list",".armament-detail",
  ".alliance-wrap",".alliance-main-grid",".directory-list-compact",
  ".messages-view",".message-layout",".messages-list",".message-detail",
  ".arsenal-layout",".arsenal-main",".defense-view",
  ".sidebar-queue-box",".sidebar-queue-card",".sidebar-queue-detail"
 ];
 const entries=[];
 selectors.forEach(sel=>{
  document.querySelectorAll(sel).forEach((el,i)=>{
   if(el)entries.push({sel,i,top:el.scrollTop||0,left:el.scrollLeft||0});
  });
 });
 /* 1.6.10 — filet générique : capture aussi les divs scrollés sans classe connue
    (ex : vue construction classique avec style="overflow:auto" inline). */
 try{
  document.querySelectorAll("#center div").forEach((el,i)=>{
   if(el && (el.scrollTop>0 || el.scrollLeft>0)) entries.push({sel:"#center div",i,top:el.scrollTop,left:el.scrollLeft});
  });
 }catch(e){}
 return {
  winX:window.scrollX||0,
  winY:window.scrollY||0,
  docTop:(document.scrollingElement&&document.scrollingElement.scrollTop)||0,
  activeId:document.activeElement&&document.activeElement.id?document.activeElement.id:null,
  entries
 };
}
function restoreScrollState(pos){
 if(!pos)return;
 const apply=()=>{
  try{
   if(document.scrollingElement)document.scrollingElement.scrollTop=pos.docTop||0;
   window.scrollTo(pos.winX||0,pos.winY||0);
   (pos.entries||[]).forEach(e=>{
    const el=document.querySelectorAll(e.sel)[e.i];
    if(el){el.scrollTop=e.top||0;el.scrollLeft=e.left||0;}
   });
   if(pos.activeId){
    const el=document.getElementById(pos.activeId);
    if(el&&document.activeElement!==el)el.focus({preventScroll:true});
   }
  }catch(e){}
 };
 apply();
 requestAnimationFrame(()=>{apply();requestAnimationFrame(apply);});
}
function rerenderPreserveScroll(){
 const pos=captureScrollState();
 save();
 render();
 restoreScrollState(pos);
}
;

