function ownedSystemForPlanet(p=activePlanet()){
 if(!p)return null;
 return {
  id:"owned_"+p.id,
  owned:true,
  planetId:p.id,
  name:p.name,
  type:p.isHomeworld?"home":"owned_colony",
  x:p.x||0,
  y:p.y||0,
  galaxyX:p.galaxyX,
  galaxyY:p.galaxyY,
  sector:p.sector||"?",
  system:p.system||"?",
  rarity:p.rarity||"Possédée",
  archetype:p.type||"Empire",
  richness:p.isHomeworld?5:((p.bonus&&p.bonus.titanium)?7:4),
  danger:1,
  enemyPower:0,
  counterIntel:0,
  defenses:planetCommandementPower(p.id),
  fleetPower:planetFleetPower(p.id)
 };
}
function contextualRightPanelSelection(){
 if(state.view==="galaxy")return state.selected;
 if(["planet","buildings","buildings_list","ships","defenses","armament"].includes(state.view)){
  return ownedSystemForPlanet(activePlanet());
 }
 return null;
}


function ensureAllianceState(){
 state.alliance = state.alliance || null;
 state.allianceDraft = state.allianceDraft || {name:"",tag:"",description:""};
 state.allianceBank = state.allianceBank || {titanium:0,xenite:0,antimatter:0};
 state.allianceLogs = state.allianceLogs || [];
 state.allianceChatDraft = state.allianceChatDraft || "";
}
function setAllianceDraft(k,v){
 ensureAllianceState();
 state.allianceDraft[k]=String(v||"").slice(0,k==="tag"?6:220);
 save();render();
}
function createAlliance(){
 ensureAllianceState();
 const name=String(state.allianceDraft.name||"").trim();
 const tag=String(state.allianceDraft.tag||"").trim().toUpperCase().replace(/[^A-Z0-9]/g,"").slice(0,6);
 if(name.length<3){addLog("Nom d’alliance trop court.");render();return}
 if(tag.length<2){addLog("Tag d’alliance invalide.");render();return}
 state.alliance={
  id:"ally_"+Date.now(),
  name,tag,
  description:String(state.allianceDraft.description||"").trim(),
  founder:playerDisplayName(),
  createdAt:Date.now(),
  rank:"Fondateur",
  members:[
   {name:playerDisplayName(),rank:"Fondateur",power:empireFleetPower()+planetCommandementPower(state.activePlanetId),country:"",status:"En ligne"}
  ]
 };
 state.allianceLogs.unshift("Alliance ["+tag+"] "+name+" créée.");
 addLog("Alliance créée : ["+tag+"] "+name+".");
 save();render();
 saveAllianceToSupabase();
}
function leaveAlliance(){
 state.alliance=null;
 state.allianceLogs.unshift("Vous avez quitté l’alliance.");
 addLog("Alliance quittée.");
 save();render();
 saveAllianceToSupabase();
}
function setAllianceChatDraft(v){
 state.allianceChatDraft=String(v||"").slice(0,240);
}
function sendAllianceChat(){
 ensureAllianceState();
 const txt=String(state.allianceChatDraft||"").trim();
 if(!txt)return;
 state.allianceLogs.unshift(playerDisplayName()+" : "+txt);
 state.allianceChatDraft="";
 saveAllianceToSupabase();
 save();render();
}
function allianceBankDeposit(k){
 ensureAllianceState();
 const amount=Math.max(0,Math.floor((state.resources[k]||0)*0.1));
 if(amount<=0){addLog("Pas assez de ressource à déposer.");render();return}
 state.resources[k]-=amount;
 state.allianceBank[k]=(state.allianceBank[k]||0)+amount;
 state.allianceLogs.unshift("Dépôt alliance : "+fmt(amount)+" "+k+".");
 save();render();
 saveAllianceToSupabase();
}
function allianceBankWithdraw(k){
 ensureAllianceState();
 const amount=Math.max(0,Math.floor((state.allianceBank[k]||0)*0.1));
 if(amount<=0){addLog("Banque alliance insuffisante.");render();return}
 state.allianceBank[k]-=amount;
 state.resources[k]=(state.resources[k]||0)+amount;
 state.allianceLogs.unshift("Retrait alliance : "+fmt(amount)+" "+k+".");
 save();render();
 saveAllianceToSupabase();
}

function ensureAllianceRecruitmentState(){
 ensureAllianceState();
 // Serveur vierge : aucune alliance n'existe tant que les joueurs n'en créent pas.
 state.publicAlliances = state.publicAlliances || [];
 state.allianceApplicationDraft = state.allianceApplicationDraft || {allianceId:"",presentation:"",motivation:""};
 state.allianceApplications = state.allianceApplications || [];
}
function setApplicationDraft(k,v){
 ensureAllianceRecruitmentState();
 state.allianceApplicationDraft[k]=String(v||"").slice(0,420);
 save();
}

function applyToAlliance(allianceId){
 ensureAllianceRecruitmentState();
 const a=enrichedPublicAlliances().find(x=>x.id===allianceId);
 if(!a){addLog("Alliance introuvable.");render();return}
 const d=state.allianceApplicationDraft||{};
 const presentation=String(d.presentation||"").trim();
 const motivation=String(d.motivation||"").trim();
 if(presentation.length<10){addLog("Présentation trop courte : minimum 10 caractères.");render();return}
 if(motivation.length<10){addLog("Motivation trop courte : minimum 10 caractères.");render();return}
 const exists=(state.allianceApplications||[]).find(x=>x.allianceId===allianceId&&x.player===playerDisplayName()&&x.status==="pending");
 if(exists){addLog("Candidature déjà envoyée à ["+a.tag+"].");render();return}
 state.allianceApplications.unshift({
  id:"app_"+Date.now(),
  allianceId,
  allianceTag:a.tag,
  allianceName:a.name,
  player:playerDisplayName(),
  country:"France",
  power:empireFleetPower()+planetCommandementPower(state.activePlanetId),
  mainPlanet:activePlanet().name,
  coords:coordText(activePlanet()),
  presentation,
  motivation,
  status:"pending",
  createdAt:Date.now()
 });
 state.allianceLogs.unshift("Candidature envoyée à ["+a.tag+"] "+a.name+".");
 addLog("Candidature envoyée à ["+a.tag+"] "+a.name+".");
 save();render();
 submitAllianceApplicationSupabase(allianceId);
}
function acceptApplication(id){
 ensureAllianceRecruitmentState();
 const app=(state.allianceApplications||[]).find(x=>x.id===id);
 if(!app)return;
 if(!state.alliance){
  state.alliance={id:"ally_"+Date.now(),name:app.allianceName,tag:app.allianceTag,description:"Alliance rejointe via candidature.",founder:"Orion-7",createdAt:Date.now(),rank:"Membre",members:[]};
 }
 state.alliance.members=state.alliance.members||[];
 if(!state.alliance.members.find(m=>m.name===app.player)){
  state.alliance.members.push({name:app.player,rank:"Recrue",power:app.power,country:app.country,status:"En ligne"});
 }
 app.status="accepted";
 state.allianceLogs.unshift(app.player+" a rejoint l’alliance après candidature.");
 addLog("Candidature acceptée : "+app.player+".");
 save();render();
 saveAllianceToSupabase();
}
function refuseApplication(id){
 const app=(state.allianceApplications||[]).find(x=>x.id===id);
 if(!app)return;
 app.status="refused";
 state.allianceLogs.unshift("Candidature refusée : "+app.player+" → ["+app.allianceTag+"].");
 addLog("Candidature refusée.");
 save();render();
 saveAllianceToSupabase();
}

function setAllianceDirectoryFilter(k,v){
 ensureAllianceRecruitmentState();
 state.allianceDirectory = state.allianceDirectory || {query:"",sort:"power",status:"all"};
 state.allianceDirectory[k]=String(v||"").slice(0,60);
 rerenderPreserveScroll();
}
function enrichedPublicAlliances(){
 ensureAllianceRecruitmentState();
 const base=state.publicAlliances||[];
 const extras=[
  {id:"pub_zenith",name:"Zenith Guard",tag:"ZEN",members:18,power:76300,description:"Commandement organisée, entraide quotidienne.",status:"open",country:"France"},
  {id:"pub_umbra",name:"Umbra Wolves",tag:"UMB",members:9,power:31800,description:"Raids rapides et diplomatie agressive.",status:"closed",country:"Canada"},
  {id:"pub_solar",name:"Solar Pact",tag:"SUN",members:22,power:90400,description:"Grosse alliance orientée contrôle territorial.",status:"open",country:"Belgique"},
  {id:"pub_relic",name:"Relic Hunters",tag:"RLC",members:5,power:14200,description:"Exploration, artefacts et mondes rares.",status:"open",country:"Suisse"}
 ];
 const merged=[...base,...extras].map((a,i)=>({
  status:a.status||"open",
  country:a.country||(["France","Belgique","Suisse","Algérie"][i%4]),
  ...a
 }));
 const seen=new Set();
 return merged.filter(a=>{if(seen.has(a.id))return false;seen.add(a.id);return true});
}
function filteredPublicAlliances(){
 ensureAllianceRecruitmentState();
 const d=state.allianceDirectory||{query:"",sort:"power",status:"all"};
 let list=enrichedPublicAlliances();
 const q=String(d.query||"").toLowerCase().trim();
 if(q)list=list.filter(a=>String(a.name).toLowerCase().includes(q)||String(a.tag).toLowerCase().includes(q)||String(a.description).toLowerCase().includes(q));
 if(d.status&&d.status!=="all")list=list.filter(a=>a.status===d.status);
 list.sort((a,b)=>{
  if(d.sort==="members")return (b.members||0)-(a.members||0);
  if(d.sort==="name")return String(a.name).localeCompare(String(b.name));
  if(d.sort==="tag")return String(a.tag).localeCompare(String(b.tag));
  return (b.power||0)-(a.power||0);
 });
 return list;
}

