// ============================================
// SYSTÈME D'ALLIANCE COMPLET - SUPABASE SYNC
// ============================================

// ============================================
// 1. INITIALISATION ALLIANCE
// ============================================
async function initAllianceSystem() {
  if(!supa) {
    console.log('Alliance: Supabase pas disponible, mode local');
    return;
  }

  // Charger les données d'alliance depuis Supabase
  await loadAllianceFromSupabase();
  
  // Charger les candidatures
  await loadAllianceApplicationsFromSupabase();
  
  // Démarrer la synchronisation temps réel
  subscribeToAllianceUpdates();
}

// ============================================
// 2. SAUVEGARDE SUPABASE
// ============================================
async function saveAllianceToSupabase() {
  if(!supa || !state.alliance || !state.userId) return false;

  try {
    const allianceData = {
      id: state.alliance.id,
      user_id: state.userId,
      name: state.alliance.name,
      tag: state.alliance.tag,
      description: state.alliance.description,
      founder: state.alliance.founder || state.playerName,
      members: JSON.stringify(state.alliance.members || []),
      bank: JSON.stringify(state.allianceBank || {}),
      chat_logs: JSON.stringify(state.allianceLogs || []),
      created_at: state.alliance.createdAt || Date.now(),
      rank: state.alliance.rank || 'Membre',
      updated_at: new Date().toISOString()
    };

    // Vérifier si l'alliance existe déjà
    const { data: existing } = await supa
      .from('alliances')
      .select('id')
      .eq('id', state.alliance.id)
      .maybeSingle();

    if(existing) {
      // Mettre à jour
      const { error } = await supa
      .from('alliances')
        .update(allianceData)
        .eq('id', state.alliance.id);
      
      if(error) {
        console.log('Erreur sauvegarde alliance:', error);
        return false;
      }
    } else {
      // Créer
      const { error } = await supa
      .from('alliances')
        .insert([allianceData]);
      
      if(error) {
        console.log('Erreur création alliance:', error);
        return false;
      }
    }

    addLog('✅ Alliance sauvegardée sur le serveur.');
    return true;
  } catch(e) {
    console.log('Erreur saveAllianceToSupabase:', e);
    return false;
  }
}

// ============================================
// 3. CHARGEMENT SUPABASE
// ============================================
async function loadAllianceFromSupabase() {
  if(!supa || !state.userId) return;

  try {
    const { data, error } = await supa
      .from('alliances')
      .select('*')
      .eq('user_id', state.userId)
      .maybeSingle();

    if(error || !data) {
      state.alliance = null;
      return null;
    }

    // Restaurer l'alliance
    state.alliance = {
      id: data.id,
      name: data.name,
      tag: data.tag,
      description: data.description,
      founder: data.founder,
      createdAt: data.created_at,
      rank: data.rank,
      members: JSON.parse(data.members || '[]')
    };

    // Restaurer la banque
    state.allianceBank = JSON.parse(data.bank || '{"titanium":0,"xenite":0,"antimatter":0}');
    
    // Restaurer les logs
    state.allianceLogs = JSON.parse(data.chat_logs || '[]');

    addLog('✅ Alliance chargée depuis serveur: [' + state.alliance.tag + '] ' + state.alliance.name);
  } catch(e) {
    console.log('Erreur loadAllianceFromSupabase:', e);
  }
}

// ============================================
// 4. CANDIDATURES
// ============================================
async function loadAllianceApplicationsFromSupabase() {
  if(!supa) return;

  try {
    // Candidatures envoyées par le joueur
    const { data: sent } = await supa
      .from('alliance_applications')
      .select('*')
      .eq('player_id', state.userId);

    // Candidatures reçues par l'alliance du joueur
    let received = [];
    if(state.alliance) {
      const { data: rec } = await supa
      .from('alliance_applications')
        .select('*')
        .eq('alliance_id', state.alliance.id);
      received = rec || [];
    }

    state.allianceApplications = [...(sent || []), ...received];
  } catch(e) {
    console.log('Erreur loadAllianceApplicationsFromSupabase:', e);
  }
}

async function submitAllianceApplicationSupabase(allianceId) {
  if(!supa || !state.userId) return false;

  try {
    const appData = {
      id: 'app_' + Date.now(),
      player_id: state.userId,
      player_name: state.playerName || 'Anonyme',
      alliance_id: allianceId,
      presentation: state.allianceApplicationDraft?.presentation || '',
      motivation: state.allianceApplicationDraft?.motivation || '',
      power: calculatePower(),
      country: 'France', // À récupérer depuis le profil
      status: 'pending',
      created_at: new Date().toISOString()
    };

    const { error } = await supa
      .from('alliance_applications')
      .insert([appData]);

    if(error) {
      console.log('Erreur candidature:', error);
      return false;
    }

    addLog('📩 Candidature envoyée à l\'alliance!');
    return true;
  } catch(e) {
    console.log('Erreur submitAllianceApplicationSupabase:', e);
    return false;
  }
}

// ============================================
// 5. SYNCHRONISATION TEMPS RÉEL
// ============================================
function subscribeToAllianceUpdates() {
  if(!supa || !state.alliance) return;
  try {
    if(state.__allianceRealtimeChannel && supa.removeChannel){
      try{supa.removeChannel(state.__allianceRealtimeChannel);}catch(e){}
    }
    state.__allianceRealtimeChannel = supa
      .channel('stellarion_alliance_' + state.alliance.id)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'alliances', filter: 'id=eq.' + state.alliance.id }, payload => {
        console.log('Mise à jour alliance reçue:', payload);
        loadAllianceFromSupabase();
        render();
      })
      .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'alliance_applications', filter: 'alliance_id=eq.' + state.alliance.id }, payload => {
        const app = payload.new || {};
        showAllianceNotification('Nouvelle candidature', (app.player_name||'Un joueur') + ' a candidaturé!');
        addLog('📝 Nouvelle candidature: ' + (app.player_name||'Joueur'));
        loadAllianceApplicationsFromSupabase();
        render();
      })
      .subscribe();
  } catch(e) {
    console.log('Erreur subscribeToAllianceUpdates:', e);
  }
}

// ============================================
// 6. NOTIFICATIONS
// ============================================
function showAllianceNotification(title, message) {
  // Créer une notification simple
  const notifHTML = `
    <div style="
      position: fixed;
      bottom: 20px;
      right: 20px;
      background: linear-gradient(135deg, #4FC3F7, #01579B);
      border: 2px solid #4FC3F7;
      border-radius: 12px;
      padding: 16px 20px;
      color: white;
      z-index: 9999;
      max-width: 350px;
      animation: slideIn 0.3s ease;
      box-shadow: 0 0 30px rgba(79,195,247,0.5);
    ">
      <strong style="display: block; margin-bottom: 6px;">${title}</strong>
      <span>${message}</span>
    </div>
    <style>
      @keyframes slideIn {
        from {
          opacity: 0;
          transform: translateX(400px);
        }
        to {
          opacity: 1;
          transform: translateX(0);
        }
      }
    </style>
  `;

  document.body.insertAdjacentHTML('beforeend', notifHTML);

  // Retirer après 4 secondes
  setTimeout(() => {
    const notif = document.querySelector('[style*="position: fixed"]');
    if(notif) notif.remove();
  }, 4000);
}

// ============================================
// 7. OVERRIDE FONCTIONS EXISTANTES
// ============================================

// Override createAlliance pour sauvegarder en Supabase
const oldCreateAlliance = window.createAlliance;
window.createAlliance = async function() {
  if(oldCreateAlliance) oldCreateAlliance();
  await saveAllianceToSupabase();
  save();
  render();
};

// Override leaveAlliance
const oldLeaveAlliance = window.leaveAlliance;
window.leaveAlliance = async function() {
  if(!supa || !state.alliance) {
    if(oldLeaveAlliance) oldLeaveAlliance();
    return;
  }

  try {
    // Supprimer de Supabase
    await supa
      .from('alliances')
      .delete()
      .eq('id', state.alliance.id);
  } catch(e) {
    console.log('Erreur suppression alliance:', e);
  }

  if(oldLeaveAlliance) oldLeaveAlliance();
  save();
  render();
};

// Override sendAllianceChat pour synchroniser
const oldSendAllianceChat = window.sendAllianceChat;
window.sendAllianceChat = async function() {
  if(oldSendAllianceChat) oldSendAllianceChat();
  
  // Broadcaster le message
  if(supa && state.alliance) {
    try {
      await supa
      .from('alliance_chat')
        .insert([{
          alliance_id: state.alliance.id,
          player_id: state.userId,
          player_name: state.playerName,
          message: state.allianceChatDraft,
          created_at: new Date().toISOString()
        }]);
    } catch(e) {
      console.log('Erreur chat alliance:', e);
    }
  }

  save();
  render();
};

// Override allianceBankDeposit
const oldAllianceBankDeposit = window.allianceBankDeposit;
window.allianceBankDeposit = async function(k) {
  if(oldAllianceBankDeposit) oldAllianceBankDeposit(k);
  await saveAllianceToSupabase();
  save();
  render();
};

// Override allianceBankWithdraw
const oldAllianceBankWithdraw = window.allianceBankWithdraw;
window.allianceBankWithdraw = async function(k) {
  if(oldAllianceBankWithdraw) oldAllianceBankWithdraw(k);
  await saveAllianceToSupabase();
  save();
  render();
};

// Override applyToAlliance
const oldApplyToAlliance = window.applyToAlliance;
window.applyToAlliance = async function(allianceId) {
  // Soumettre en Supabase d'abord
  const success = await submitAllianceApplicationSupabase(allianceId);
  if(!success) return;

  // Puis appeler l'ancienne fonction
  if(oldApplyToAlliance) oldApplyToAlliance(allianceId);
  save();
  render();
};

// ============================================
// 8. CALCULER LA PUISSANCE
// ============================================
function calculatePower() {
  let power = 0;
  
  // Puissance des bâtiments
  if(state.buildings) {
    for(const [planetId, buildings] of Object.entries(state.buildings)) {
      if(Array.isArray(buildings)) {
        power += buildings.reduce((sum, b) => {
          const building = BUILDINGS.find(bl => bl.id === b.building_id);
          return sum + ((building?.power || 0) * (b.level || 1));
        }, 0);
      }
    }
  }

  // Puissance des vaisseaux
  for(const planet of state.planets || []) {
    const ships = planetShips(planet.id) || {};
    for(const [shipId, count] of Object.entries(ships)) {
      const ship = SHIPS.find(s => s.id === shipId);
      if(ship) {
        power += (ship.attack || 0) * (count || 0) * 2;
      }
    }
  }

  // Puissance des défenses
  const defenseCount = Object.values(state.defenses || {}).reduce((a, b) => a + b, 0);
  power += defenseCount * 150;

  return Math.max(0, Math.round(power));
}

// ============================================
// 9. AUTO-INIT
