function gwmShowTooltip(name,pos,x,y){
 let el=document.getElementById("gwmTooltip");
 if(!el){
  el=document.createElement("div");
  el.id="gwmTooltip";
  el.className="gwm-tooltip";
  document.body.appendChild(el);
 }
 el.innerHTML=`<strong>${name}</strong><br>${pos}`;
 el.style.left=x+"px";
 el.style.top=y+"px";
 el.style.display="block";
}
function gwmMoveTooltip(x,y){
 const el=document.getElementById("gwmTooltip");
 if(el){el.style.left=x+"px";el.style.top=y+"px";}
}
function gwmHideTooltip(){
 const el=document.getElementById("gwmTooltip");
 if(el)el.style.display="none";
}


