 const reward=result.questReward||(target.reward||((result.loot&&((result.loot.titanium||0)||(result.loot.xenite||0)||(result.loot.antimatter||0)||(result.loot.artifacts||result.loot.fragments||0)))?result.loot:{}));
 const score=result.rewardDifficultyScore||target.rewardDifficultyScore||target.danger||"?";
 const danger=target.danger||"?";
 const richness=target.richness||"?";
 const kind=target.weeklyBoss?"Boss hebdomadaire":"Menace journalière";
 const status=victory?"MENACE NEUTRALISÉE":"MISSION ÉCHOUÉE";
 const statusClass=victory?"ok":"error";
 const objective=victory
  ?"La cible IA a été neutralisée. La progression de quête a été mise à jour et les récompenses ont été transférées à ton empire."
  :"La flotte n’a pas réussi à neutraliser la menace. Renforce ton attaque, ajoute des vaisseaux lourds ou attends une meilleure fenêtre.";
