// Met à jour en direct les chiffres de ressources (panneau gauche + entête planète)
// sans reconstruire toute l'interface, pour un affichage temps réel fluide.
function updateLiveResourceText(){
 try{
  document.querySelectorAll('[data-res]').forEach(el=>{
   const key=el.getAttribute('data-res');
   if(state.resources && (key in state.resources)){
    el.textContent=fmt(state.resources[key]);
   }
  });
  // Entête de ressources de la vue construction (Ti / Xe / AM)
  document.querySelectorAll('[data-res-mini]').forEach(el=>{
   const key=el.getAttribute('data-res-mini');
   if(state.resources && (key in state.resources)){
    const label=el.getAttribute('data-res-label')||'';
    el.textContent=label+fmt(state.resources[key]);
   }
  });
  // Barre principale "RESSOURCES STOCKÉES" — mise à jour en temps réel (chaque seconde)
  const sbar=document.querySelectorAll('[data-sbar]');
  if(sbar.length){
   const r=state.resources||{};
   sbar.forEach(el=>{
    const key=el.getAttribute('data-sbar');
    if(key==='__energy'){
     el.textContent=(typeof stableEnergyDisplay1542b==='function')?stableEnergyDisplay1542b():(fmt((state.resources&&state.resources.energy)||0)+' MW');
     return;
    }
    let v;
    if(key==='__fragments') v=Number(r.fragments||r.artifacts||0)||0;
    else v=Number(r[key]||0)||0;
    el.textContent=(typeof stableFormatResource1542b==='function')?stableFormatResource1542b(v):Math.round(v).toLocaleString('fr-FR');
   });
  }
 }catch(e){}
}
