function slotSummary(p){return `<div class="slotgrid">${Object.entries(p.slots).map(([k,v])=>`<div class="slot"><strong>${slotIcon(k)} ${slotName(k)}</strong><div class="small muted">${usedSlots(k,p.id)}/${v} utilisés</div></div>`).join("")}</div>`}
function slotIcon(k){return k==="mining"?"⛏️":k==="industrial"?"🏭":k==="military"?"⚔️":k==="energy"?"☀️":"🔬"}
function slotName(k){return k==="mining"?"Mines":k==="industrial"?"Industrie":k==="military"?"Militaire":k==="orbital"?"Orbital":k==="defense"?"Commandement":k==="energy"?"Énergie":"Recherche"}
function buildingHtml(def){const p=activePlanet();ensureBuildingCatalogForPlanet(p.id);const rows=state.buildings[p.id]||[], row=rows.find(b=>b.building_id===def.id), queued=state.buildQueue.filter(q=>q.building_id===def.id&&q.planetId===p.id).length, level=row?row.level:0, effective=level+queued, next=effective+1, c=cost(def,next), allowed=canBuildOnPlanet(def,p), ok=allowed.ok&&state.resources.titanium>=c.titanium&&state.resources.xenite>=c.xenite&&state.resources.antimatter>=(c.antimatter||0);return `<div class="building"><div class="building-head"><div><strong>${def.icon} ${def.name}</strong><div class="small muted">Niveau ${level}/∞${queued?` · +${queued} file`:""} · ${slotIcon(def.slot)} ${slotName(def.slot)}</div></div><button class="btn" ${!ok?"disabled":""} onclick="queueBuilding('${def.id}')">Construire</button></div><div class="tiny ${allowed.ok?"muted":"error"}">${allowed.ok?`${fmt(c.titanium)} Titane · ${fmt(c.xenite)} Xénite · ${fmtTime(buildTime(def,next))}`:allowed.reason}</div></div>`}
function queueHtml(q){const def=BUILDINGS.find(b=>b.id===q.building_id),now=Date.now(),total=Math.max(1,q.finishAt-q.startAt),remain=Math.max(0,q.finishAt-now),p=Math.max(0,Math.min(1,1-remain/total)),dm=fragmentFinishCost(remain/1000,total/1000);return `<div class="row"><strong>${def.icon} ${def.name} → niv. ${q.to}</strong><div class="small muted">${fmtTime(remain/1000)}</div><div class="progress"><div style="width:${Math.round(p*100)}%"></div></div><button class="btn btn-gold" style="margin-top:8px" onclick="finishQueueItem('${q.id}')">Finir · ${dm} 💠</button></div>`}
