function fleetHtml(f){const now=performance.now()/1000,p=Math.min(1,(now-f.startTime)/f.duration);const comp=f.ships?Object.entries(f.ships).map(([id,n])=>`${SHIPS.find(s=>s.id===id)?.icon||"🚀"} ${n}`).join(" · "):"";return `<div class="row"><strong>🚀 ${f.mission.toUpperCase()}</strong><div class="small muted">${f.to.name}${comp?" · "+comp:""}</div><div class="progress"><div style="width:${Math.round(p*100)}%"></div></div></div>`}
function shipQueueHtml(q){
 const ship=SHIPS.find(s=>s.id===q.ship_id);
 const now=Date.now(), total=Math.max(1,q.finishAt-q.startAt), remain=Math.max(0,q.finishAt-now), p=Math.max(0,Math.min(1,1-remain/total));
 const dm=fragmentFinishCost(remain/1000,total/1000);
 return `<div class="row"><strong>${ship.icon} ${ship.name} x${q.qty||1}</strong><div class="small muted">Formation : ${fmtTime(remain/1000)}</div><div class="progress"><div style="width:${Math.round(p*100)}%"></div></div><button class="btn btn-gold" style="margin-top:8px" onclick="finishShipQueueItem('${q.id}')">Finir · ${dm} 💠</button></div>`
}

function updateLiveBoostCosts(){
 document.querySelectorAll(".queue-boost-btn,button").forEach(btn=>{
  const txt=(btn.textContent||"").toLowerCase();
  if(!txt.includes("accélérer")&&!txt.includes("accelerer")&&!txt.includes("finir"))return;
  const box=btn.closest(".queue-compact,.sidebar-queue-item,.queue-item-compact,.row,.card,div");
  if(!box)return;
  const timer=box.querySelector("[data-finish-at]:not([data-progress])");
  if(!timer)return;
  const finish=Number(timer.getAttribute("data-finish-at"))||0;
  const remain=Math.max(0,(finish-Date.now())/1000);
  const price=fragmentFinishCost(remain,remain);
  if(price<=0)return;
  if(txt.includes("finir")){
   btn.innerHTML="Finir · "+price+" 💠";
  }else{
   btn.innerHTML="⚡ Accélérer · "+price+" 💠";
  }
  btn.title="Coût actuel : "+price+" fragment"+(price>1?"s":"")+" · 1 fragment = 1 minute restante";
 });
}

function renderLiveTimers(){
 const now=Date.now();
 let completed=false;
 for(const q of state.buildQueue||[]) if(q.finishAt<=now) completed=true;
 for(const q of state.shipQueue||[]) if(q.finishAt<=now) completed=true;
 if(completed){
  if(typeof processBuildQueue==="function")processBuildQueue(false);
  if(typeof processShipQueue==="function")processShipQueue(false);
  save();render();return;
 }
 document.querySelectorAll("[data-finish-at]:not([data-progress])").forEach(el=>{
  const finish=Number(el.getAttribute("data-finish-at"))||0;
  el.textContent=fmtTime(Math.max(0,(finish-Date.now())/1000));
 });
 document.querySelectorAll("[data-fleet-time]").forEach(el=>{
  const start=Number(el.getAttribute("data-start-at"))||0;
  const duration=Number(el.getAttribute("data-duration"))||0;
  el.textContent=fmtTime(Math.max(0,(start+duration)-(performance.now()/1000)));
 });
 document.querySelectorAll("[data-fleet-progress]").forEach(el=>{
  const start=Number(el.getAttribute("data-start-at"))||0;
  const duration=Number(el.getAttribute("data-duration"))||1;
  const pct=Math.max(0,Math.min(100,Math.round(((performance.now()/1000)-start)/duration*100)));
  el.style.width=pct+"%";
 });
 document.querySelectorAll("[data-progress]").forEach(el=>{
  const start=Number(el.getAttribute("data-start-at"))||0;
  const finish=Number(el.getAttribute("data-finish-at"))||0;
  const total=Math.max(1,finish-start);
  const pct=Math.max(0,Math.min(100,Math.round((1-((finish-Date.now())/total))*100)));
  el.style.width=pct+"%";
  if(el.textContent) el.textContent="";
 });
 if(typeof updateLiveBoostCosts==="function")updateLiveBoostCosts();
}

