function systemPanelHtml(s){
 if(state && state.view!=="galaxy") return "";

 try{
  if(s && s.owned){ return ownedPlanetPanelHtml(s); }

  if(!s){
   return `<div class="card panel"><span class="pill">SÉLECTION</span><p class="muted">Clique sur une planète de la galaxie pour afficher ses informations.</p>${cwmSelectedPanelHtml(s)}</div>`;
  }

  state.scanReports = state.scanReports || {};
  state.systems = Array.isArray(state.systems) && state.systems.length ? state.systems : generateGalaxy();
  const home = state.systems[0] || {x:0,y:0};
  const report = state.scanReports[s.id];
  const isKnown = s.type==="home" || !!report;
  const sx = Number(s.x || 0);
  const sy = Number(s.y || 0);
  const distance = Math.round(Math.hypot(sx-Number(home.x||0), sy-Number(home.y||0)));

  let defenseCount = "?";
  try{
   if(typeof enemyCommandementsFor==="function" && typeof DEFENSES!=="undefined"){
    const defs = enemyCommandementsFor(s);
    defenseCount = Object.values(defs||{}).reduce((a,b)=>a+(Number(b)||0),0);
   }
  }catch(e){ defenseCount = "?"; }

  let visibleStats = "";
  if(isKnown){
   visibleStats = `
    <div class="resource"><span>Planètes</span><strong>${s.planets ?? "?"}</strong></div>
    <div class="resource"><span>Danger</span><strong>${s.danger ?? "?"}/10</strong></div>
    <div class="resource"><span>Richesse</span><strong>${s.richness ?? "?"}/10</strong></div>
    <div class="resource"><span>Puissance flotte</span><strong>${fmt(Number(s.enemyPower||0))}</strong></div>
    <div class="resource"><span>Contre-espionnage</span><strong>${fmt(Number(s.counterIntel||0))}</strong></div>
    <div class="resource"><span>Commandements estimées</span><strong>${defenseCount}</strong>${cwmSelectedPanelHtml(s)}</div>`;
  } else {
   visibleStats = `
    <div class="resource"><span>Distance</span><strong>${fmt(distance)}</strong></div>
    <div class="resource"><span>Planètes</span><strong>?</strong></div>
    <div class="resource"><span>Danger</span><strong>Inconnu</strong></div>
    <div class="resource"><span>Richesse</span><strong>Inconnue</strong></div>
    <div class="resource"><span>Flotte ennemie</span><strong>?</strong></div>
    <div class="resource"><span>Commandements</span><strong>?</strong></div>
    <p class="tiny warn">Envoie une sonde éclaireuse pour révéler les informations détaillées.</p>`;
  }

  let missionHtml = "";
  try{
   missionHtml = typeof missionPlannerHtml==="function" ? missionPlannerHtml(s) : `<div class="row"><strong class="error">Centre de mission absent</strong>${cwmSelectedPanelHtml(s)}</div>`;
  }catch(e){
   missionHtml = `<div class="row"><strong class="error">Centre de mission indisponible</strong><p class="small muted">${String(e.message||e)}</p>${cwmSelectedPanelHtml(s)}</div>`;
  }

  let scannedReport = "";
  try{
   scannedReport = report && typeof reportHtml==="function" ? reportHtml(report) : "";
  }catch(e){ scannedReport = ""; }

  const __sel=(typeof gwmSelectionInfo==="function")?gwmSelectionInfo():null;
  const __asset=(typeof vlibSelectionAsset==="function")?vlibSelectionAsset():null;
  const __cx=__sel?__sel.c.x:Math.round(sx/18);
  const __cy=__sel?__sel.c.y:Math.round(sy/18);
  const __modernPreview=__asset
   ? `<div class="gwm-selection-preview" style="margin:10px 0"><img class="gwm-planet-img" src="${__asset.src}" alt="${s.name||"Planète"}" style="width:100%;max-width:240px;object-fit:contain;display:block;margin:0 auto;filter:drop-shadow(0 0 30px rgba(79,195,247,.3))"></div>`
   : `<div class="planet" style="background:radial-gradient(circle at 35% 25%,white,${systemColor(s.type)} 35%,#061431 80%)"></div>`;
  const __actionButtons=`<div class="gwm-selection-actions" style="margin-top:12px">
   <button class="btn btn-ghost" onclick="gwmSetCamera(${__cx},${__cy},gwmCamera().zoom)">🎯 Centrer</button>
   <button class="btn btn-ghost" onclick="gwmFocusHomePlanet()">🏠 Retour empire</button>
  </div>`;

  return `<div class="card panel selected-row">
   <span class="pill" style="border-color:${systemColor(s.type)}">${systemLabel(s.type)}</span>
   <h2>${s.name || "Système inconnu"}</h2>
   <p class="muted">Secteur ${s.sector ?? "?"} · Système ${s.system ?? "?"}</p><div class="coord-pill" onclick="copyCoordFromElement(this)">📍 Position ${coordText(s)}</div>
   ${__modernPreview}
   ${visibleStats}
   ${playerProfileHtml(s)}
   ${quickMessageTargetHtml(s,"galaxy")}
   ${missionHtml}
   ${scannedReport}
   ${__actionButtons}
  ${cwmSelectedPanelHtml(s)}</div>`;
 }catch(err){
  return `<div class="card panel">
    <span class="pill">SYSTÈME</span>
    <h2 class="error">Erreur système corrigible</h2>
    <p class="muted">${String(err.message||err)}</p>
    <button class="btn btn-ghost" onclick="localStorage.clear();location.reload()">Réinitialiser sauvegarde</button>
   ${cwmSelectedPanelHtml(s)}</div>`;
 }
}

