    <textarea placeholder="Message" oninput="setDraft('body',this.value)" style="width:100%;height:80px;margin-top:8px;background:#07101f;color:white;border:1px solid rgba(79,195,247,.2);border-radius:8px;padding:8px">${stellarionSafeText((state.messageDraft&&state.messageDraft.body)||"")}</textarea>
