/* ---- bloc script (source: ligne ~13554) ---- */
// ===== Authentification : le jeu ne démarre qu'une fois le joueur connecté =====
let __gameStarted = false;
let __authMode = "login";
let currentUser = null;

function authSetMode(mode){
 __authMode = mode;
 const login = document.getElementById("tab-login");
 const signup = document.getElementById("tab-signup");
 const pseudoWrap = document.getElementById("auth-pseudo-wrap");
 const submit = document.getElementById("auth-submit");
 const pwd = document.getElementById("auth-password");
 if(mode==="login"){
  login.style.background="#4FC3F7"; login.style.color="#04162e"; login.style.border="0";
  signup.style.background="transparent"; signup.style.color="#cfe3fb"; signup.style.border="1px solid rgba(79,195,247,.3)";
  pseudoWrap.style.display="none";
  submit.textContent="Se connecter";
  if(pwd) pwd.setAttribute("autocomplete","current-password");
 } else {
  signup.style.background="#4FC3F7"; signup.style.color="#04162e"; signup.style.border="0";
  login.style.background="transparent"; login.style.color="#cfe3fb"; login.style.border="1px solid rgba(79,195,247,.3)";
  pseudoWrap.style.display="block";
  submit.textContent="Créer mon empire";
  if(pwd) pwd.setAttribute("autocomplete","new-password");
 }
 authMessage("");
}

function authMessage(text, ok){
 const el = document.getElementById("auth-message");
 if(!el) return;
 el.textContent = text || "";
 el.style.color = ok ? "#7ee0a8" : "#ff9a8a";
}

function showAuthScreen(){
 try{ window.__stellarionBootHold = false; }catch(e){}
 try{ document.body.classList.remove('stellarion-boot-hold'); }catch(e){}
 const s = document.getElementById("auth-screen");
 if(s) s.style.display = "flex";
}
function hideAuthScreen(){
 const s = document.getElementById("auth-screen");
 if(s) s.style.display = "none";
}

async function authSubmit(){
 if(!supa){ authMessage("Connexion au serveur impossible. Réessaie dans un instant."); return; }
 const email = (document.getElementById("auth-email").value||"").trim();
 const password = document.getElementById("auth-password").value||"";
 if(!email || !password){ authMessage("Email et mot de passe requis."); return; }
 if(password.length < 6){ authMessage("Mot de passe : 6 caractères minimum."); return; }

 const btn = document.getElementById("auth-submit");
 btn.disabled = true; const oldLabel = btn.textContent; btn.textContent = "…";

 try {
  if(__authMode === "signup"){
   const pseudo = (document.getElementById("auth-pseudo").value||"").trim() || ("Commandant " + email.split("@")[0]);
   const { data, error } = await supa.auth.signUp({
    email, password,
    options: { data: { pseudo } }
   });
   if(error){ authMessage(traduireErreurAuth(error.message)); return; }
   if(data && data.session){
    authMessage("Empire créé ! Lancement…", true);
    onAuthenticated(data.user);
   } else {
    authMessage("Compte créé. Vérifie ta boîte mail pour confirmer, puis connecte-toi.", true);
    authSetMode("login");
   }
  } else {
   const { data, error } = await supa.auth.signInWithPassword({ email, password });
   if(error){ authMessage(traduireErreurAuth(error.message)); return; }
   authMessage("Connexion réussie ! Lancement…", true);
   onAuthenticated(data.user);
  }
 } catch(e){
  authMessage("Erreur : " + (e.message||e));
 } finally {
  btn.disabled = false; btn.textContent = oldLabel;
 }
}

function traduireErreurAuth(msg){
 const m = (msg||"").toLowerCase();
 if(m.includes("invalid login")) return "Email ou mot de passe incorrect.";
 if(m.includes("already registered") || m.includes("already been registered")) return "Cet email a déjà un compte. Connecte-toi.";
 if(m.includes("email not confirmed")) return "Email non confirmé. Vérifie ta boîte mail.";
 if(m.includes("password")) return "Mot de passe trop faible (6 caractères minimum).";
 if(m.includes("rate limit")) return "Trop de tentatives. Patiente un instant.";
 return msg || "Une erreur est survenue.";
}

function onAuthenticated(user){
 currentUser = user;
 hideAuthScreen();
 if(!__gameStarted){
  __gameStarted = true;
  try {
   setSaveKeyForUser(user);   // sauvegarde propre à ce joueur (liée à son compte)
   load();                    // charge SA sauvegarde, ou démarre un empire neuf
   render();
   startGameLoop();
   // Initialiser le système d'alliance
   initAllianceSystem();
  } catch(e){
   console.error("Erreur démarrage jeu:", e);
  }
 }
}

async function logoutPlayer(){
 if(supa){ try { await supa.auth.signOut(); } catch(e){} }
 location.reload();
}

// Au chargement : on vérifie s'il y a déjà une session active (le joueur reste connecté).
async function initAuth(){
 if(!supa){
  // Si Supabase ne charge pas, on laisse le jeu démarrer en mode hors-ligne pour ne pas tout bloquer.
  console.warn("Supabase indisponible — démarrage hors-ligne.");
  onAuthenticated(null);
  return;
 }
 try {
  const { data } = await supa.auth.getSession();
  if(data && data.session){
   onAuthenticated(data.session.user);
  } else {
   showAuthScreen();
   authSetMode("login");
  }
 } catch(e){
  console.error(e);
  showAuthScreen();
  authSetMode("login");
 }
}


// Crédite la production de la seconde écoulée DANS LE STOCK DE CHAQUE PLANÈTE,
// de façon indépendante. La planète mère reçoit sa production, chaque colonie la sienne.
function tickResources(){
 if(typeof ensurePlanetResources==="function") ensurePlanetResources();
 for(const p of state.planets||[]){
  const prod = (typeof calcProdForPlanet==="function") ? calcProdForPlanet(p.id) : {titanium:0,xenite:0,antimatter:0};
  const r = state.planetResources && state.planetResources[p.id];
  if(!r) continue;
  r.titanium   += (prod.titanium   || 0) / 3600;
  r.xenite     += (prod.xenite     || 0) / 3600;
  r.antimatter += (prod.antimatter || 0) / 3600;
 }
 // On resynchronise le miroir (state.resources) avec la planète active.
 if(typeof syncActiveResources==="function") syncActiveResources();
}

function refreshResourceDisplays(){
 if(typeof updateLiveResourceText==="function") updateLiveResourceText();
}

let __gameLoopStarted = false;
function startGameLoop(){
 if(__gameLoopStarted) return;
 __gameLoopStarted = true;
 setInterval(()=>{
  const nowLoop=Date.now();
  processBuildQueue(false);
  processShipQueue(false);
  processFleets();
  for(const p of state.planets||[]){
   state.buildings[p.id]=state.buildings[p.id]||[];
   if(!state.buildings[p.id].find(b=>b.building_id==="orbital_base")){
    state.buildings[p.id].push({building_id:"orbital_base",level:p.isHomeworld?1:0});
   }
  }
  migrateGlobalShipsToPlanets();
  tickResources();
  if(!state.__lastAutoSaveAt || nowLoop-state.__lastAutoSaveAt>5000){
   state.__lastAutoSaveAt=nowLoop;
   state.lastSave=nowLoop;
   save();
  }
  if(!document.hidden){
   renderLiveTimers();
    refreshResourceDisplays();
    try{ if(typeof pollIncomingPlayerMessages==="function") pollIncomingPlayerMessages(false); }catch(e){}
    try{ if(typeof refreshPublicMissionsV1==="function") refreshPublicMissionsV1(false); }catch(e){}
    try{
     if(typeof claimMarketSettlementsFromCloud==="function" && (!state.__lastMarketSettlementClaimAt || nowLoop-state.__lastMarketSettlementClaimAt>15000)){
      state.__lastMarketSettlementClaimAt=nowLoop;
      claimMarketSettlementsFromCloud(true);
     }
    }catch(e){}
   }
 },1000);
}

// ===== Filet de sécurité boucle de jeu =====
// Si le flux de connexion a sauté startGameLoop() (erreur intermédiaire alors que
// __gameStarted était déjà passé à true), la boucle ne démarre jamais et les
// constructions/flottes ne se valident qu'au rechargement de la page. Ce timer
// indépendant garantit que la boucle tourne, et traite la file en secours.
// Il ne touche PAS aux ressources (pas de double crédit) : uniquement les files
// discrètes, qui sont idempotentes (ne valident qu'une fois ce qui est dû).
setInterval(function(){
 try{
  if(!window.state || !Array.isArray(state.planets) || !state.planets.length) return;
  if(typeof startGameLoop==="function") startGameLoop();
  // Secours direct au cas où la boucle ne tournerait toujours pas.
  if(typeof processBuildQueue==="function") processBuildQueue(false);
  if(typeof processShipQueue==="function") processShipQueue(false);
  if(typeof processFleets==="function") processFleets();
  if(!document.hidden && typeof renderLiveTimers==="function") renderLiveTimers();
 }catch(e){}
},2000);


// ===== Alpha 1.5.43 V15 — Connexion + sauvegarde cloud Supabase =====
// Objectif : un compte = une sauvegarde persistante côté Supabase.
// Le localStorage reste uniquement un cache de secours.
const STELLARION_CLOUD_SAVE_VERSION = "1.5.44-v16";
let __cloudSaveReadyV15 = false;
let __cloudSaveBusyV15 = false;
let __cloudSaveQueuedV15 = false;
let __cloudLastPushV15 = 0;
let __cloudStatusV15 = "hors-ligne";

function setCloudStatusV15(txt){
 __cloudStatusV15 = txt || "";
 const el=document.getElementById('cloudStatusV15');
 if(el) el.textContent = __cloudStatusV15;
}

function serializableStateV15(){
 try{ if(typeof commitActiveResources==="function") commitActiveResources(); }catch(e){}
 const data={...state, selectedId:state.selected&&state.selected.id};
 delete data.systems; delete data.selected; delete data.__allianceRealtimeChannel;
 // Caches reconstructibles : ne JAMAIS les pousser dans la sauvegarde (ils gonflent
 // la charge utile avec la liste de TOUS les joueurs cloud et leurs mondes).
 delete data.cloudPlayers; delete data.cloudPlayersUpdatedAt; delete data.cloudPlayersLastError;
 delete data.registeredPlayersV12; delete data.__lbfNpcs; delete data.__lbfRealPlayers; delete data.planetProductionServer;
 data.savedAt = Date.now();
 data.saveVersion = STELLARION_CLOUD_SAVE_VERSION;
 return data;
}
// La sauvegarde cloud appelait cloudSavePayloadV15() qui n'existait pas : chaque push
// échouait silencieusement. On la définit ici comme la charge utile sérialisable.
function cloudSavePayloadV15(){ return serializableStateV15(); }

async function ensureCloudPlayerV15(user){
 if(!supa || !user || !user.id) return false;
 const username=String((user.user_metadata&&user.user_metadata.pseudo) || state?.playerName || (user.email?user.email.split('@')[0]:"Commandant") || "Commandant").replace(/[<>]/g,"").trim().slice(0,32) || "Commandant";
 const payload={
  id:user.id,
  username,
  last_seen:new Date().toISOString(),
  ...stellarionHomePlanetPublicSnapshotV16()
  };
  const {error}=await stellarionUpsertPlayerV16(payload);
 if(error){ console.warn('players upsert error',error); return false; }
 return true;
}

async function pullCloudSaveV15(user){
 if(!supa || !user || !user.id)return null;
 try{
  const {data,error}=await supa.from('player_saves').select('payload,saved_at,save_version').eq('player_id',user.id).maybeSingle();
  if(error)throw error;
  if(!data||!data.payload)return null;
  let localData=null;
  try{ const raw=localStorage.getItem(SAVE_KEY); if(raw)localData=JSON.parse(raw); }catch(e){}
  const cloudPayload=data.payload||{};
  // Démarrage authentifié : le cloud est la source visible au chargement.
  // On renvoie donc toujours la sauvegarde serveur si elle existe, pour éviter
  // le flash de l'ancienne sauvegarde locale avant l'arrivée du cloud.
  setCloudStatusV15('cloud chargé');
  return cloudPayload;
 }catch(e){
  console.warn('pullCloudSaveV15',e);
  setCloudStatusV15('cloud lecture KO');
  return null;
 }
}

async function pushCloudSaveV15(force=false){
 if(!supa || typeof currentUser==='undefined' || !currentUser || !currentUser.id){
  setCloudStatusV15(currentUser ? 'cloud indisponible' : 'hors-ligne');
  return false;
 }
 const now=Date.now();
 if(!force && now-__cloudLastPushV15<8000){
  __cloudSaveQueuedV15=true;
  return false;
 }
 if(__cloudSaveBusyV15){
  __cloudSaveQueuedV15=true;
  return false;
 }
 __cloudSaveBusyV15=true;
 __cloudSaveQueuedV15=false;
 try{
  const payload=cloudSavePayloadV15();
  const savedIso=new Date(Number(payload.savedAt)||Date.now()).toISOString();
  const {error}=await supa.from('player_saves').upsert({
   player_id:currentUser.id,
   payload,
   save_version:STELLARION_CLOUD_SAVE_VERSION,
   saved_at:savedIso,
   updated_at:new Date().toISOString()
  },{onConflict:'player_id'});
  if(error)throw error;
  __cloudLastPushV15=Date.now();
  setCloudStatusV15('cloud OK');
  return true;
 }catch(e){
  console.warn('pushCloudSaveV15',e);
  setCloudStatusV15('cloud sauvegarde KO');
  return false;
 }finally{
  __cloudSaveBusyV15=false;
  if(__cloudSaveQueuedV15){
   __cloudSaveQueuedV15=false;
   setTimeout(function(){try{pushCloudSaveV15(true)}catch(e){}},900);
  }
 }
}

// Wrapper sauvegarde V1 CLEAN : sauvegarde locale immediate + miroir Supabase du compte.
const __saveLocalOriginalV15 = save;
save = function(){
 try{
  __saveLocalOriginalV15();
  const ok = (typeof window!=="undefined") ? (window.__stellarionLastSaveOk!==false) : true;
  setCloudStatusV15(currentUser ? (ok ? 'sauvegarde locale OK' : 'sauvegarde KO') : 'hors-ligne');
  if(ok && __cloudSaveReadyV15)pushCloudSaveV15(false);
 }
 catch(e){ console.warn('local save error',e); setCloudStatusV15('erreur sauvegarde locale'); }
};
// Nouveau démarrage authentifié : tire la sauvegarde Supabase avant de charger le jeu.
onAuthenticated = async function(user){
 currentUser = user;
 hideAuthScreen();
 if(__gameStarted) return;
 __gameStarted = true;
 try{
  setSaveKeyForUser(user);
  if(user && supa){
   setCloudStatusV15('cache compte local…');
   const cloudSave = await pullCloudSaveV15(user);
   if(cloudSave){
    try{ localStorage.setItem(SAVE_KEY,JSON.stringify(cloudSave)); }catch(e){}
    setCloudStatusV15('cloud chargé');
   }else{
    setCloudStatusV15('sauvegarde locale prête');
   }
  }
  load();
  state.userId = user && user.id ? user.id : 'invite';
  state.playerEmail = user && user.email ? user.email : '';
  state.playerName = state.playerName || ((user&&user.user_metadata&&user.user_metadata.pseudo) || (user&&user.email?user.email.split('@')[0]:'Vapowh'));
  if(user && supa) await ensureCloudPlayerV15(user);
  __cloudSaveReadyV15 = !!(user && supa);
  render();
  try{ if(typeof pollIncomingPlayerMessages==="function") pollIncomingPlayerMessages(true); }catch(e){}
  startGameLoop();
  try{ initAllianceSystem(); }catch(e){}
  if(__cloudSaveReadyV15) pushCloudSaveV15(true);
 }catch(e){
  console.error('Erreur démarrage V15:',e);
  showAuthScreen();
  authMessage('Erreur au lancement : '+(e.message||e));
 }
};

// Badge de statut cloud dans la topbar, sans casser la DA.
(function(){
 const oldRender=render;
 render=function(){
  oldRender();
  try{
   const brand=document.querySelector('.topbar-brand1512')||document.querySelector('.topbar .brand')?.parentElement;
   if(brand && !document.getElementById('cloudStatusV15')){
    brand.insertAdjacentHTML('beforeend',`<div class="tiny muted">☁️ <span id="cloudStatusV15">${__cloudStatusV15}</span></div>`);
   }
  }catch(e){}
 };
})();


// ===== Alpha 1.5.44 V16 — Auth complète + profil persistant =====
// Nettoyage à la racine : Supabase devient la source de vérité du compte joueur.
const STELLARION_V16_PROFILE_VERSION = "1.5.44-v16";
let __profileSaveBusyV16 = false;
let __profileSaveQueuedV16 = false;
let __profileLoadedV16 = false;

function safeTextV16(v, max=500){
 return String(v||"").replace(/[<>]/g,"").trim().slice(0,max);
}
function currentPseudoV16(){
 return safeTextV16(state?.playerName || currentUser?.user_metadata?.pseudo || currentUser?.email?.split('@')[0] || 'Commandant', 32) || 'Commandant';
}
function stellarionHomePlanetPublicSnapshotV16(){
 try{
  const planets=Array.isArray(state.planets)?state.planets:[];
  const home=planets.find(p=>p&&p.isHomeworld)||planets[0];
  if(!home)return {};
  const c=(typeof stellarionOwnedPlanetCoord==="function")?stellarionOwnedPlanetCoord(home):{x:(home.galaxyX!==undefined?home.galaxyX:home.x),y:(home.galaxyY!==undefined?home.galaxyY:home.y)};
  const gx=Math.round(Number(c&&c.x));
  const gy=Math.round(Number(c&&c.y));
  let world=null;
  try{
   if(typeof atlasWorldFor==="function"&&Number.isFinite(gx)&&Number.isFinite(gy)){
    const w=atlasWorldFor(home,gx,gy);
    if(w)world={idx:w.idx,kind:w.kind,family:w.family,pal:w.pal,seed:w.seed,atmo:w.atmo,name:w.name,coord:w.coord,x:w.x,y:w.y,type:w.type,temp:w.temp,ring:!!w.ring,spin:w.spin,diam:w.diam};
   }
  }catch(e){}
  return {
   home_planet_id:safeTextV16(home.id||"home",80),
   home_planet_name:safeTextV16(home.name||"Nova Prime",80),
   home_planet_type:safeTextV16(home.type||(home.isHomeworld?"homeworld":"colony"),80),
   home_planet_world:world
  };
 }catch(e){return {}}
}
function stellarionStripPlayerVisualPayloadV16(payload){
 const clean={...payload};
 delete clean.home_planet_id;
 delete clean.home_planet_name;
 delete clean.home_planet_type;
 delete clean.home_planet_world;
 return clean;
}
function stellarionMissingPlayerVisualSchemaV16(error){
 const msg=String(error&&error.message||"").toLowerCase();
 return !!(error&&(error.code==="42703"||error.code==="PGRST204"||msg.includes("column")&&msg.includes("does not exist")||msg.includes("schema cache")&&msg.includes("home_planet")));
}
async function stellarionUpsertPlayerV16(payload,selectCols){
 const q=supa.from('players').upsert(payload,{onConflict:'id'});
 const res=selectCols?q.select(selectCols).single():await q;
 const out=selectCols?await res:res;
 if(out&&stellarionMissingPlayerVisualSchemaV16(out.error)){
  const q2=supa.from('players').upsert(stellarionStripPlayerVisualPayloadV16(payload),{onConflict:'id'});
  return selectCols?await q2.select(selectCols.replace(/,home_planet_[^,]+/g,"")).single():await q2;
 }
 return out;
}
function normalizeProfileFromRowV16(row){
 row = row || {};
 return {
  pseudo: safeTextV16(row.username || row.pseudo || currentPseudoV16(),32) || 'Commandant',
  avatar_url: safeTextV16(state?.playerAvatar || '',700),
  country: safeTextV16(state?.playerCountry || '',60),
  flag: safeTextV16(state?.playerFlag || '',16),
  description: safeTextV16(state?.playerDescription || '',700),
  motto: safeTextV16(state?.playerMotto || '',120),
  created_at: row.created_at || state?.playerCreatedAt || new Date().toISOString(),
  last_seen: row.last_seen || new Date().toISOString()
 };
}
function applyProfileToStateV16(profile){
 if(!profile) return;
 state.playerName = profile.pseudo || state.playerName || 'Commandant';
 state.playerAvatar = profile.avatar_url || '';
 state.playerCountry = profile.country || '';
 state.playerFlag = profile.flag || '';
 state.playerDescription = profile.description || '';
 state.playerMotto = profile.motto || '';
 state.playerCreatedAt = profile.created_at || state.playerCreatedAt || new Date().toISOString();
 state.profileVersion = STELLARION_V16_PROFILE_VERSION;
}

// Remplace l'upsert V15 par un upsert profil complet.
// Récupère la coordonnée galaxie persistante du joueur (sa planète mère) pour la
// stocker côté serveur. Sans position partagée, tous les joueurs retombent en 0,0.
function stellarionPlayerGalaxyCoord(){
 try{
  if(typeof ensurePersistentCoordinates==='function') ensurePersistentCoordinates();
  const planets=Array.isArray(state.planets)?state.planets:[];
  const home=planets.find(p=>p&&p.isHomeworld)||planets[0];
  if(!home) return null;
  const c=(typeof getPersistentCoord==='function')?getPersistentCoord(home):{galaxyX:home.galaxyX,galaxyY:home.galaxyY};
  const gx=Math.round(Number(c&&c.galaxyX));
  const gy=Math.round(Number(c&&c.galaxyY));
  if(!Number.isFinite(gx)||!Number.isFinite(gy)) return null;
  return {galaxy_x:gx, galaxy_y:gy, sector:Number(home.sector)||null, system:Number(home.system)||null};
 }catch(e){ return null; }
}

function stellarionIsUniqueCoordErrorV16(error){
 return !!(error && (error.code==="23505" || String(error.message||"").toLowerCase().includes("unique")));
}
function stellarionCoordKeyV16(x,y){
 return String(Math.round(Number(x)||0))+";"+String(Math.round(Number(y)||0));
}
function stellarionCoordCandidateV16(base,attempt,taken){
 const bx=Math.round(Number(base&&base.galaxy_x)||0);
 const by=Math.round(Number(base&&base.galaxy_y)||0);
 taken.add(stellarionCoordKeyV16(0,0));
 if(attempt<=0 && !taken.has(stellarionCoordKeyV16(bx,by))) return {galaxy_x:bx,galaxy_y:by};
 for(let step=Math.max(1,attempt); step<attempt+80; step++){
  const ring=Math.ceil(step/8);
  const positions=[
   [ring,0],[-ring,0],[0,ring],[0,-ring],
   [ring,ring],[-ring,ring],[ring,-ring],[-ring,-ring]
  ];
  const pos=positions[step%positions.length];
  const c={galaxy_x:bx+pos[0],galaxy_y:by+pos[1]};
  if(!taken.has(stellarionCoordKeyV16(c.galaxy_x,c.galaxy_y))) return c;
 }
 return {galaxy_x:bx+attempt+81,galaxy_y:by};
}
function applyGalaxyCoordToHomeV16(row){
 if(!row || !Number.isFinite(Number(row.galaxy_x)) || !Number.isFinite(Number(row.galaxy_y))) return false;
 const planets=Array.isArray(state.planets)?state.planets:[];
 const home=planets.find(p=>p&&p.isHomeworld)||planets[0];
 if(!home) return false;
 home.galaxyX=Number(row.galaxy_x);
 home.galaxyY=Number(row.galaxy_y);
 if(Number(row.sector)) home.sector=Number(row.sector);
 if(Number(row.system)) home.system=Number(row.system);
 return true;
}
async function claimUniqueGalaxyCoordV16(user,row=null){
 if(!supa || !user || !user.id) return null;
 const base=stellarionPlayerGalaxyCoord() || {galaxy_x:0,galaxy_y:0,sector:null,system:null};
 const taken=new Set();
 let rowCoordTaken=false;
 try{
  const {data,error}=await supa.from('players').select('id,galaxy_x,galaxy_y').not('galaxy_x','is',null).not('galaxy_y','is',null);
  if(!error && Array.isArray(data)){
   const rowKey=row?stellarionCoordKeyV16(row.galaxy_x,row.galaxy_y):"";
   data.forEach(p=>{
    if(!p)return;
    const key=stellarionCoordKeyV16(p.galaxy_x,p.galaxy_y);
    if(p.id!==user.id) taken.add(key);
    if(rowKey && p.id!==user.id && key===rowKey) rowCoordTaken=true;
   });
  }
 }catch(e){}
 const rowX=Math.round(Number(row&&row.galaxy_x)||0), rowY=Math.round(Number(row&&row.galaxy_y)||0);
 const rowIsAssigned=!!(row && Number.isFinite(Number(row.galaxy_x)) && Number.isFinite(Number(row.galaxy_y)));
 if(rowIsAssigned && !(rowX===0&&rowY===0) && !rowCoordTaken){
  applyGalaxyCoordToHomeV16(row);
  return row;
 }
 for(let attempt=0; attempt<120; attempt++){
  const coord=stellarionCoordCandidateV16(base,attempt,taken);
  taken.add(stellarionCoordKeyV16(coord.galaxy_x,coord.galaxy_y));
  const payload={
   id:user.id,
   username:currentPseudoV16(),
   last_seen:new Date().toISOString(),
   galaxy_x:coord.galaxy_x,
   galaxy_y:coord.galaxy_y,
   sector:Number(base.sector)||null,
   system:Number(base.system)||null
    ,...stellarionHomePlanetPublicSnapshotV16()
   };
   const {data,error}=await stellarionUpsertPlayerV16(payload,'id,galaxy_x,galaxy_y,sector,system,home_planet_id,home_planet_name,home_planet_type,home_planet_world');
  if(!error){
   applyGalaxyCoordToHomeV16(data||payload);
   return data||payload;
  }
  if(stellarionIsUniqueCoordErrorV16(error)) continue;
  console.warn('claimUniqueGalaxyCoordV16 error',error);
  return null;
 }
 console.warn('claimUniqueGalaxyCoordV16: aucune coordonnee libre trouvee');
 return null;
}

ensureCloudPlayerV15 = async function(user){
 if(!supa || !user || !user.id) return false;
 const payload={
   id:user.id,
   username:currentPseudoV16(),
   last_seen:new Date().toISOString(),
   ...stellarionHomePlanetPublicSnapshotV16()
  };
 // Stats du joueur, pour que les AUTRES voient son vrai score dans le classement.
 try{
  if(typeof window.lbfMyStatsForCloud === "function"){
   const st = window.lbfMyStatsForCloud();
   if(st){
    payload.empire   = Math.max(0, Math.round(Number(st.empire)||0));
    payload.fleet    = Math.max(0, Math.round(Number(st.fleet)||0));
    payload.defense  = Math.max(0, Math.round(Number(st.defense)||0));
    payload.military = Math.max(0, Math.round(Number(st.military)|| (payload.fleet + payload.defense)));
    payload.total    = Math.max(0, Math.round(Number(st.total)|| (payload.empire + payload.military)));
    payload.planets  = Math.max(1, Math.round(Number(st.planets)||1));
    if(st.alliance) payload.alliance = String(st.alliance).slice(0,32);
    if(st.country)  payload.country  = String(st.country).slice(0,60);
    if(st.flag)     payload.flag     = String(st.flag).slice(0,16);
   }
  }
 }catch(e){}
  const {error}=await stellarionUpsertPlayerV16(payload);
 if(error){ console.warn('V16 players upsert error',error); return false; }
 return true;
};

async function loadPlayerProfileV16(user){
 if(!supa || !user || !user.id) return null;
 try{
  let {data,error}=await supa.from('players').select('id,username,created_at,last_seen,galaxy_x,galaxy_y,sector,system,home_planet_id,home_planet_name,home_planet_type,home_planet_world').eq('id',user.id).maybeSingle();
  if(stellarionMissingPlayerVisualSchemaV16(error)){
   const old=await supa.from('players').select('id,username,created_at,last_seen,galaxy_x,galaxy_y,sector,system').eq('id',user.id).maybeSingle();
   data=old.data; error=old.error;
  }
  if(error) throw error;
  if(data){
   const profile=normalizeProfileFromRowV16(data);
   applyProfileToStateV16(profile);
   // Position galaxie : le serveur fait foi. On réapplique la coordonnée stockée au
   // home pour garder la même place partout ; si la ligne n'en a pas encore (ancien
   // compte), ensureCloudPlayerV15 ci-dessous la renseigne depuis le home local.
   try{
    if(Number.isFinite(Number(data.galaxy_x)) && Number.isFinite(Number(data.galaxy_y))){
     const planets=Array.isArray(state.planets)?state.planets:[];
     const home=planets.find(p=>p&&p.isHomeworld)||planets[0];
     if(home){ home.galaxyX=Number(data.galaxy_x); home.galaxyY=Number(data.galaxy_y); if(Number(data.sector))home.sector=Number(data.sector); if(Number(data.system))home.system=Number(data.system); }
    }
   }catch(e){}
   try{ await ensureCloudPlayerV15(user); }catch(e){}
   try{ await claimUniqueGalaxyCoordV16(user,data); }catch(e){ console.warn('claimUniqueGalaxyCoordV16',e); }
   __profileLoadedV16=true;
   try{ __saveLocalOriginalV15 ? __saveLocalOriginalV15() : localStorage.setItem(SAVE_KEY,JSON.stringify(state)); }catch(e){}
   return profile;
  }
  await ensureCloudPlayerV15(user);
  try{ await claimUniqueGalaxyCoordV16(user,null); }catch(e){ console.warn('claimUniqueGalaxyCoordV16',e); }
  __profileLoadedV16=true;
 }catch(e){
  console.warn('loadPlayerProfileV16',e);
 }
 return null;
}

async function savePlayerProfileV16(closeAfter=false){
 if(!supa || !currentUser || !currentUser.id){ alert('Connexion requise pour sauvegarder le profil.'); return false; }
 if(__profileSaveBusyV16){ __profileSaveQueuedV16=true; return false; }
 __profileSaveBusyV16=true;
 try{
  const pseudo=safeTextV16(document.getElementById('profile-pseudo-v16')?.value || currentPseudoV16(),32) || 'Commandant';
  const country=safeTextV16(document.getElementById('profile-country-v16')?.value || '',60);
  const flag=safeTextV16(document.getElementById('profile-flag-v16')?.value || '',16);
  const avatar=safeTextV16(document.getElementById('profile-avatar-v16')?.value || '',700);
  const motto=safeTextV16(document.getElementById('profile-motto-v16')?.value || '',120);
  const description=safeTextV16(document.getElementById('profile-description-v16')?.value || '',700);
  Object.assign(state,{playerName:pseudo,playerCountry:country,playerFlag:flag,playerAvatar:avatar,playerMotto:motto,playerDescription:description,profileVersion:STELLARION_V16_PROFILE_VERSION});
  const {error}=await stellarionUpsertPlayerV16({
   id:currentUser.id,
   username:pseudo,
   last_seen:new Date().toISOString(),
   ...stellarionHomePlanetPublicSnapshotV16()
  });
  if(error) throw error;
  try{ save(); }catch(e){}
  setCloudStatusV15('profil sauvegardé');
  render();
  addAccountWidgetV16();
  if(closeAfter) closeProfileModalV16();
  return true;
 }catch(e){
  console.warn('savePlayerProfileV16',e);
  alert('Erreur sauvegarde profil : '+(e.message||e));
  return false;
 }finally{
  __profileSaveBusyV16=false;
  if(__profileSaveQueuedV16){ __profileSaveQueuedV16=false; setTimeout(()=>savePlayerProfileV16(false),700); }
 }
}

function profileModalHtmlV16(){
 const pseudo=currentPseudoV16();
 const country=safeTextV16(state?.playerCountry||'',60);
 const flag=safeTextV16(state?.playerFlag||'',16);
 const avatar=safeTextV16(state?.playerAvatar||'',700);
 const motto=safeTextV16(state?.playerMotto||'',120);
 const description=safeTextV16(state?.playerDescription||'',700);
 const email=safeTextV16(currentUser?.email||'',120);
 return `<div id="profile-modal-v16" class="v16-modal-backdrop" onclick="if(event.target.id==='profile-modal-v16')closeProfileModalV16()">
  <div class="v16-profile-modal card">
   <div class="v16-modal-head"><div><span class="pill">COMPTE JOUEUR V16</span><h2>Profil commandant</h2><p class="tiny muted">Compte : ${email||'mode local'}</p></div><button class="btn btn-ghost" onclick="closeProfileModalV16()">✕</button></div>
   <div class="v16-profile-grid">
    <div>
     <label>Pseudo</label><input id="profile-pseudo-v16" maxlength="32" value="${pseudo.replace(/"/g,'&quot;')}">
     <label>Pays d’origine</label><input id="profile-country-v16" maxlength="60" placeholder="France, Algérie, Belgique…" value="${country.replace(/"/g,'&quot;')}">
     <label>Drapeau / symbole court</label><input id="profile-flag-v16" maxlength="16" placeholder="🇫🇷" value="${flag.replace(/"/g,'&quot;')}">
     <label>Devise courte</label><input id="profile-motto-v16" maxlength="120" placeholder="Ex : La galaxie ne dort jamais" value="${motto.replace(/"/g,'&quot;')}">
    </div>
    <div>
     <label>Image / avatar URL</label><input id="profile-avatar-v16" maxlength="700" placeholder="https://…" value="${avatar.replace(/"/g,'&quot;')}">
     <div class="v16-avatar-preview">${avatar?`<img src="${avatar.replace(/"/g,'&quot;')}" onerror="this.remove();this.parentElement.textContent='Image invalide';">`:`<span>${(flag||'👤')}</span>`}</div>
    </div>
   </div>
   <label>Description publique</label><textarea id="profile-description-v16" maxlength="700" placeholder="Présente ton empire, ton style de jeu, ton alliance…">${description.replace(/</g,'&lt;')}</textarea>
   <div class="v16-profile-actions"><button class="btn btn-ghost" onclick="pushCloudSaveV15(true)">Forcer sauvegarde cloud</button><button class="btn" onclick="savePlayerProfileV16(true)">Sauvegarder profil</button><button class="btn btn-danger" onclick="logoutPlayer()">Déconnexion</button></div>
  </div>
 </div>`;
}
function openProfileModalV16(){
 closeProfileModalV16();
 document.body.insertAdjacentHTML('beforeend',profileModalHtmlV16());
}
function closeProfileModalV16(){ document.getElementById('profile-modal-v16')?.remove(); }

async function resetPasswordV16(){
 if(!supa){ authMessage('Serveur indisponible.'); return; }
 const email=(document.getElementById('auth-email')?.value||'').trim();
 if(!email){ authMessage('Entre ton email puis clique à nouveau.'); return; }
 try{
  const {error}=await supa.auth.resetPasswordForEmail(email,{redirectTo:location.href.split('#')[0]});
  if(error) throw error;
  authMessage('Email de récupération envoyé si le compte existe.',true);
 }catch(e){ authMessage(traduireErreurAuth(e.message||e)); }
}

function upgradeAuthScreenV16(){
 try{
  const box=document.getElementById('auth-message');
  if(box && !document.getElementById('auth-reset-v16')){
   box.insertAdjacentHTML('afterend',`<button id="auth-reset-v16" type="button" onclick="resetPasswordV16()" style="width:100%;margin:0 0 10px;padding:10px;border-radius:10px;border:1px solid rgba(79,195,247,.25);background:rgba(255,255,255,.04);color:#9fdcff;font-weight:700;cursor:pointer">Mot de passe oublié</button>`);
  }
  const sub=document.getElementById('auth-submit');
  if(sub) sub.textContent = (__authMode==='signup')?'Créer mon empire':'Se connecter';
 }catch(e){}
}

function addAccountWidgetV16(){
 try{
  const top=document.querySelector('.topbar') || document.querySelector('[class*="topbar"]');
  if(!top) return;
  let chip=document.getElementById('account-chip-v16');
  if(!chip){
   chip=document.createElement('button'); chip.id='account-chip-v16'; chip.className='account-chip-v16'; chip.type='button'; chip.onclick=openProfileModalV16;
   top.appendChild(chip);
  }
  const flag=safeTextV16(state?.playerFlag||'',16);
  chip.innerHTML=`<span>${flag||'👤'}</span><strong>${currentPseudoV16()}</strong><small>${currentUser?'Connecté':'Local'}</small>`;
 }catch(e){}
}

const __authSetModeV15 = authSetMode;
authSetMode = function(mode){ __authSetModeV15(mode); upgradeAuthScreenV16(); };

const __onAuthenticatedV15_forV16 = onAuthenticated;
onAuthenticated = async function(user){
 await __onAuthenticatedV15_forV16(user);
 try{ if(user) await loadPlayerProfileV16(user); }catch(e){}
 try{ addAccountWidgetV16(); }catch(e){}
 try{ render(); addAccountWidgetV16(); }catch(e){}
};

(function(){
 const oldRenderV16=render;
 render=function(){ oldRenderV16(); addAccountWidgetV16(); };
})();

if(supa){
 try{
  supa.auth.onAuthStateChange((event,session)=>{
   if(event==='SIGNED_OUT') return;
   if(event==='PASSWORD_RECOVERY') authMessage('Tu peux définir ton nouveau mot de passe.',true);
   if(session?.user && !__gameStarted) onAuthenticated(session.user);
  });
 }catch(e){}
}
upgradeAuthScreenV16();

// Tout est défini : on peut vérifier la session et démarrer (ou afficher la connexion).
setTimeout(initAuth, 0);
;

