    if(m.includes("scan")||m.includes("spy")||m.includes("espion"))return {c:"#69f0ae",name:"Espionnage"};
    if(m.includes("transfer")||m.includes("transport")||m.includes("support"))return {c:"#4fc3f7",name:"Transfert"};
    if(m.includes("colon"))return {c:"#ce93d8",name:"Colonisation"};
