    if(!ctx||!f||!f.from||!f.to)return;
    const st=missionStyle(f.mission), col=st.c;
    const A=f.returning?f.to:f.from, B=f.returning?f.from:f.to;
    const ax=cx+(Number(A.x)||0)*zoom, ay=cy+(Number(A.y)||0)*zoom;
    const bx=cx+(Number(B.x)||0)*zoom, by=cy+(Number(B.y)||0)*zoom;
    const now=performance.now()/1000, dur=Math.max(.001,Number(f.duration)||1);
    const p=Math.max(0,Math.min(1,(now-(Number(f.startTime)||0))/dur));
    const fx=ax+(bx-ax)*p, fy=ay+(by-ay)*p, ang=Math.atan2(by-ay,bx-ax);

