    ctx.moveTo(.25*u,-.16*u);ctx.lineTo(-.68*u,-1.15*u);ctx.lineTo(-1.2*u,-.95*u);ctx.lineTo(-.70*u,-.18*u);ctx.closePath();ctx.fill();
    const body=ctx.createLinearGradient(0,-.45*u,0,.45*u);body.addColorStop(0,"#f6fbff");body.addColorStop(.50,"#9eb2cc");body.addColorStop(1,"#30425c");
    ctx.fillStyle=body;ctx.beginPath();ctx.moveTo(1.95*u,0);ctx.lineTo(.38*u,.42*u);ctx.lineTo(-1.25*u,.28*u);ctx.lineTo(-1.25*u,-.28*u);ctx.lineTo(.38*u,-.42*u);ctx.closePath();ctx.fill();
