(function(){
  const previousSystemPanelHtml = window.systemPanelHtml;

  function esc38(v){
    return String(v==null?"":v).replace(/[&<>"']/g,function(m){
      return {"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[m];
    });
  }

  function coord38ForSelected(s){
    if(typeof cwmCoordForSystem==="function"&&(s||state.selected))return cwmCoordForSystem(s||state.selected);
    if(state&&state.uiState&&state.uiState.selectedTargetCoord){
      const c=state.uiState.selectedTargetCoord;
      if(Number.isFinite(Number(c.x))&&Number.isFinite(Number(c.y)))return {x:Math.round(Number(c.x)),y:Math.round(Number(c.y))};
    }
    const x=Math.round(Number((s&&s.x)||0)/18), y=Math.round(Number((s&&s.y)||0)/18);
    return {x,y};
  }

  function planet38At(c,s){
    const p=(typeof gwmPlanetAt==="function")?gwmPlanetAt(c.x,c.y):null;
    if(p)return p;
    if(s&&s.owned&&s.planetId){
      const owned=(state.planets||[]).find(function(x){return x.id===s.planetId});
      return Object.assign({},owned||{}, {system:s,kind:"player",name:(owned&&owned.name)||s.name,owned:true,planetId:s.planetId,hostile:false,type:(owned&&owned.isHomeworld)?"home":"owned_colony",galaxyX:c.x,galaxyY:c.y,x:c.x,y:c.y});
    }
    return {system:s,kind:"empty",name:(s&&s.name)||("Position ["+c.x+" | "+c.y+"]"),owned:false,hostile:false,type:(s&&s.type)||"neutral"};
  }

  function asset38For(p,c){
    const asset=(typeof vlibAssetFor==="function")?vlibAssetFor(p,c.x,c.y):null;
    if(asset&&asset.html)return asset.html;
    if(asset&&asset.src)return '<img class="gwm-planet-img" src="'+esc38(asset.src)+'" alt="'+esc38(p.name||"Planete")+'">';
    return '<div class="planet" style="background:radial-gradient(circle at 35% 25%,white,#4FC3F7 35%,#061431 80%)"></div>';
  }

  function status38(p,s){
    if(p&&p.owned)return "Colonie possedee";
    if(p&&p.quest)return "Objectif IA / quete";
    if((p&&p.hostile)||(s&&s.type==="hostile"))return "Planete hostile";
    if(s&&s.temp)return "Position neutre";
    return "Planete selectionnee";
  }

  function owner38(p,s){
    const src=(p&&p.cloudPlayer?p:s&&s.cloudPlayer?s:null)||{};
    const playerId=src.playerId||src.id||"";
    const name=src.ownerName||src.username||src.playerName||src.name||"Inconnu";
    if(playerId)return {name:name,playerId:String(playerId),known:true};
    if(p&&p.owned)return {name:"Vous",playerId:"",known:true};
    if(p&&p.quest)return {name:"IA hostile",playerId:"",known:false};
    return {name:"Inconnu",playerId:"",known:false};
  }

  window.stellarionOpenOwnerMessage38=function(btn){
    const name=String((btn&&btn.dataset&&btn.dataset.name)||"Commandant voisin");
    const playerId=String((btn&&btn.dataset&&btn.dataset.pid)||"");
    const planet=String((btn&&btn.dataset&&btn.dataset.planet)||"cette planete");
    if(!playerId){try{addLog("Proprietaire inconnu : envoie un drone pour obtenir plus d'informations.");}catch(e){}return false;}
    try{
      if(typeof openComposer==="function")openComposer(name,"Contact depuis la galaxie","Salut, je te contacte au sujet de "+planet+".",playerId);
      else if(typeof openComposerForSystem==="function")openComposerForSystem(playerId,"galaxy");
    }catch(e){}
    return false;
  };

  /* Panneau d'actions du haut (Attaquer/Espionner/Transferer/Coloniser) supprime :
     les actions restent disponibles dans le Centre de mission plus bas. */

  function selectedGalaxyPlanetPanel38(s){
    if(!state||state.view!=="galaxy")return "";
    const base=s||state.selected||activePlanetSystem();
    if(!base)return "";
    const c=coord38ForSelected(base);
    const realSystem=(typeof gwmSystemAt==="function"?gwmSystemAt(c.x,c.y):null)||base;
    const p=planet38At(c,realSystem);
    const name=(p&&p.name)||(realSystem&&realSystem.name)||("Position ["+c.x+" | "+c.y+"]");
    const pos=(typeof gwmCoordText==="function"?gwmCoordText(c.x,c.y):("["+c.x+" | "+c.y+"]"));
    const type=(p&&p.type)||(realSystem&&realSystem.type)||"neutral";
    const badge=(p&&p.owned)?"COLONIE POSSEDEE":(p&&p.quest)?"OBJECTIF IA":((p&&p.hostile)||(realSystem&&realSystem.type==="hostile"))?"HOSTILE":"PLANETE";
    const border=(typeof systemColor==="function"?systemColor((realSystem&&realSystem.type)||type):"#4FC3F7");
    const mission=(p&&p.owned)?"":((typeof missionPlannerHtml==="function")?missionPlannerHtml(realSystem):"");
    const owner=owner38(p,realSystem);
    const ownerButton=owner.playerId
      ? '<button class="btn btn-ghost" type="button" style="width:100%;text-align:left" data-pid="'+esc38(owner.playerId)+'" data-name="'+esc38(owner.name)+'" data-planet="'+esc38(name)+'" onclick="return stellarionOpenOwnerMessage38(this)">'+esc38(owner.name)+' <span class="tiny muted">message prive</span></button>'
      : '<strong>'+esc38(owner.name)+'</strong>';
    return '<div class="card panel selected-row galaxy-selected-card">'
      + '<span class="pill" style="border-color:'+esc38(border)+'">'+badge+'</span>'
      + '<h2>'+esc38(name)+'</h2>'
      + '<div class="coord-pill" data-pos="'+esc38(pos)+'" title="Copier la position" onclick="gwmCopy(this.dataset.pos)">Position '+esc38(pos)+'</div>'
      + '<div class="gwm-selection-preview">'+asset38For(p,c)+'</div>'
      + '<div class="galaxy-selected-meta">'
      + '<div class="resource"><span>Proprietaire</span>'+ownerButton+'</div>'
      + '<div class="resource"><span>Statut</span><strong>'+esc38(status38(p,realSystem))+'</strong></div>'
      + '</div>'
      + '<div class="gwm-selection-actions" style="margin-top:12px">'
      + '<button class="btn" onclick="gwmSetCamera('+c.x+','+c.y+',gwmCamera().zoom)">Centrer</button>'
      + '<button class="btn btn-ghost" data-pos="'+esc38(pos)+'" onclick="gwmCopy(this.dataset.pos)">Copier position</button>'
      + ((p&&p.owned&&p.planetId)?'<button class="btn btn-ghost" data-pid="'+esc38(p.planetId)+'" onclick="state.activePlanetId=this.dataset.pid;setView(&quot;planet&quot;)">Voir planete</button>':'')
      + '</div>'
      + (mission?'<div class="galaxy-mission-wrap">'+mission+'</div>':'')
      + '</div>';
  }

  window.systemPanelHtml=function(s){
    if(state&&state.view==="galaxy"){
      const panel=selectedGalaxyPlanetPanel38(s);
      if(panel){
        setTimeout(function(){try{if(typeof atlasInitCanvases==="function")atlasInitCanvases(document.querySelector(".side.right"));}catch(e){}},0);
        return panel;
      }
    }
    return (typeof previousSystemPanelHtml==="function")?previousSystemPanelHtml(s):"";
  };
})();
;

