/* ---- bloc script (source: ligne ~21704) ---- */
/* Alpha 1.5.30 — nettoyage rendu flottes galaxie
   Problème constaté : après changement de vue/re-render, des marqueurs de flotte retour peuvent rester empilés.
   Solution :
   - assainit state.fleets au chargement et avant render ;
   - supprime les doublons visuels de flottes ;
   - nettoie les anciens marqueurs DOM quand on quitte / revient Galaxie ;
   - limite les pastilles "retour" abusives et évite les ghosts x124.
*/
(function(){
 function now150(){return performance.now()/1000}
 function fleetKey150(f){
  return [
   f&&f.mission||"",
   f&&f.returning?"return":"go",
   f&&f.originPlanetId||"",
   f&&f.to&&f.to.id||f&&f.to&&f.to.name||"",
   f&&f.from&&f.from.id||f&&f.from&&f.from.name||"",
   Math.round(Number(f&&f.startTime)||0)
  ].join("|");
 }
 function normalizeFleet150(f){
  if(!f||typeof f!=="object")return null;
  if(!f.id)f.id="f_clean_"+Math.random().toString(36).slice(2);
  f.ships=f.ships||{};
  f.cargo=f.cargo||{titanium:0,xenite:0,antimatter:0};
  f.duration=Math.max(6,Math.min(3600,Number(f.duration)||30));
  f.startTime=Number(f.startTime)||now150();
  if(!f.from&&typeof activePlanetSystem==="function")f.from=activePlanetSystem();
  if(!f.to)f.to={name:"Mission inconnue",x:0,y:0,id:"unknown"};
  return f;
 }
 window.stellarionCleanFleetState150=function(){
  state.fleets=Array.isArray(state.fleets)?state.fleets:[];
  const t=now150();
  const seen=new Set();
  const clean=[];
  for(const raw of state.fleets){
   const f=normalizeFleet150(raw);
   if(!f)continue;
   const elapsed=t-(Number(f.startTime)||t);
   // Flotte anormalement vieille ou terminée bloquée : on la purge.
   if(f.done===true)continue;
   if(elapsed>Math.max(90,(Number(f.duration)||30)*8))continue;
   const key=fleetKey150(f);
   if(seen.has(key))continue;
   seen.add(key);
   clean.push(f);
  }
  if(clean.length!==state.fleets.length){
   state.fleets=clean;
   try{save&&save()}catch(e){}
  }
  state.__fleetRenderCleaned150=true;
  return {count:state.fleets.length};
 };
 function removeGhostFleetNodes150(){
  try{
   // On ne supprime que les éléments liés aux flottes/missions visuelles, pas les planètes.
   const selectors=[
    ".fleet-ghost",
    ".fleet-marker",
    ".fleet-path",
    ".fleet-route",
    ".active-fleet",
    ".mission-fleet-marker",
    ".gwm-fleet",
    "[data-fleet-id]",
    "[data-fleet-marker]"
   ];
   document.querySelectorAll(selectors.join(",")).forEach(el=>{
    if(!el.closest(".log")&&!el.closest(".messages")&&!el.closest(".bottom-queue"))el.remove();
   });
  }catch(e){}
 }
 function dedupeVisibleFleetBadges150(){
  try{
   const seen=new Set();
   const nodes=[...document.querySelectorAll(".galaxy-map *")].filter(el=>{
    const txt=(el.textContent||"").trim();
    return /retour|attaque|espionnage|transfert|colonisation/i.test(txt) && /x\d+|0:\d+|\d+s/i.test(txt);
   });
   for(const el of nodes){
    const box=el.getBoundingClientRect();
    const key=[Math.round(box.left/8),Math.round(box.top/8),el.textContent.trim().slice(0,40)].join("|");
    if(seen.has(key))el.remove();
    else seen.add(key);
   }
  }catch(e){}
 }
 function afterRenderFleetClean150(){
  if(!(state&&state.view==="galaxy"))return;
  stellarionCleanFleetState150();
  dedupeVisibleFleetBadges150();
 }
 const oldRender150=window.render;
 if(typeof oldRender150==="function"&&!oldRender150.__fleetRenderCleanup150){
  const patched=function(){
   try{
    if(state&&state.view!=="galaxy")removeGhostFleetNodes150();
    stellarionCleanFleetState150();
   }catch(e){}
   const r=oldRender150.apply(this,arguments);
   requestAnimationFrame(afterRenderFleetClean150);
   setTimeout(afterRenderFleetClean150,60);
   return r;
  };
  patched.__fleetRenderCleanup150=true;
  window.render=patched;
 }
 document.addEventListener("visibilitychange",()=>{try{stellarionCleanFleetState150()}catch(e){}});
 setTimeout(()=>{try{stellarionCleanFleetState150(); if(state&&state.view==="galaxy")afterRenderFleetClean150();}catch(e){}},300);
 window.stellarionFleetRenderAudit150=function(){
  return {
   build:"1.5.0 Galaxy Fleet Render Cleanup",
   view:state&&state.view,
   fleets:Array.isArray(state&&state.fleets)?state.fleets.length:0,
   cleaned:!!(state&&state.__fleetRenderCleaned150),
   renderPatched:!!(window.render&&window.render.__fleetRenderCleanup150)
  };
 };
})();
;

/* ---- bloc script (source: ligne ~21829) ---- */
/* Alpha 1.5.30 — verrou scroll colonne droite flotte galaxie
   Correction ciblée : dans la colonne droite Galaxie, +1 / -1 / MAX ne doit plus remonter le panneau.
*/
(function(){
 let lock151=null;
 function rightScrollTargets151(){
  const arr=[];
  const sels=[
   ".side.right",
   ".galaxy-selected-card",
   ".galaxy-mission-wrap",
   ".mission-compact",
   ".mission-ship-list",
   ".mission-panel",
   ".fleet-drawers",
   "#center",
   ".center",
   ".main",
   ".app"
  ];
  for(const sel of sels){
   document.querySelectorAll(sel).forEach(el=>{
    if(el && !arr.includes(el))arr.push(el);
   });
  }
  arr.push(document.scrollingElement,document.documentElement,document.body);
  return arr.filter(Boolean);
 }
 function captureRightScroll151(){
  try{
   lock151={
    time:performance.now(),
    winX:window.scrollX||0,
    winY:window.scrollY||0,
    active:document.activeElement,
    items:rightScrollTargets151().map((el,idx)=>({
     idx,
     el,
     top:el.scrollTop||0,
     left:el.scrollLeft||0
    }))
   };
  }catch(e){}
 }
 function restoreRightScroll151(){
  try{
   if(!lock151||performance.now()-lock151.time>2500)return;
   window.scrollTo(lock151.winX||0,lock151.winY||0);
   for(const item of lock151.items||[]){
    if(item.el){
     item.el.scrollTop=item.top||0;
     item.el.scrollLeft=item.left||0;
    }
   }
   if(lock151.active && lock151.active.blur)lock151.active.blur();
  }catch(e){}
 }
 function restoreMany151(){
  restoreRightScroll151();
  requestAnimationFrame(()=>{restoreRightScroll151();requestAnimationFrame(restoreRightScroll151)});
  setTimeout(restoreRightScroll151,0);
  setTimeout(restoreRightScroll151,50);
  setTimeout(restoreRightScroll151,120);
  setTimeout(restoreRightScroll151,260);
 }
 function isFleetControl151(target){
  if(!(state&&state.view==="galaxy"))return false;
  if(!target||!target.closest)return false;
  const el=target.closest("button,input,[onclick]");
  if(!el)return false;
  const code=[
   el.getAttribute("onclick")||"",
   el.getAttribute("oninput")||"",
   el.className||"",
   el.textContent||"",
   target.className||""
  ].join(" ");
  return /addMissionShip|setMissionShip|maxMissionShip|clearMissionShip|mission-stepper|mission-max-btn|mission-ship-line|\+1|-1|MAX/i.test(code);
 }
 document.addEventListener("pointerdown",e=>{if(isFleetControl151(e.target))captureRightScroll151();},true);
 document.addEventListener("mousedown",e=>{if(isFleetControl151(e.target))captureRightScroll151();},true);
 document.addEventListener("click",e=>{
  if(isFleetControl151(e.target)){
   // Alpha 1.5.30 : ne PAS bloquer le onclick.
   // On capture/restaure le scroll, mais on laisse +1 / -1 / MAX exécuter leur action.
   captureRightScroll151();
   setTimeout(restoreMany151,0);
  }
 },true);
 document.addEventListener("input",e=>{if(isFleetControl151(e.target)){captureRightScroll151();restoreMany151();}},true);
 document.addEventListener("change",e=>{if(isFleetControl151(e.target)){captureRightScroll151();restoreMany151();}},true);

 function wrap151(name){
  const old=window[name];
  if(typeof old==="function"&&!old.__rightScroll151){
   const patched=function(){
    captureRightScroll151();
    const r=old.apply(this,arguments);
    restoreMany151();
    return r;
   };
   patched.__rightScroll151=true;
   window[name]=patched;
  }
 }
 // Ces fonctions sont la source exacte du bug.
 wrap151("setMissionShip");
 wrap151("addMissionShip");
 wrap151("maxMissionShip");
 wrap151("clearMissionShip");
 wrap151("updateMissionPlannerLive");

 const oldRender=window.render;
 if(typeof oldRender==="function"&&!oldRender.__rightColumnFleetScroll151){
  const patched=function(){
   const active=!!(lock151&&performance.now()-lock151.time<2500);
   const r=oldRender.apply(this,arguments);
   if(active)restoreMany151();
   return r;
  };
  patched.__rightColumnFleetScroll151=true;
  window.render=patched;
 }
 window.stellarionRightFleetScrollAudit151=function(){
  const right=document.querySelector(".side.right");
  return {
   build:"1.5.2 Max Button Fleet Hotfix",
   view:state&&state.view,
   locked:!!lock151,
   rightScrollTop:right?right.scrollTop:null,
   setMissionShipWrapped:!!(window.setMissionShip&&window.setMissionShip.__rightScroll151),
   addMissionShipWrapped:!!(window.addMissionShip&&window.addMissionShip.__rightScroll151),
   renderWrapped:!!(window.render&&window.render.__rightColumnFleetScroll151)
  };
 };
})();
;

