(function(){
  function eco(){try{return (getPerformanceMode1517&&getPerformanceMode1517())==="eco"}catch(e){return true}}
  const rawRAF=window.requestAnimationFrame.bind(window);
  let lastEcoFrame=0;
  window.requestAnimationFrame=function(cb){
    if(!eco()) return rawRAF(cb);
    // En mode éco : throttle global RAF à environ 4 fps max pour les animations décoratives.
    return rawRAF(function(ts){
      if(ts-lastEcoFrame<250){
        return;
      }
      lastEcoFrame=ts;
      try{cb(ts)}catch(e){console.error(e)}
    });
  };
  window.stellarionPerformanceAudit1517=function(){
    const anim=[...document.querySelectorAll("*")].filter(el=>{
      const s=getComputedStyle(el);
      return s.animationName && s.animationName!=="none" && s.animationDuration!=="0s";
    }).length;
    const filtered=[...document.querySelectorAll("*")].filter(el=>{
      const s=getComputedStyle(el);
      return s.filter && s.filter!=="none";
    }).length;
    return {
      build:"1.5.17 Performance Saver",
      mode:getPerformanceMode1517?getPerformanceMode1517():"unknown",
      animatedElements:anim,
      filteredElements:filtered,
      canvases:document.querySelectorAll("canvas").length,
      globalSwitcher:!!document.querySelector(".global-planet-switcher1512"),
      rallyCustom:!!document.querySelector(".rally-custom1516")
    };
  };
})();
