    try{if(typeof window.cwmCoordForSystem==='function'){const c=window.cwmCoordForSystem(obj);if(c&&Number.isFinite(Number(c.x))&&Number.isFinite(Number(c.y)))return {x:Number(c.x),y:Number(c.y)}}}catch(e){}
