/* ---- bloc script (source: ligne ~24382) ---- */
(function(){
  /* STELLARION V1 CLEAN — stockage supprimé.
     Une seule règle : aucune limite artificielle de ressources et aucun bâtiment de stockage. */
  const STORAGE_IDS=['titanium_storage','xenite_storage','antimatter_storage','dark_storage'];
  function isStorageDef(def){return !!(def&&(def.slot==='storage'||def.category==='storage'||def.stores||STORAGE_IDS.includes(def.id)));}
  function purgeStorageArtifacts(){
    try{
      if(Array.isArray(window.BUILDINGS)){
        for(let i=BUILDINGS.length-1;i>=0;i--){ if(isStorageDef(BUILDINGS[i])) BUILDINGS.splice(i,1); }
      }
      if(window.state){
        state.buildQueue=(state.buildQueue||[]).filter(q=>!STORAGE_IDS.includes(q.building_id));
        if(state.selectedBuildingId&&STORAGE_IDS.includes(state.selectedBuildingId))state.selectedBuildingId='titanium_mine_1';
        if(state.buildings){
          for(const pid of Object.keys(state.buildings)){
            state.buildings[pid]=(state.buildings[pid]||[]).filter(r=>!STORAGE_IDS.includes(r.building_id));
          }
        }
      }
    }catch(e){console.warn('Clean stockage: purge ignorée',e)}
  }
  purgeStorageArtifacts();
  const oldCanBuild1542f=window.canBuildOnPlanet;
  if(typeof oldCanBuild1542f==='function'&&!window.__noStorageClean1542f){
    window.__noStorageClean1542f=true;
    window.canBuildOnPlanet=function(def,planet){
      if(isStorageDef(def))return {ok:false,reason:'Stockage supprimé dans Stellarion V1 CLEAN'};
      return oldCanBuild1542f.apply(this,arguments);
    };
  }
  function f(v){try{return fmt(Number(v)||0)}catch(e){return String(Math.round(Number(v)||0)).replace(/\B(?=(\d{3})+(?!\d))/g,' ');}}
  function art(def){try{return window.stellarionBuildingArt?stellarionBuildingArt(def):`<span class="emoji">${def.icon||'⬢'}</span>`}catch(e){return `<span class="emoji">${def.icon||'⬢'}</span>`}}
  function prod(){try{return calcProdForPlanet?calcProdForPlanet(state.activePlanetId):calcProd()}catch(e){return {titanium:0,xenite:0,antimatter:0}}}
  function energy(){try{return calcEnergyForPlanet?calcEnergyForPlanet(state.activePlanetId):calcEnergy()}catch(e){return {balance:0,production:0,consumption:0}}}
  const oldProductionLabel=window.productionLabelForDef;
  window.productionLabelForDef=function(def,level){if(isStorageDef(def))return '';return typeof oldProductionLabel==='function'?oldProductionLabel.apply(this,arguments):'';};
  const oldProductionValue=window.productionValueForDef;
  window.productionValueForDef=function(def,level){if(isStorageDef(def))return 0;return typeof oldProductionValue==='function'?oldProductionValue.apply(this,arguments):0;};
  function queueHtml(){
    purgeStorageArtifacts();
    const q=(state.buildQueue||[]).filter(x=>x.planetId===state.activePlanetId&&!STORAGE_IDS.includes(x.building_id));
    if(!q.length)return '<p class="small muted">Aucune construction active.</p>';
    return q.slice(0,4).map(x=>{const d=BUILDINGS.find(b=>b.id===x.building_id)||{};const remain=Math.max(0,Math.ceil((Number(x.finishAt||0)-Date.now())/1000));return `<div class="cqueue-item1542f">${art(d)}<div><b>${d.name||'Construction'}</b><br><span>Niveau ${x.toLevel||x.to||'?'} · ${f(remain)}s</span></div></div>`}).join('');
  }
  function card(def){
    if(isStorageDef(def))return '';
    const info=buildingUpgradeInfo(def), level=Number(info.row.level)||0, selected=state.selectedBuildingId===def.id;
    const current=def.produces?('+'+f(productionValueForDef(def,level))+productionUnitForDef(def)):productionLabelForDef(def,level);
    const next=def.produces?('Prochain +'+f(productionValueForDef(def,info.next))+productionUnitForDef(def)):productionLabelForDef(def,info.next);
    const blocked=!info.allowed.ok;
    return `<div class="ccard1542f ${selected?'selected':''} ${blocked?'blocked':''}" onclick="__stellarionKeepConstructionScroll(()=>{state.selectedBuildingId='${def.id}';save();render()})">
      <div class="ccard-title1542f"><span>${def.name}</span><small>Niv. ${level}</small></div>
      <div class="ccard-img1542f">${art(def)}</div>
      <div class="ccard-stat1542f"><span>Actuel</span><strong>${current}</strong></div>
      <div class="ccard-stat1542f"><span>Évolution</span><strong>${next}</strong></div>
      <div class="ccard-cost1542f"><span>Ti ${f(info.c.titanium)}</span><span>Xe ${f(info.c.xenite)}</span><span>AM ${f(info.c.antimatter||0)}</span></div>
      <button class="btn" ${info.ok?'':'disabled'} onclick="event.stopPropagation();queueBuilding('${def.id}')">AMÉLIORER</button>
    </div>`;
  }
  function section(title,sub,defs,cls){return `<section class="csection1542f"><h3>${title}</h3><p>${sub}</p><div class="cgrid1542f ${cls||''}">${defs.filter(d=>!isStorageDef(d)).map(card).join('')}</div></section>`;}
  function defs(ids){return ids.map(id=>BUILDINGS.find(b=>b.id===id)).filter(Boolean).filter(d=>!isStorageDef(d));}
  function harvestDefs(type){const p=activePlanet();ensureHarvestSpots(p);const max=(p.harvestSpots||{})[type]||0;return BUILDINGS.filter(b=>!isStorageDef(b)&&b.mineType===type&&(b.variantIndex||1)<=max).sort((a,b)=>(a.variantIndex||1)-(b.variantIndex||1));}
  function summaryHtml(){
    const pr=prod(), en=energy();
    return `<aside class="csummary1542f">
      <div class="csummary-card1542f"><h3>Résumé planète</h3><div class="csum-line1542f"><span>Puissance</span><strong>${f(en.consumption||0)} MW utilisés</strong></div><div class="csum-line1542f"><span>Énergie</span><strong class="${(en.balance||0)>=0?'ok':'error'}">${f(en.balance||0)} MW</strong></div><div class="csum-line1542f"><span>Commandement</span><strong>${f(Object.values(state.defenses||{}).reduce((a,b)=>a+(Number(b)||0),0))}</strong></div></div>
      <div class="csummary-card1542f"><h3>Production totale</h3><div class="csum-line1542f"><span>Titane</span><strong class="ok">+${f(pr.titanium||0)}/h</strong></div><div class="csum-line1542f"><span>Xénite</span><strong class="ok">+${f(pr.xenite||0)}/h</strong></div><div class="csum-line1542f"><span>Antimatière</span><strong class="ok">+${f(pr.antimatter||0)}/h</strong></div></div>
      <div class="csummary-card1542f"><h3>Ressources</h3><p class="small muted">Stockage supprimé : les ressources ne sont plus plafonnées.</p><div class="csum-line1542f"><span>Titane actuel</span><strong>${f((state.resources||{}).titanium||0)}</strong></div><div class="csum-line1542f"><span>Xénite actuelle</span><strong>${f((state.resources||{}).xenite||0)}</strong></div><div class="csum-line1542f"><span>Fragments</span><strong>${f((state.resources||{}).fragments||0)}</strong></div></div>
      <div class="csummary-card1542f"><h3>Construction active</h3>${queueHtml()}</div>
    </aside>`;
  }
  window.constructionDetailPanelHtml=function(){
    purgeStorageArtifacts();
    const def=BUILDINGS.find(b=>b.id===state.selectedBuildingId&&!isStorageDef(b))||BUILDINGS.find(b=>b.id==='titanium_mine_1')||BUILDINGS.find(b=>b.id==='titanium_mine')||BUILDINGS.find(b=>!isStorageDef(b))||BUILDINGS[0];
    const info=buildingUpgradeInfo(def), level=Number(info.row.level)||0;
    const current=def.produces?('+'+f(productionValueForDef(def,level))+productionUnitForDef(def)):productionLabelForDef(def,level);
    const next=def.produces?('+'+f(productionValueForDef(def,info.next))+productionUnitForDef(def)):productionLabelForDef(def,info.next);
    return `<div class="card panel cdetail1542f"><span class="pill">DÉTAIL BÂTIMENT</span><div class="big-img1542f">${art(def)}</div><h2>${def.name}</h2><div class="resource"><span>Niveau</span><strong>${level}</strong></div><div class="resource"><span>Actuel</span><strong>${current}</strong></div><div class="resource"><span>Prochain</span><strong>${next}</strong></div><div class="resource"><span>Coût</span><strong>Ti ${f(info.c.titanium)} · Xe ${f(info.c.xenite)}</strong></div><button class="btn" style="width:100%;margin-top:10px" ${info.ok?'':'disabled'} onclick="queueBuilding('${def.id}')">AMÉLIORER</button><p class="tiny ${info.allowed.ok?'muted':'error'}">${info.allowed.reason||'Bâtiment opérationnel.'}</p></div>`;
  };
  const oldRightPanels1542f=window.rightPanels;
  window.rightPanels=function(){ if(state&&state.view==='buildings')return constructionDetailPanelHtml(); return typeof oldRightPanels1542f==='function'?oldRightPanels1542f.apply(this,arguments):''; };
  window.planetConstructionView=function(){
    purgeStorageArtifacts();
    const p=activePlanet();ensureBuildingCatalogForPlanet(p.id);ensureHarvestSpots(p);purgeStorageArtifacts();
    const cats=[['resources','💠','Ressources','Mines et extracteurs'],['prod','⚡','Production','Énergie et antimatière'],['general','🔧','Commandements & Militaire','Protection, vaisseaux et recherche']];
    const main=`<main class="cmain1542f">
      <div class="cmain-head1542f"><div><span class="pill">CONSTRUCTION</span><h2>${p.name}</h2><p>Construction nettoyée : aucun stockage, aucune limite artificielle de ressources.</p></div></div>
      <section id="section-resources">${section('Ressources','Mines et extracteurs visibles au maximum. Les coûts sont explicitement affichés.',[...harvestDefs('titanium'),...harvestDefs('xenite')])}</section>
      <section id="section-production">${section('Production & développement','Énergie, antimatière, ambassade et infrastructure.',defs(['fusion_plant','antimatter_refinery','embassy','command_center']),'compact')}</section>
      <section id="section-militaire">${section('Militaire & défense','La défense reste visible directement sur Construction.',defs(['shipyard','orbital_base','shield_generator','quantum_lab','academy']),'compact')}</section>
    </main>`;
    return `<div class="construction-clean1542f"><aside class="ccats1542f"><div class="cpanel1542f" style="padding:14px"><span class="pill">CATÉGORIES</span>${cats.map((c,i)=>`<div class="ccat1542f ${i===0?'active':''}" style="cursor:pointer;transition:all 0.2s" onmouseover="this.style.opacity='0.8';this.style.background='rgba(79,195,247,0.1)'" onmouseout="this.style.opacity='1';this.style.background='none'" onclick="const sectionMap={'resources':'resources','prod':'production','general':'militaire'};const target=document.getElementById('section-'+sectionMap['${c[0]}']); if(target)target.scrollIntoView({behavior:'smooth'})"><span class="ico">${c[1]}</span><div><strong>${c[2]}</strong><small>${c[3]}</small></div></div>`).join('')}</div></aside>${main}${summaryHtml()}</div>`;
  };
})();
;

/* ---- bloc script (source: ligne ~24523) ---- */
window.__stellarionKeepConstructionScroll = function(cb){
  const selectors = ['.cmain1542f', '.construction-main', '.building-main', '.buildings-grid'];
  const saved = selectors.map(sel => {
    const el = document.querySelector(sel);
    return el ? {sel, top: el.scrollTop, left: el.scrollLeft} : null;
  }).filter(Boolean);
  const run = () => { if (typeof cb === 'function') cb(); };
  run();
  requestAnimationFrame(() => {
    saved.forEach(s => {
      const el = document.querySelector(s.sel);
      if (el) { el.scrollTop = s.top; el.scrollLeft = s.left; }
    });
  });
  setTimeout(() => {
    saved.forEach(s => {
      const el = document.querySelector(s.sel);
      if (el) { el.scrollTop = s.top; el.scrollLeft = s.left; }
    });
  }, 0);
};
;

