/* ---- bloc script (source: ligne ~24753) ---- */
/* FIX STELLARION — bouton Annuler popup Alliance
   Ferme tous les modals Alliance possibles, même si une ancienne couche bloque le clic. */
(function(){
  function closeAllAlliancePopupsFixed(){
    [
      'allianceModalV5',
      'allianceModalV4',
      'allianceSafeModal'
    ].forEach(function(id){
      var el=document.getElementById(id);
      if(el) el.remove();
    });

    document.querySelectorAll(
      '.alliance-v5-modal,'+
      '.alliance-v4-modal,'+
      '.alliance-safe-modal,'+
      '[id^="allianceModal"],'+
      '[id*="AllianceModal"],'+
      '[id*="allianceModal"]'
    ).forEach(function(el){
      if(el && el.parentNode) el.parentNode.removeChild(el);
    });
  }

  window.closeAllAlliancePopupsFixed = closeAllAlliancePopupsFixed;

  var oldCloseV5 = window.closeAllianceModalV5;
  window.closeAllianceModalV5 = function(){
    try{ if(typeof oldCloseV5 === 'function') oldCloseV5(); }catch(e){}
    closeAllAlliancePopupsFixed();
  };

  var oldCloseV4 = window.closeAllianceModalV4;
  window.closeAllianceModalV4 = function(){
    try{ if(typeof oldCloseV4 === 'function') oldCloseV4(); }catch(e){}
    closeAllAlliancePopupsFixed();
  };

  var oldCloseSafe = window.closeAllianceSafeModal;
  window.closeAllianceSafeModal = function(){
    try{ if(typeof oldCloseSafe === 'function') oldCloseSafe(); }catch(e){}
    closeAllAlliancePopupsFixed();
  };

  document.addEventListener('click', function(e){
    var btn = e.target && e.target.closest && e.target.closest(
      '#allyV5Cancel,'+
      '#allyV4Cancel,'+
      '#allyV5ApplyCancel,'+
      '#allyV4ApplyCancel,'+
      '.alliance-v5-modal-actions .btn-ghost,'+
      '.alliance-v4-modal-actions .btn-ghost,'+
      '.alliance-safe-modal-actions .btn-ghost'
    );
    if(!btn) return;
    var txt=(btn.textContent||'').trim().toLowerCase();
    if(txt.indexOf('annuler') === -1) return;
    e.preventDefault();
    e.stopPropagation();
    closeAllAlliancePopupsFixed();
    return false;
  }, true);

  document.addEventListener('keydown', function(e){
    if(e.key === 'Escape') closeAllAlliancePopupsFixed();
  }, true);
})();
;

/* ---- bloc script (source: ligne ~24831) ---- */
(function(){
  'use strict';
  function getState(){ try{return (typeof state!=='undefined')?state:(window.state||{});}catch(e){return window.state||{};} }
  function exposeGlobals(){
    try{ if(typeof state!=='undefined') window.state=state; }catch(e){}
    try{ if(typeof SHIPS!=='undefined' && Array.isArray(SHIPS)) window.SHIPS=SHIPS; }catch(e){}
    try{ if(typeof DEFENSES!=='undefined' && Array.isArray(DEFENSES)) window.DEFENSES=DEFENSES; }catch(e){}
    try{ if(Array.isArray(window.SHIPS)) window.SHIP_BY_ID=Object.fromEntries(window.SHIPS.map(function(s){return [String(s.id),s];})); }catch(e){}
    try{ if(Array.isArray(window.DEFENSES)) window.DEFENSE_BY_ID=Object.fromEntries(window.DEFENSES.map(function(d){return [String(d.id),d];})); }catch(e){}
  }
  function N(v){return Math.max(0,Number(v)||0)}
  function F(v){try{return Math.round(N(v)).toLocaleString('fr-FR')}catch(e){return String(Math.round(N(v)))}}
  function shipsCatalog(){exposeGlobals();return Array.isArray(window.SHIPS)?window.SHIPS:[]}
  function defensesCatalog(){exposeGlobals();return Array.isArray(window.DEFENSES)?window.DEFENSES:[]}
  function shipDef(id){var list=shipsCatalog();return (window.SHIP_BY_ID&&window.SHIP_BY_ID[String(id)])||list.find(function(s){return String(s.id)===String(id)})||{};}
  function defenseDef(id){var list=defensesCatalog();return (window.DEFENSE_BY_ID&&window.DEFENSE_BY_ID[String(id)])||list.find(function(d){return String(d.id)===String(id)})||{};}
  function shipAttack(id){var s=shipDef(id);return N(s.attack||s.atk||s.power||0)}
  function shipDefense(id){var s=shipDef(id);return N(s.hull||s.structure||s.hp||s.defense||s.coque||0)}
  function shipCargo(id){var s=shipDef(id);return N(s.cargo||0)}
  function shipName(id){var s=shipDef(id);return (s.icon?s.icon+' ':'')+(s.name||String(id).replace(/_/g,' '))}
  function normalize(obj){
    var out={}; if(!obj||typeof obj!=='object')return out;
    if(Array.isArray(obj)){obj.forEach(function(x){merge(out,x)});return out;}
    Object.entries(obj).forEach(function(pair){var key=pair[0],val=pair[1];
      if(val&&typeof val==='object'){
        var id=val.ship_id||val.shipId||val.defense_id||val.defenseId||val.type||val.key||val.id||key;
        var q=val.count??val.qty??val.quantity??val.amount??val.owned??val.available??val.total??val.stock;
        if(id&&N(q)>0)out[id]=(out[id]||0)+N(q);
      }else if(N(val)>0){out[key]=(out[key]||0)+N(val)}
    }); return out;
  }
  function merge(to,from){Object.entries(normalize(from)).forEach(function(pair){if(pair[1]>0)to[pair[0]]=(to[pair[0]]||0)+pair[1]});return to;}
  function planets(){var st=getState();return Array.isArray(st.planets)?st.planets:[]}
  function planetShipsDirect(planetId){
    var st=getState(),out={};
    try{ if(typeof planetShips==='function') merge(out,planetShips(planetId)); }catch(e){}
    merge(out,st.planetShips&&st.planetShips[planetId]);
    merge(out,st.shipsByPlanet&&st.shipsByPlanet[planetId]);
    merge(out,st.fleetsByPlanet&&st.fleetsByPlanet[planetId]);
    merge(out,st.arsenalByPlanet&&st.arsenalByPlanet[planetId]);
    return out;
  }
  function arrayShips(planetId){
    var st=getState(),out={};
    [st.ships,st.playerShips,st.ownedShips,st.shipInventory,st.arsenalShips,st.availableShips,st.fleetStock,st.vessels]
      .filter(Array.isArray).flat().forEach(function(row){
        if(!row||typeof row!=='object')return;
        var pid=row.planet_id||row.planetId||row.base_planet_id||row.home_planet_id||row.location_planet_id;
        if(pid&&planetId&&String(pid)!==String(planetId))return;
        var id=row.ship_id||row.shipId||row.type||row.key||row.id;
        var q=row.count??row.qty??row.quantity??row.amount??row.owned??row.available??row.total??row.stock;
        if(id&&N(q)>0)out[id]=(out[id]||0)+N(q);
      });
    return out;
  }
  function fleetOrigin(f){return f.originPlanetId||f.fromPlanetId||f.planetId||f.homePlanetId||f.sourcePlanetId||(f.origin&&f.origin.id)||(f.from&&f.from.planetId)||null}
  function fleetShips(planetId){
    var st=getState(),out={};
    (Array.isArray(st.fleets)?st.fleets:[]).forEach(function(f){
      if(!f||f.done||f.cancelled)return;
      var pid=fleetOrigin(f); if(planetId&&pid&&String(pid)!==String(planetId))return;
      merge(out,f.ships||f.units||f.vessels||f.fleet);
    });
    return out;
  }
  function totalShipsForPlanet(planetId){var out={};merge(out,planetShipsDirect(planetId));merge(out,arrayShips(planetId));merge(out,fleetShips(planetId));return out;}
  function defenseStats(){
    var st=getState(),count=0,attack=0,defense=0;
    function add(obj){Object.entries(normalize(obj)).forEach(function(pair){var id=pair[0],q=N(pair[1]);var d=defenseDef(id);count+=q;attack+=q*N(d.attack||d.power||0);defense+=q*N(d.hull||d.structure||d.hp||d.defense||0);});}
    add(st.defenses); if(st.planetDefenses&&typeof st.planetDefenses==='object')Object.values(st.planetDefenses).forEach(add);
    return {count:Math.round(count),attack:Math.round(attack),defense:Math.round(defense),military:Math.round(attack+defense)};
  }
  function calculate(scope){
    exposeGlobals(); var st=getState(),targets=[];
    if(scope&&typeof scope==='object'&&scope.ships){targets.push({id:'direct',ships:normalize(scope.ships)});}
    else if(scope){targets.push({id:scope,ships:totalShipsForPlanet(scope)});}
    else{var ps=planets(); if(ps.length)ps.forEach(function(p){targets.push({id:p.id,ships:totalShipsForPlanet(p.id)})}); else targets.push({id:st.activePlanetId||'global',ships:totalShipsForPlanet(st.activePlanetId)});}
    var byShip={},byPlanet={},count=0,attack=0,defense=0,cargo=0;
    targets.forEach(function(t){var ps={ships:0,attack:0,defense:0,cargo:0,military:0,byShip:{}};Object.entries(t.ships||{}).forEach(function(pair){var id=pair[0],q=N(pair[1]);if(q<=0)return;var a=q*shipAttack(id),d=q*shipDefense(id),c=q*shipCargo(id);count+=q;attack+=a;defense+=d;cargo+=c;ps.ships+=q;ps.attack+=a;ps.defense+=d;ps.cargo+=c;byShip[id]=byShip[id]||{id:id,name:shipName(id),qty:0,attack:0,defense:0,cargo:0};byShip[id].qty+=q;byShip[id].attack+=a;byShip[id].defense+=d;byShip[id].cargo+=c;ps.byShip[id]={id:id,name:shipName(id),qty:q,attack:a,defense:d,cargo:c};});ps.attack=Math.round(ps.attack);ps.defense=Math.round(ps.defense);ps.cargo=Math.round(ps.cargo);ps.military=ps.attack+ps.defense;byPlanet[t.id]=ps;});
    var ds=defenseStats(); attack=Math.round(attack); defense=Math.round(defense); cargo=Math.round(cargo);
    return {ships:Math.round(count),attack:attack,defense:defense,cargo:cargo,fleetMilitary:attack+defense,commandAttack:ds.attack,commandDefense:ds.defense,commandMilitary:ds.military,military:attack+defense+ds.military,power:attack+defense+ds.military,byShip:byShip,byPlanet:byPlanet,source:'SHIPS const + flotte stationnée + flottes en vol + défenses planétaires',updatedAt:Date.now()};
  }
  function sync(){var st=getState(),stats=calculate();st.militaryStats=stats;st.attack=stats.attack;st.defense=stats.defense;st.fleetPower=stats.attack;st.fleetDefense=stats.defense;st.fleetCargo=stats.cargo;st.military=stats.military;st.militaryScore=stats.military;st.commandMilitary=stats.commandMilitary;return stats;}
  window.calculateMilitaryStats=calculate; window.syncMilitaryStats=sync; window.getTotalFleetShipsForRanking=totalShipsForPlanet;
  window.shipAttackValue=shipAttack; window.shipDefenseValue=shipDefense; window.shipCargoValue=shipCargo;
  window.ownFleetScore=function(){return sync().fleetMilitary}; window.ownCommandementScore=function(){return sync().commandMilitary}; window.ownMilitaryScore=function(){return sync().military};
  window.empireFleetPower=function(){return sync().fleetMilitary}; window.empireFleetAttack=function(){return sync().attack}; window.empireFleetDefense=function(){return sync().defense}; window.empireFleetCargo=function(){return sync().cargo}; window.empireMilitaryPower=function(){return sync().military};
  window.planetFleetPower=function(pid){return calculate(pid).fleetMilitary}; window.planetFleetAttack=function(pid){return calculate(pid).attack}; window.planetFleetDefense=function(pid){return calculate(pid).defense}; window.planetFleetCargo=function(pid){return calculate(pid).cargo};
  function refreshProof(){var st=getState(),stats=sync();document.querySelectorAll('[data-mstat="attack"]').forEach(function(e){e.textContent=F(stats.attack)});document.querySelectorAll('[data-mstat="defense"]').forEach(function(e){e.textContent=F(stats.defense)});document.querySelectorAll('[data-mstat="ships"]').forEach(function(e){e.textContent=F(stats.ships)});document.querySelectorAll('[data-mstat="military"]').forEach(function(e){e.textContent=F(stats.military)});document.querySelectorAll('.ranking-v12 .card.panel,.ranking-side-card-v12,.military-stats-mini').forEach(function(p){if(!p.querySelector('.military-v5-proof')){var n=document.createElement('div');n.className='military-v5-proof';n.textContent='V5 OK : classement militaire = attaque flotte + défense/coque flotte + défenses planétaires, même si la flotte est en vol.';p.appendChild(n);}});}
  function focusSafeSearch(){var el=document.querySelector('.ranking-search-v12');if(!el)return;el.dataset.focusFixed='v5';}
  window.setRankingSearchV12=function(v){var st=getState();st.rankingSearchV12=String(v||'');var pos=0;try{pos=document.activeElement&&document.activeElement.classList&&document.activeElement.classList.contains('ranking-search-v12')?document.activeElement.selectionStart:st.rankingSearchV12.length}catch(e){pos=st.rankingSearchV12.length}try{if(typeof render==='function')render();else if(document.getElementById('center')&&typeof leaderboardHtml==='function')document.getElementById('center').innerHTML=leaderboardHtml();}catch(e){try{document.getElementById('center').innerHTML=leaderboardHtml()}catch(x){}}
    requestAnimationFrame(function(){var el=document.querySelector('.ranking-search-v12');if(el){el.dataset.focusFixed='v5';try{el.focus({preventScroll:true});el.setSelectionRange(pos,pos)}catch(e){}}refreshProof();});
  };
  window.setRankingTabV12=function(cat){var st=getState();st.rankingTabV12=cat;try{if(typeof render==='function')render();}catch(e){}requestAnimationFrame(function(){focusSafeSearch();refreshProof();});};
  function wrapRender(){}
  window.STELLARION_MILITARY_V5={exposeGlobals:exposeGlobals,calculate:calculate,sync:sync,test:function(){var st=getState();var before=sync();return {shipCatalog:shipsCatalog().length,defenseCatalog:defensesCatalog().length,ships:before.ships,attack:before.attack,defense:before.defense,military:before.military,byShip:before.byShip,source:before.source,focusPatch:typeof window.setRankingSearchV12==='function'};}};
  function boot(){exposeGlobals();wrapRender();refreshProof();focusSafeSearch();}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
  setInterval(function(){try{refreshProof()}catch(e){}},1500);
})();
