   const p={...base,rank:g.rank}; const isMe=!!p.isMe; const desc=p.description||'Ce joueur n’a pas encore ajouté de descriptif.'; const avatarHtml=p.avatar?`<img class="profile-avatar-v12" src="${esc(p.avatar)}" alt="avatar">`:`<div class="profile-avatar-v12"></div>`;
   const edit=isMe?`<div class="profile-edit-grid-v12"><input id="profAvatarV12" class="profile-input-v12" placeholder="URL image/avatar" value="${esc(p.avatar||'')}"><input id="profCountryV12" class="profile-input-v12" placeholder="Pays d'origine" value="${esc(p.country||'')}"><input id="profFlagV12" class="profile-input-v12" placeholder="Emoji drapeau" value="${esc(p.flag||'')}"><input id="profMottoV12" class="profile-input-v12" placeholder="Devise / statut" value="${esc(p.motto||'')}"><textarea id="profDescV12" class="profile-textarea-v12" placeholder="Description du commandant...">${esc(p.description||'')}</textarea></div><div class="profile-actions-v12"><button class="btn" onclick="saveMyProfileV12()">💾 Sauvegarder mon profil</button></div>`:'';
