(function(){
  function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]||c;});}
  function num(v){return Number(v)||0;}
  function fmtSafe(v){try{return typeof fmt==='function'?fmt(v):String(Math.round(num(v)));}catch(e){return String(Math.round(num(v)));}}
  function playerName(){try{return typeof playerDisplayName==='function'?playerDisplayName():(state.username||state.playerName||'Commandant');}catch(e){return (window.state&&state.username)||'Commandant';}}
  function ensureAllianceV5(){window.state=window.state||{};state.allianceFiltersV5=state.allianceFiltersV5||{q:'',status:'open',country:'all',sort:'power',minMembers:'',minPower:''};state.allianceApplications=Array.isArray(state.allianceApplications)?state.allianceApplications:[];state.allianceLogs=Array.isArray(state.allianceLogs)?state.allianceLogs:[];state.allianceChatDraft=state.allianceChatDraft||'';}
  function baseAlliances(){ensureAllianceV5();var list=[];try{if(typeof enrichedPublicAlliances==='function')list=enrichedPublicAlliances()||[];}catch(e){}if(!Array.isArray(list)||!list.length){list=[{id:'pub_solar',name:'Solar Pact',tag:'SUN',members:22,power:90400,description:'Grosse alliance orientée contrôle territorial.',status:'open',country:'Belgique'},{id:'pub_zenith',name:'Zenith Guard',tag:'ZEN',members:18,power:76300,description:'Commandement organisée, entraide quotidienne.',status:'open',country:'France'},{id:'pub_umbra',name:'Umbra Wolves',tag:'UMB',members:9,power:31800,description:'Raids rapides et diplomatie agressive.',status:'closed',country:'Canada'},{id:'pub_relic',name:'Relic Hunters',tag:'RLC',members:5,power:14200,description:'Exploration, artefacts et mondes rares.',status:'open',country:'Suisse'}];}var seen={};return list.map(function(a,i){return Object.assign({id:a.id||('ally_public_'+i),name:a.name||'Alliance',tag:a.tag||'---',members:num(a.members),power:num(a.power),description:a.description||'',status:a.status||'open',country:a.country||'Inconnu'},a);}).filter(function(a){if(seen[a.id])return false;seen[a.id]=true;return true;});}
  function countries(){var o={};baseAlliances().forEach(function(a){if(a.country)o[a.country]=true;});return Object.keys(o).sort();}
  function filteredAlliances(){ensureAllianceV5();var d=state.allianceFiltersV5,q=String(d.q||'').toLowerCase().trim();var list=baseAlliances().filter(function(a){if(d.status&&d.status!=='all'&&a.status!==d.status)return false;if(d.country&&d.country!=='all'&&a.country!==d.country)return false;if(d.minMembers&&num(a.members)<num(d.minMembers))return false;if(d.minPower&&num(a.power)<num(d.minPower))return false;if(q&&!String([a.name,a.tag,a.description,a.country].join(' ')).toLowerCase().includes(q))return false;return true;});var s=d.sort||'power';list.sort(function(a,b){if(s==='members')return num(b.members)-num(a.members);if(s==='name')return String(a.name).localeCompare(String(b.name));if(s==='tag')return String(a.tag).localeCompare(String(b.tag));if(s==='country')return String(a.country).localeCompare(String(b.country));return num(b.power)-num(a.power);});return list;}
  function statusLabel(v){return v==='all'?'Toutes':(v==='closed'?'Fermées':'Ouvertes');}
  function sortLabel(v){return ({power:'Puissance',members:'Membres',name:'Nom',tag:'Tag',country:'Pays'})[v||'power']||'Puissance';}
  function nextValue(cur,arr){var i=arr.indexOf(cur);return arr[(i+1+arr.length)%arr.length];}
  function rowHtml(a,i){var open=a.status==='open';return '<div class="alliance-v5-row '+(open?'open':'')+'" data-alliance-id="'+esc(a.id)+'"><div><div><strong>#'+(i+1)+'</strong><span class="alliance-v5-tag">['+esc(a.tag)+']</span><strong>'+esc(a.name)+'</strong><span class="alliance-v5-status '+(open?'open':'closed')+'">'+(open?'Ouvert':'Fermé')+'</span></div><div class="alliance-v5-stats"><span>👥 '+num(a.members)+'</span><span>⚔️ '+fmtSafe(a.power)+'</span><span>🌍 '+esc(a.country)+'</span><span>Activité '+Math.min(100,Math.max(18,Math.round((num(a.members)||1)*7)))+'%</span></div><p class="small muted">'+esc(a.description||'Aucune description.')+'</p></div><div class="alliance-v5-actions"><button class="btn '+(open?'btn-gold':'btn-ghost')+'" '+(open?'':'disabled')+' type="button" onclick="openAllianceApplyV5(\''+esc(a.id)+'\')">'+(open?'Candidater':'Fermée')+'</button><button class="btn btn-ghost" type="button" onclick="messageAllianceV5(\''+esc(a.id)+'\')">✉️ Message</button><button class="btn btn-ghost" type="button" onclick="openAllianceProfileV5(\''+esc(a.id)+'\')">👁️ Profil</button></div></div>';}
  function listHtml(){var list=filteredAlliances();return list.length?list.map(rowHtml).join(''):'<div class="alliance-v5-card"><p class="muted small">Aucune alliance ne correspond aux filtres.</p></div>';}
  function refreshListOnly(){var el=document.getElementById('allianceV5List');if(!el)return;var y=el.scrollTop;el.innerHTML=listHtml();el.scrollTop=y;}
  window.setAllianceFilterV5=function(k,v){ensureAllianceV5();state.allianceFiltersV5[k]=String(v==null?'':v).slice(0,80);refreshListOnly();};
  window.cycleAllianceFilterV5=function(k){ensureAllianceV5();var d=state.allianceFiltersV5;if(k==='status')d.status=nextValue(d.status||'open',['open','all','closed']);else if(k==='sort')d.sort=nextValue(d.sort||'power',['power','members','name','tag','country']);else if(k==='country'){var arr=['all'].concat(countries());d.country=nextValue(d.country||'all',arr);}refreshFiltersOnly();refreshListOnly();};
  function refreshFiltersOnly(){var el=document.getElementById('allianceV5Filters');if(el)el.innerHTML=filtersInnerHtml();}
  function filtersInnerHtml(){ensureAllianceV5();var d=state.allianceFiltersV5;return '<input class="alliance-v5-field" value="'+esc(d.q||'')+'" placeholder="Recherche nom, tag, pays..." oninput="setAllianceFilterV5(\'q\',this.value)"><button class="alliance-v5-filter-btn" type="button" onclick="cycleAllianceFilterV5(\'status\')"><span>'+statusLabel(d.status)+'</span><b>↻</b></button><button class="alliance-v5-filter-btn" type="button" onclick="cycleAllianceFilterV5(\'country\')"><span>'+(d.country==='all'?'Tous pays':esc(d.country))+'</span><b>↻</b></button><input class="alliance-v5-field" type="number" min="0" value="'+esc(d.minMembers||'')+'" placeholder="Membres min" oninput="setAllianceFilterV5(\'minMembers\',this.value)"><input class="alliance-v5-field" type="number" min="0" value="'+esc(d.minPower||'')+'" placeholder="Puissance min" oninput="setAllianceFilterV5(\'minPower\',this.value)"><button class="alliance-v5-filter-btn" type="button" onclick="cycleAllianceFilterV5(\'sort\')"><span>'+sortLabel(d.sort)+'</span><b>↻</b></button>';}
  function filtersHtml(){return '<div id="allianceV5Filters" class="alliance-v5-filters">'+filtersInnerHtml()+'</div>';}
  function modal(html){closeAllianceModalV5();var o=document.createElement('div');o.id='allianceModalV5';o.className='alliance-v5-modal';o.innerHTML=html;o.addEventListener('click',function(e){if(e.target===o)closeAllianceModalV5();});document.body.appendChild(o);var card=o.querySelector('.alliance-v5-modal-card');if(card){['click','pointerdown','mousedown','mouseup','keydown','keyup','keypress','input','change','beforeinput','compositionstart','compositionupdate','compositionend'].forEach(function(ev){card.addEventListener(ev,function(e){e.stopPropagation();},false);});}return o;}
  window.closeAllianceModalV5=function(){var x=document.getElementById('allianceModalV5');if(x)x.remove();};
  window.openCreateAllianceV5=function(){modal('<div class="alliance-v5-modal-card"><span class="pill">CRÉATION ALLIANCE</span><h2>Fonder une alliance</h2><label class="small muted">Nom de l’alliance</label><input id="allyV5Name" class="alliance-v5-field" maxlength="40" autocomplete="off" placeholder="Ex : Solar Pact"><label class="small muted">Tag court</label><input id="allyV5Tag" class="alliance-v5-field" maxlength="6" autocomplete="off" placeholder="Ex : SUN"><label class="small muted">Description</label><textarea id="allyV5Desc" class="alliance-v5-field alliance-v5-textarea" maxlength="300" placeholder="Objectifs, style de jeu, recrutement..."></textarea><div class="alliance-v5-modal-actions"><button id="allyV5Submit" class="btn btn-gold" type="button">Fonder l’alliance</button><button id="allyV5Cancel" class="btn btn-ghost" type="button">Annuler</button></div></div>');var name=document.getElementById('allyV5Name'),tag=document.getElementById('allyV5Tag'),desc=document.getElementById('allyV5Desc'),submit=document.getElementById('allyV5Submit'),cancel=document.getElementById('allyV5Cancel');cancel.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();closeAllianceModalV5();});submit.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();var nm=(name.value||'').trim();var tg=(tag.value||'').trim().toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,6);var de=(desc.value||'').trim();if(nm.length<3){try{addLog('Nom d’alliance trop court.');}catch(x){}name.focus();return false;}if(tg.length<2){try{addLog('Tag d’alliance invalide.');}catch(x){}tag.focus();return false;}ensureAllianceV5();state.alliance={id:'ally_'+Date.now(),name:nm,tag:tg,description:de,founder:playerName(),createdAt:Date.now(),rank:'Fondateur',status:'open',members:[{name:playerName(),rank:'Fondateur',power:0,country:(state.profile&&state.profile.country)||state.country||'',status:'En ligne'}]};state.allianceLogs=state.allianceLogs||[];state.allianceLogs.unshift('Alliance ['+tg+'] '+nm+' créée.');try{addLog('Alliance créée : ['+tg+'] '+nm+'.');}catch(x){}try{if(typeof save==='function')save();}catch(x){}closeAllianceModalV5();var center=document.getElementById('center');if(center)center.innerHTML=dashboardHtml();else if(typeof render==='function')render();return false;});setTimeout(function(){try{name.focus({preventScroll:true});}catch(e){}},60);};
  function findAlliance(id){return baseAlliances().find(function(a){return String(a.id)===String(id);});}
  window.openAllianceApplyV5=function(id){var a=findAlliance(id);if(!a)return;modal('<div class="alliance-v5-modal-card"><span class="pill">CANDIDATURE</span><h2>['+esc(a.tag)+'] '+esc(a.name)+'</h2><p class="small muted">Envoie une candidature aux recruteurs.</p><textarea id="allyV5Apply" class="alliance-v5-field alliance-v5-textarea">Bonjour,\n\nJe souhaite rejoindre votre alliance.\n\nCordialement.</textarea><div class="alliance-v5-modal-actions"><button id="allyV5ApplySubmit" class="btn btn-gold" type="button">Envoyer</button><button id="allyV5ApplyCancel" class="btn btn-ghost" type="button">Annuler</button></div></div>');var t=document.getElementById('allyV5Apply'),submit=document.getElementById('allyV5ApplySubmit'),cancel=document.getElementById('allyV5ApplyCancel');cancel.onclick=function(e){e.preventDefault();e.stopPropagation();closeAllianceModalV5();};submit.onclick=function(e){e.preventDefault();e.stopPropagation();ensureAllianceV5();state.allianceApplications.push({id:'app_'+Date.now(),allianceId:a.id,allianceName:a.name,tag:a.tag,message:t.value||'',status:'sent',createdAt:Date.now()});try{addLog('Candidature envoyée à ['+a.tag+'] '+a.name+'.');}catch(x){}try{if(typeof save==='function')save();}catch(x){}closeAllianceModalV5();};setTimeout(function(){try{t.focus({preventScroll:true});t.select();}catch(e){}},60);};
  window.messageAllianceV5=function(id){var a=findAlliance(id);if(!a)return;if(typeof openStellarionComposerV7==='function')openStellarionComposerV7('Recruteur ['+a.tag+']','Contact alliance ['+a.tag+']','Bonjour,\n\nJe souhaite échanger au sujet de votre alliance.');else try{addLog('Message vers ['+a.tag+'] '+a.name);}catch(e){}};
  window.openAllianceProfileV5=function(id){var a=findAlliance(id);if(!a)return;modal('<div class="alliance-v5-modal-card"><span class="pill">PROFIL ALLIANCE</span><h2>['+esc(a.tag)+'] '+esc(a.name)+'</h2><p class="muted">'+esc(a.description||'Aucune description.')+'</p><div class="alliance-v5-card"><div class="resource"><span>Membres</span><strong>'+num(a.members)+'</strong></div><div class="resource"><span>Puissance</span><strong>'+fmtSafe(a.power)+'</strong></div><div class="resource"><span>Pays</span><strong>'+esc(a.country)+'</strong></div></div><button class="btn btn-ghost" style="width:100%;margin-top:10px" type="button" onclick="closeAllianceModalV5()">Fermer</button></div>');};
  window.leaveAlliance=function(){if(confirm('Quitter ton alliance ?')){state.alliance=null;try{if(typeof save==='function')save();}catch(e){}if(typeof render==='function')render();}};
  window.setAllianceChatDraft=function(v){state.allianceChatDraft=String(v||'').slice(0,240);};
  window.sendAllianceChat=function(){var txt=String(state.allianceChatDraft||'').trim();if(!txt)return;state.allianceLogs=state.allianceLogs||[];state.allianceLogs.unshift(playerName()+' : '+txt);state.allianceChatDraft='';try{if(typeof save==='function')save();}catch(e){}var center=document.getElementById('center');if(center)center.innerHTML=dashboardHtml();};
  function directoryHtml(){return '<div class="alliance-v5-card"><h2>Rechercher une alliance</h2><p class="small muted">Les filtres sont des boutons cycliques, pas des menus select : plus de désélection impossible.</p>'+filtersHtml()+'</div><div id="allianceV5List" class="alliance-v5-list">'+listHtml()+'</div>';}
  function createHtml(){return '<div class="alliance-v5-wrap"><div class="alliance-v5-card"><span class="pill">ALLIANCE</span><h2>Créer une alliance</h2><p class="small muted">Création en popup isolée.</p><button class="btn btn-gold" type="button" style="width:100%;margin-top:10px" onclick="openCreateAllianceV5()">➕ Créer mon alliance</button></div><div class="alliance-v5-main">'+directoryHtml()+'</div></div>';}
  function dashboardHtml(){ensureAllianceV5();var a=state.alliance||{},members=Array.isArray(a.members)?a.members:[];if(!members.length)members=[{name:playerName(),rank:a.rank||'Fondateur',status:'En ligne',power:0}];var power=members.reduce(function(s,m){return s+num(m.power);},0);return '<div class="alliance-v5-dashboard"><div class="alliance-v5-card"><span class="pill">['+esc(a.tag||'ALL')+']</span><h2>'+esc(a.name||'Alliance')+'</h2><p class="small muted">'+esc(a.description||'Aucune description.')+'</p><div class="resource"><span>Grade</span><strong>'+esc(a.rank||'Membre')+'</strong></div><div class="resource"><span>Membres</span><strong>'+members.length+'</strong></div><div class="resource"><span>Puissance</span><strong>'+fmtSafe(power)+'</strong></div><button class="btn btn-ghost" type="button" style="width:100%;margin-top:10px" onclick="leaveAlliance()">Quitter l’alliance</button></div><div class="alliance-v5-main"><div class="alliance-v5-card alliance-v5-scroll"><h2>Quartier général alliance</h2><p class="muted">Tu es déjà dans une alliance : la recherche publique est masquée.</p><h3>Membres</h3>'+members.map(function(m){return '<div class="alliance-v5-member"><span>'+esc(m.name||'Membre')+'<br><small class="muted">'+esc(m.rank||'Membre')+'</small></span><strong>'+esc(m.status||'Actif')+'</strong></div>';}).join('')+'</div><div class="alliance-v5-card"><h2>Chat alliance</h2><div style="display:grid;grid-template-columns:1fr 120px;gap:8px"><input class="alliance-v5-field" type="text" placeholder="Message alliance" value="'+esc(state.allianceChatDraft||'')+'" oninput="setAllianceChatDraft(this.value)"><button class="btn" type="button" onclick="sendAllianceChat()">Envoyer</button></div><div class="alliance-v5-scroll" style="max-height:230px;margin-top:8px">'+(state.allianceLogs||[]).slice(0,18).map(function(l){return '<div class="alliance-v5-member"><span>'+esc(l)+'</span></div>';}).join('')+'</div></div></div></div>';}
  function allianceV5View(){ensureAllianceV5();return state.alliance?dashboardHtml():createHtml();}
  window.allianceView=allianceV5View;try{allianceView=allianceV5View;}catch(e){}
  window.allianceCreateView=createHtml;window.publicAllianceRegistryHtml=directoryHtml;window.openCreateAllianceSafe=window.openCreateAlliancePopupFinal=window.openCreateAllianceV4=window.openCreateAllianceV5;
})();
