(function(){
  "use strict";

  function rpcReady(){
    return window.StellarionCore && window.StellarionCore.supabase && window.StellarionCore.supabase.rpc && window.state && window.state.__serverHydrated;
  }

  function now(){ return Date.now(); }
  function asSeconds(ms){ return Math.max(1, Math.round(ms / 1000)); }
  function fragmentCost(seconds){ return Math.max(1, Math.ceil(Math.max(1, seconds) / 60)); }

  async function serverStartConstruction(planet, def, nextLevel, cost, durationSeconds){
    const res = await window.StellarionCore.supabase.rpc("ca04_start_construction", {
      p_planet_id: planet.id,
      p_building_id: def.id,
      p_target_level: nextLevel,
      p_cost_titanium: Math.max(0, Math.round(cost.titanium || 0)),
      p_cost_xenite: Math.max(0, Math.round(cost.xenite || 0)),
      p_cost_antimatter: Math.max(0, Math.round(cost.antimatter || 0)),
      p_duration_seconds: Math.max(1, Math.round(durationSeconds || 1))
    });
    if(res.error) throw res.error;
    return res.data;
  }

  async function serverCompleteDue(){
    if(!rpcReady()) return null;
    const res = await window.StellarionCore.supabase.rpc("ca04_complete_due_constructions", {});
    if(res.error) throw res.error;
    return res.data;
  }

  async function serverFinishNow(queueId, price){
    const res = await window.StellarionCore.supabase.rpc("ca04_finish_construction_now", {
      p_queue_id: queueId,
      p_fragment_cost: Math.max(0, Math.round(price || 0))
    });
    if(res.error) throw res.error;
    return res.data;
  }

  function removeFinishedLocalQueues(){
    if(!window.state || !Array.isArray(state.buildQueue)) return;
    const t = now();
    let changed = false;
    state.buildQueue = state.buildQueue.filter(function(q){
      if(Number(q.finishAt || 0) > t) return true; // pas encore terminé : on garde
      // Terminé : on APPLIQUE le niveau au bâtiment AVANT de retirer l'item.
      // Sans ça, ce nettoyage (déclenché toutes les secondes) retirait la
      // construction finie sans jamais monter le niveau -> bâtiment bloqué au niveau 0.
      try{
        const rows = (state.buildings && state.buildings[q.planetId]) || [];
        const row = rows.find(function(b){ return b.building_id === q.building_id; });
        if(row && Number(q.to) > Number(row.level || 0)){ row.level = Number(q.to); changed = true; }
      }catch(e){}
      return false; // on retire l'item terminé
    });
    if(changed){
      try{ if(typeof save === "function") save(); }catch(e){}
      try{ if(typeof render === "function") render(); }catch(e){}
    }
  }

  function install(){
    if(typeof window.queueBuilding === "function" && !window.queueBuilding.__ca04){
      const localQueueBuilding = window.queueBuilding;

      window.queueBuilding = async function(id){
        if(!rpcReady()){
          return localQueueBuilding.apply(this, arguments);
        }

        try{
          const planet = activePlanet();
          const def = BUILDINGS.find(b => b.id === id);
          const allowed = canBuildOnPlanet(def, planet);
          if(!allowed.ok){ addLog(allowed.reason + "."); render(); return; }

          const rows = state.buildings[planet.id] || [];
          const row = rows.find(b => b.building_id === id);
          const queuedLevels = state.buildQueue.filter(q => q.building_id === id && q.planetId === planet.id).length;
          const level = (row ? row.level : 0) + queuedLevels;
          const next = level + 1;
          const c = cost(def, next);

          if(state.buildQueue.filter(q => q.planetId === planet.id).length >= canQueue()){
            addLog("File de construction pleine sur " + planet.name + ".");
            render();
            return;
          }

          if(state.resources.titanium < c.titanium || state.resources.xenite < c.xenite || state.resources.antimatter < (c.antimatter || 0)){
            addLog("Ressources insuffisantes.");
            render();
            return;
          }

          const durationSec = buildTime(def, next);
          const server = await serverStartConstruction(planet, def, next, c, durationSec);

          state.resources.titanium -= c.titanium;
          state.resources.xenite -= c.xenite;
          state.resources.antimatter -= (c.antimatter || 0);
          if(!row) rows.push({ building_id:id, level:0 });

          const startMs = new Date(server.started_at).getTime();
          const finishMs = new Date(server.finishes_at).getTime();

          state.buildings[planet.id] = rows;
          state.buildQueue.push({
            id: String(server.queue_id),
            serverId: String(server.queue_id),
            planetId: planet.id,
            building_id: id,
            from: level,
            to: next,
            startAt: startMs,
            finishAt: finishMs,
            duration: Math.max(1, Math.round((finishMs - startMs) / 1000)),
            serverSynced: true
          });

          addLog(def.name + " ajouté à la file serveur de " + planet.name + ".");
          save(); render();
        }catch(error){
          console.error("[CA0.4] Construction serveur impossible, fallback local:", error);
          addLog("Serveur construction indisponible : action locale temporaire.");
          return localQueueBuilding.apply(this, arguments);
        }
      };
      window.queueBuilding.__ca04 = true;
    }

    if(typeof window.processBuildQueue === "function" && !window.processBuildQueue.__ca04){
      const localProcess = window.processBuildQueue;
      window.processBuildQueue = function(silent){
        const before = Array.isArray(state.buildQueue) ? state.buildQueue.length : 0;
        const result = localProcess.apply(this, arguments);
        removeFinishedLocalQueues();

        if(rpcReady()){
          serverCompleteDue().then(data => {
            if(data && data.completed && data.completed.length && !silent){
              addLog(data.completed.length + " construction(s) synchronisée(s) serveur.");
            }
          }).catch(e => console.warn("[CA0.4] complete due serveur", e));
        }

        if(before !== (state.buildQueue || []).length){
          try{ save(); }catch(e){}
        }
        return result;
      };
      window.processBuildQueue.__ca04 = true;
    }

    if(typeof window.finishQueueItem === "function" && !window.finishQueueItem.__ca04){
      const localFinish = window.finishQueueItem;
      window.finishQueueItem = async function(id){
        const q = state.buildQueue.find(q => q.id === id);
        if(!q || !rpcReady() || !q.serverSynced){
          return localFinish.apply(this, arguments);
        }

        try{
          const remain = Math.max(0, (q.finishAt - Date.now()) / 1000);
          const price = fragmentCost(remain);

          await serverFinishNow(q.serverId || q.id, price);

          q.finishAt = Date.now();
          processBuildQueue(false);
          state.fragments = Math.max(0, Number(state.fragments || 0) - price);
          if(state.resources) state.resources.fragments = state.fragments;

          addLog("Construction terminée avec " + price + " fragments.");
          save(); render();
        }catch(error){
          console.error("[CA0.4] Accélération serveur impossible:", error);
          addLog("Accélération serveur impossible.");
          render();
        }
      };
      window.finishQueueItem.__ca04 = true;
    }
  }

  function tryInstall(){
    try{ install(); }catch(e){ console.warn("[CA0.4] install pending", e); }
  }

  if(document.readyState === "loading"){
    document.addEventListener("DOMContentLoaded", tryInstall);
  } else {
    tryInstall();
  }

  setInterval(function(){
    tryInstall();
    removeFinishedLocalQueues();
  }, 1000);

  window.StellarionCA04Construction = {
    serverStartConstruction,
    serverCompleteDue,
    serverFinishNow
  };
})();
;

/* ---- bloc script (source: ligne ~25944) ---- */
/* STELLARION CONNECTED ALPHA 0.5 — Production serveur
   Le serveur calcule les ressources selon last_tick + niveaux bâtiments.
*/
(function(){
  "use strict";

  function ready(){
    return window.StellarionCore
      && window.StellarionCore.supabase
      && window.StellarionCore.supabase.rpc
      && window.state
      && window.state.__serverHydrated;
  }

  async function tickAllPlanets(){
    if(!ready()) return null;
    const res = await window.StellarionCore.supabase.rpc("ca05_tick_all_my_planets", {});
    if(res.error) throw res.error;
    return res.data;
  }

  function applyTickResult(data){
    if(!data || !Array.isArray(data.planets) || !window.state) return;

    state.__serverProductionTickAt = new Date().toISOString();

    for(const item of data.planets){
      const pid = item.planet_id;
      if(!pid || !item.resources) continue;

      state.planetResources = state.planetResources || {};
      state.planetResources[pid] = Object.assign({}, state.planetResources[pid] || {}, {
        titanium: Number(item.resources.titanium || 0),
        xenite: Number(item.resources.xenite || 0),
        antimatter: Number(item.resources.antimatter || 0),
        energy: Number(item.resources.energy || 0),
        fragments: Number(state.fragments || 0),
        darkMatter: Number(state.darkMatter || 0)
      });

      state.planetProductionServer = state.planetProductionServer || {};
      state.planetProductionServer[pid] = item.production_per_hour || {};
    }

    if(state.activePlanetId && state.planetResources[state.activePlanetId]){
      state.resources = Object.assign({}, state.resources || {}, state.planetResources[state.activePlanetId]);
    }

    try{
      state.logs = Array.isArray(state.logs) ? state.logs : [];
      state.logs.unshift("Production serveur synchronisée.");
      state.logs = state.logs.slice(0,80);
    }catch(e){}

    try{ if(typeof window.save === "function") window.save(); }catch(e){}
    try{ if(typeof window.render === "function") window.render(); }catch(e){}
  }

  async function syncServerProduction(){
    if(!ready()) return;
    try{
      const data = await tickAllPlanets();
      applyTickResult(data);
    }catch(error){
      console.warn("[CA0.5] Production serveur indisponible :", error);
    }
  }

  function patchProductionDisplay(){
    if(!window.state || !state.planetProductionServer || !state.activePlanetId) return;
    const prod = state.planetProductionServer[state.activePlanetId];
    if(!prod) return;

    // Données disponibles pour l'UI existante si elle veut les lire.
    state.serverProduction = prod;
  }

  window.StellarionCA05Production = {
    tickAllPlanets,
    applyTickResult,
    syncServerProduction
  };

  window.addEventListener("stellarion:empire:hydrated", function(){
    setTimeout(syncServerProduction, 400);
  });

  window.addEventListener("stellarion:auth:login", function(){
    setTimeout(syncServerProduction, 1200);
  });

  // Tick léger : on synchronise avec le serveur périodiquement.
  // Le client peut continuer à afficher une animation locale entre deux syncs,
  // mais la vérité revient du serveur.
  setInterval(function(){
    patchProductionDisplay();
    syncServerProduction();
  }, 30000);

  if(document.readyState === "loading"){
    document.addEventListener("DOMContentLoaded", function(){
      setTimeout(syncServerProduction, 1500);
    });
  } else {
    setTimeout(syncServerProduction, 1500);
  }
})();
;

/* ---- bloc script (source: ligne ~26054) ---- */
/* STELLARION PATCH 0.5.1 — Buff Raffinerie Antimatière
   Nouvelle règle alpha :
   Production antimatière = 75/h au niveau 1, croissance x1.55 par niveau.
   Ancienne production trop faible.
*/
(function(){
  "use strict";

  window.STELLARION_ANTIMATTER_REFINERY_BUFF = {
    basePerHour: 75,
    growth: 1.55,
    version: "0.5.1"
  };

  function antimatterPerHour(level){
    level = Math.max(0, Number(level || 0));
    if(level <= 0) return 0;
    return Math.floor(75 * Math.pow(1.55, level - 1));
  }

  window.stellarionAntimatterPerHour = antimatterPerHour;

  function patchProductionObjects(){
    if(!window.state) return;

    // Corrige l'affichage serveur si présent.
    if(state.planetProductionServer && state.activePlanetId && state.buildings && state.buildings[state.activePlanetId]){
      const rows = state.buildings[state.activePlanetId] || [];
      const row = rows.find(b =>
        b.building_id === "antimatter_refinery" ||
        b.building_id === "antimatter" ||
        b.building_id === "BLD_ANTIMATTER_REFINERY"
      );
      const lvl = row ? Number(row.level || 0) : 0;
      state.planetProductionServer[state.activePlanetId] = Object.assign({}, state.planetProductionServer[state.activePlanetId] || {}, {
        antimatter: antimatterPerHour(lvl)
      });
      state.serverProduction = state.planetProductionServer[state.activePlanetId];
    }
  }

  function install(){
    patchProductionObjects();
  }

  setInterval(install, 1000);
  window.addEventListener("stellarion:empire:hydrated", function(){ setTimeout(install, 250); });
})();
;

/* ---- bloc script (source: ligne ~26107) ---- */
(function(){
  "use strict";

  window.Stellarion060 = window.Stellarion060 || {};
  window.Stellarion060.clientBridge = window.Stellarion060.clientBridge || {};

  let syncInProgress = false;
  let lastSyncAt = 0;

  function supabaseClient(){
    if(window.StellarionCore && window.StellarionCore.supabase) return window.StellarionCore.supabase;
    if(window.supabaseClient) return window.supabaseClient;
    if(window.supabase && window.STELLARION_SUPABASE_URL && window.STELLARION_SUPABASE_ANON_KEY){
      try {
        window.supabaseClient = window.supabase.createClient(window.STELLARION_SUPABASE_URL, window.STELLARION_SUPABASE_ANON_KEY);
        return window.supabaseClient;
      } catch(e){}
    }
    return null;
  }

  function hasState(){ return !!window.state; }

  async function rpcTickAll(){
    
    if(!state || (!state.userId && !(window.currentUser && window.currentUser.id))) return null;
    if(window.STELLARION_ENABLE_ECONOMY_RPC !== true){
      state.__economyBridge060 = false;
      state.__economyBridge060Disabled = true;
      return null;
    }
    const client = supabaseClient();
    if(!client || !client.rpc) return null;
    const res = await client.rpc("ca060_tick_all_my_planets", {});
    if(res.error) throw res.error;
    return res.data;
  }

  function applyResources(data){
    if(!data || !Array.isArray(data.planets) || !hasState()) return false;

    state.planetResources = state.planetResources || {};
    state.planetProductionServer = state.planetProductionServer || {};

    for(const item of data.planets){
      if(!item || !item.planet_id) continue;
      const pid = item.planet_id;
      const current = state.planetResources[pid] || {};
      const resources = item.resources || {};
      const production = item.production_per_hour || {};

      state.planetResources[pid] = Object.assign({}, current, {
        titanium: Number(resources.titanium ?? current.titanium ?? 0),
        xenite: Number(resources.xenite ?? current.xenite ?? 0),
        antimatter: Number(resources.antimatter ?? current.antimatter ?? 0),
        energy: Number(resources.energy ?? current.energy ?? 0),
        fragments: Number(state.fragments || current.fragments || 0),
        darkMatter: Number(state.darkMatter || current.darkMatter || 0)
      });

      state.planetProductionServer[pid] = {
        titanium: Number(production.titanium || 0),
        xenite: Number(production.xenite || 0),
        antimatter: Number(production.antimatter || 0),
        energy: Number(production.energy || 0)
      };
    }

    if(state.activePlanetId && state.planetResources[state.activePlanetId]){
      state.resources = Object.assign({}, state.resources || {}, state.planetResources[state.activePlanetId]);
      state.serverProduction = Object.assign({}, state.planetProductionServer[state.activePlanetId] || {});
    }

    state.__economyServer060 = true;
    state.__economyBridge060 = true;
    state.__economyBridge060At = new Date().toISOString();

    try { if(typeof window.save === "function") window.save(); } catch(e){}
    try { if(typeof window.render === "function") window.render(); } catch(e){}

    return true;
  }

  async function sync(reason){
    if(syncInProgress) return null;
    const now = Date.now();
    if(now - lastSyncAt < 1500) return null;
    if(!hasState()) return null;
    if(!state.userId && !(window.currentUser && window.currentUser.id)) return null;

    syncInProgress = true;
    try{
      const data = await rpcTickAll();
      lastSyncAt = Date.now();
      applyResources(data);
      return data;
    }catch(error){
      state.__economyBridge060Disabled = true;
      state.__economyBridge060LastError = String(error&&error.message||error);
      return null;
    }finally{
      syncInProgress = false;
    }
  }

  function fragmentCostForSeconds(seconds){
    seconds = Math.max(0, Number(seconds || 0));
    if(seconds <= 0) return 0;
    return Math.max(1, Math.ceil(seconds / 60));
  }

  function getProduction(planetId){
    if(!hasState()) return { titanium:0, xenite:0, antimatter:0, energy:0 };
    const pid = planetId || state.activePlanetId;
    return Object.assign({ titanium:0, xenite:0, antimatter:0, energy:0 }, (state.planetProductionServer || {})[pid] || {});
  }

  function install(){
    window.stellarionFragmentCostForSeconds = fragmentCostForSeconds;
    window.stellarionGetServerProduction = getProduction;
    setTimeout(function(){ sync("boot"); }, 700);
    setTimeout(function(){ sync("boot-late"); }, 2500);
  }

  window.Stellarion060.clientBridge.economy = { sync, applyResources, getProduction, fragmentCostForSeconds };

  window.addEventListener("stellarion:empire:hydrated", function(){ setTimeout(function(){ sync("empire-hydrated"); }, 400); });
  window.addEventListener("stellarion:auth:login", function(){ setTimeout(function(){ sync("auth-login"); }, 1000); });
  window.addEventListener("focus", function(){ setTimeout(function(){ sync("window-focus"); }, 200); });
  setInterval(function(){ sync("interval-30s"); }, 30000);

  if(document.readyState === "loading") document.addEventListener("DOMContentLoaded", install);
  else install();
})();
;

/* ---- bloc script (source: ligne ~26237) ---- */
(function(){
  "use strict";
  const G = (typeof window !== "undefined") ? window : this;

  // ---------- Accès aux vraies données du jeu ----------
  function S(){ return G.state || (typeof state !== "undefined" ? state : {}) || {}; }
  function num(v){ return Number(v) || 0; }
  function f(v){ return (typeof fmt === "function") ? fmt(v) : Math.round(num(v)).toLocaleString("fr-FR"); }
  function esc(v){ return String(v ?? "").replace(/[&<>"']/g, m => ({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#039;"}[m])); }
  function planetsArr(){ const s = S(); return Array.isArray(s.planets) ? s.planets : []; }
  function activeId(){ const s = S(); return s.activePlanetId || (planetsArr()[0] && planetsArr()[0].id); }
  function planetById(id){ return planetsArr().find(p => String(p.id) === String(id)) || null; }
  function planetName(id){ const p = planetById(id); return p ? (p.name || id) : id; }
  function shipsOf(pid){ return (typeof planetShips === "function") ? planetShips(pid) : ((S().planetShips || {})[pid] || {}); }
  function shipList(){ return (typeof SHIPS !== "undefined" && Array.isArray(SHIPS)) ? SHIPS : []; }
  function shipDef(id){ return shipList().find(s => s.id === id) || null; }
  function shipNm(id){ const d = shipDef(id); return d ? d.name : id; }
  function shipIc(id){ const d = shipDef(id); return d ? d.icon : "🚀"; }
  function shipPow(id){ return (typeof shipPowerValue === "function") ? shipPowerValue(id) : (shipDef(id) ? (shipDef(id).attack || 0) : 0); }
  function fleetPowerOf(pid){ return (typeof planetFleetPower === "function") ? planetFleetPower(pid) : 0; }
  function cmdPowerOf(pid){ return (typeof planetCommandementPower === "function") ? planetCommandementPower(pid) : 0; }
  function cargoCapOf(pid){ const sh = shipsOf(pid); let c = 0; for (const [id,n] of Object.entries(sh)){ const d = shipDef(id); if (d) c += (d.cargo || 0) * num(n); } return c; }
  function countShips(sh){ return Object.values(sh || {}).reduce((a,b) => a + num(b), 0); }
  function activeFleets(){ const s = S(); return Array.isArray(s.fleets) ? s.fleets.filter(fl => fl && !fl.done) : []; }
  function planetRes(pid){ const pr = S().planetResources || {}; return pr[pid] || {titanium:0,xenite:0,antimatter:0,energy:0}; }
  function targetSel(){ const s = S(); const t = s.selected; if (!t || t.owned || t.type === "home") return null; return t; }

  function empireTotals(){
    const ps = planetsArr();
    let ships = 0, cmd = 0;
    ps.forEach(p => { ships += countShips(shipsOf(p.id)); cmd += cmdPowerOf(p.id); });
    const fleetPow = (typeof empireFleetPower === "function") ? empireFleetPower() : 0;
    return { planets: ps.length, ships, fleetPow, cmd, missions: activeFleets().length };
  }

  // ---------- Rendu (injecté dans #center par render()) ----------
  function statCard(icon, label, value){
    return `<div class="cc-stat"><div class="cc-stat-ico">${icon}</div><div><small>${esc(label)}</small><strong>${value}</strong></div></div>`;
  }

  function empireBoard(){
    const t = empireTotals();
    return `<div class="card panel cc-block">
      <h2 class="cc-h">🛰️ Situation de l'empire</h2>
      <div class="cc-stat-grid">
        ${statCard("🪐","Planètes", f(t.planets))}
        ${statCard("🚀","Vaisseaux", f(t.ships))}
        ${statCard("⚔️","Puissance (off./déf.)", f(t.fleetPow))}
        ${statCard("🎯","Missions actives", f(t.missions))}
      </div>
    </div>`;
  }

  function targetPanel(){
    const t = targetSel();
    if (!t){
      return `<div class="card panel cc-block">
        <h2 class="cc-h">🎯 Cible actuelle</h2>
        <p class="muted small">Aucune cible ennemie/neutre sélectionnée. Ouvre la <b>Galaxie</b> et clique un système pour viser, puis reviens ici pour lancer l'ordre.</p>
      </div>`;
    }
    return `<div class="card panel cc-block cc-target">
      <h2 class="cc-h">🎯 Cible verrouillée</h2>
      <div class="cc-target-name">${esc(t.name || "Système")}</div>
      <div class="muted small">${t.owned ? "Possédée" : (t.npc || t.enemy ? "Hostile" : "Neutre")} · Coordonnées ${esc(coordsLabel(t))}</div>
    </div>`;
  }

  function coordsLabel(o){
    if (!o) return "—";
    if (o.coords) return o.coords;
    if (o.sector != null || o.system != null) return `${o.sector ?? "?"}-${o.system ?? "?"}`;
    const a = [o.galaxy ?? o.g, o.system ?? o.s, o.position ?? o.pos ?? o.slot].filter(x => x != null && x !== "");
    return a.length ? a.join(":") : (o.x != null ? `${Math.round(o.x)} / ${Math.round(o.y)}` : "—");
  }
  function missionsPanel(){
    const ms = activeFleets();
    let rows;
    if (!ms.length){
      rows = `<div class="cc-row"><strong>✅ Aucune flotte en mission</strong><div class="muted small">Toutes les forces sont disponibles.</div></div>`;
    } else {
      rows = ms.map(m => {
        const label = missionLbl(m.mission);
        const from = (m.from && m.from.name) || planetName(m.originPlanetId) || "—";
        const to = (m.to && m.to.name) || "—";
        const end = num(m.startTime) + num(m.duration);
        const ships = countShips(m.ships);
        return `<div class="cc-row cc-mission">
          <strong>🚀 ${esc(label)}</strong>
          <div class="muted small">${esc(from)} → ${esc(to)} · ${f(ships)} vaisseau(x)</div>
          <div class="cc-eta">⏳ <span data-cmd-eta="${end}">${(typeof fmtTime === "function") ? fmtTime(Math.max(0, end - performance.now()/1000)) : ""}</span></div>
        </div>`;
      }).join("");
    }
    return `<div class="card panel cc-block">
      <h2 class="cc-h">📡 Missions en cours</h2>
      ${rows}
    </div>`;
  }

  function missionLbl(v){
    const map = { attack:"Attaque", spy:"Espionnage", scan:"Espionnage", transport:"Transport", transfer:"Transfert", colonize:"Colonisation", recycle:"Recyclage", support:"Soutien", explore:"Exploration", return:"Retour" };
    return map[String(v || "").toLowerCase()] || v || "Mission";
  }

  function fleetByPlanet(){
    const ps = planetsArr();
    const aid = activeId();
    const cards = ps.map(p => {
      const sh = shipsOf(p.id);
      const count = countShips(sh);
      const badges = Object.entries(sh).filter(([,q]) => num(q) > 0)
        .map(([id,q]) => `<span class="cc-badge">${shipIc(id)} ${esc(shipNm(id))} ×${f(q)}</span>`).join("")
        || `<span class="muted small">Aucun vaisseau stationné</span>`;
      const active = String(p.id) === String(aid);
      return `<div class="cc-planet-card ${active ? "is-active" : ""}" onclick="StellarionCommandCenter.focusPlanet('${esc(p.id)}')">
        <div class="cc-planet-head">
          <div><strong>🌍 ${esc(p.name || "Planète")}</strong><div class="muted tiny">${esc(coordsLabel(p))}</div></div>
          <span class="cc-pill">${f(count)} vaisseau(x)</span>
        </div>
        <div class="cc-statline">
          <span>⚔️ Puissance <b>${f(fleetPowerOf(p.id))}</b></span>
          <span>🚀 Vaisseaux <b>${f(count)}</b></span>
          <span>📦 Cargo <b>${f(cargoCapOf(p.id))}</b></span>
        </div>
        <div class="cc-badges">${badges}</div>
      </div>`;
    }).join("");
    return `<div class="card panel cc-block cc-fleet-overview">
      <h2 class="cc-h">🚀 Flottes par planète <span class="muted small">(clique pour activer)</span></h2>
      <div class="cc-planet-grid">${cards || `<div class="muted small">Aucune planète.</div>`}</div>
    </div>`;
  }

  function missionPlanner(){
    const s = S();
    s.missionDraft = s.missionDraft || { ships:{}, cargo:{titanium:0,xenite:0,antimatter:0} };
    const draft = s.missionDraft.ships || {};
    const aid = activeId();
    const sh = shipsOf(aid);
    const rows = Object.entries(sh).filter(([,q]) => num(q) > 0).map(([id,q]) => {
      const cur = num(draft[id]);
      return `<div class="cc-ship-select">
        <div><strong>${shipIc(id)} ${esc(shipNm(id))}</strong><div class="muted tiny">Dispo ${f(q)} · Puiss. ${f(shipPow(id))} · Cargo ${f((shipDef(id)||{}).cargo||0)}</div></div>
        <input class="cc-ship-input" data-ship="${esc(id)}" type="number" min="0" max="${num(q)}" value="${cur}" oninput="StellarionCommandCenter.setShip('${esc(id)}', this.value)">
        <button class="btn btn-ghost cc-max" onclick="StellarionCommandCenter.maxShip('${esc(id)}')">Max</button>
      </div>`;
    }).join("") || `<div class="muted small">Aucun vaisseau sur cette planète. Construis-en dans l'Arsenal.</div>`;

    const power = (typeof selectedShipPower === "function") ? selectedShipPower() : {attack:0,cargo:0,count:0};
    const tgt = targetSel();
    const hasTarget = !!tgt;
    const tgtLabel = tgt ? `${esc(tgt.name || "Système")} (${esc(coordsLabel(tgt))})` : "aucune";

    return `<div class="card panel cc-block">
      <h2 class="cc-h">🎯 Ordre de mission <span class="muted small">depuis ${esc(planetName(aid))}</span></h2>
      <div class="cc-target-row">
        <input id="cc-target-input" class="cc-field" placeholder="Cible : coordonnées (ex. 12-34) ou nom de système / joueur" value="${tgt ? esc(tgt.name || "") : ""}" onkeydown="if(event.key==='Enter'){StellarionCommandCenter.lockTarget();return false;}">
        <button class="btn" onclick="StellarionCommandCenter.lockTarget()">Viser</button>
      </div>
      <div class="cc-target-state ${hasTarget ? "ok" : ""}">${hasTarget ? "🎯 Cible verrouillée : " : "Aucune cible. Tape des coordonnées/nom ou clique un système sur la Galaxie. "}<b>${hasTarget ? tgtLabel : ""}</b></div>
      <div class="cc-ship-selector" id="cc-ship-selector">${rows}</div>
      <div class="cc-preview">
        <span>Sélection : <b data-cc-count>${f(power.count)}</b> vaisseau(x)</span>
        <span>⚔️ Puissance <b data-cc-attack>${f(power.attack)}</b></span>
        <span>📦 Cargo <b data-cc-cargo>${f(power.cargo)}</b></span>
      </div>
      <div class="cc-cargo-grid">
        <div><label>Titane</label><input id="cc-cargo-titanium" type="number" min="0" value="${num(s.missionDraft.cargo.titanium)}" oninput="StellarionCommandCenter.setCargo('titanium', this.value)"></div>
        <div><label>Xénite</label><input id="cc-cargo-xenite" type="number" min="0" value="${num(s.missionDraft.cargo.xenite)}" oninput="StellarionCommandCenter.setCargo('xenite', this.value)"></div>
        <div><label>Antimatière</label><input id="cc-cargo-antimatter" type="number" min="0" value="${num(s.missionDraft.cargo.antimatter)}" oninput="StellarionCommandCenter.setCargo('antimatter', this.value)"></div>
      </div>
      <div class="cc-order-btns">
        <button class="btn" ${hasTarget ? "" : "disabled"} onclick="StellarionCommandCenter.order('scan')">🔭 Espionner</button>
        <button class="btn" ${hasTarget ? "" : "disabled"} onclick="StellarionCommandCenter.order('attack')">💥 Attaquer</button>
        <button class="btn" ${hasTarget ? "" : "disabled"} onclick="StellarionCommandCenter.order('transfer')">📦 Transférer</button>
        <button class="btn" ${hasTarget ? "" : "disabled"} onclick="StellarionCommandCenter.order('colonize')">🪐 Coloniser</button>
        <button class="btn btn-ghost" onclick="StellarionCommandCenter.clearShips()">Vider</button>
      </div>
      ${hasTarget ? "" : `<div class="muted small" style="margin-top:8px">Sélectionne une cible sur la Galaxie pour activer les ordres.</div>`}
    </div>`;
  }

  function logisticsPanel(){
    const ps = planetsArr();
    const aid = activeId();
    if (ps.length < 2){
      return `<div class="card panel cc-block">
        <h2 class="cc-h">📦 Logistique inter-planètes</h2>
        <p class="muted small">Tu n'as qu'une seule planète. La logistique devient disponible dès ta première colonie.</p>
      </div>`;
    }
    const opts = (sel) => ps.map(p => `<option value="${esc(p.id)}" ${String(p.id)===String(sel)?"selected":""}>${esc(p.name||"Planète")} — ${esc(coordsLabel(p))}</option>`).join("");
    const otherId = (ps.find(p => String(p.id) !== String(aid)) || ps[0]).id;
    const sr = planetRes(aid);
    return `<div class="card panel cc-block cc-logistics">
      <h2 class="cc-h">📦 Logistique inter-planètes <span class="muted small">(transfert immédiat)</span></h2>
      <div class="cc-form-grid">
        <div><label class="cc-label">Départ</label><select id="cc-tr-from" class="cc-field">${opts(aid)}</select></div>
        <div><label class="cc-label">Destination</label><select id="cc-tr-to" class="cc-field">${opts(otherId)}</select></div>
      </div>
      <div class="cc-cargo-grid">
        <div><label>Titane <span class="muted tiny">(dispo ${f(sr.titanium)})</span></label><input id="cc-tr-titanium" type="number" min="0" value="0"></div>
        <div><label>Xénite <span class="muted tiny">(dispo ${f(sr.xenite)})</span></label><input id="cc-tr-xenite" type="number" min="0" value="0"></div>
        <div><label>Antimatière <span class="muted tiny">(dispo ${f(sr.antimatter)})</span></label><input id="cc-tr-antimatter" type="number" min="0" value="0"></div>
      </div>
      <button class="btn" style="width:100%;margin-top:10px" onclick="StellarionCommandCenter.transfer()">Envoyer les ressources</button>
      <p class="muted tiny" style="margin-top:6px">Les ressources de départ affichées correspondent à la planète active. Choisis une autre planète de départ pour transférer son stock.</p>
    </div>`;
  }

  function defensesPanel(){
    let grid = "";
    try {
      if (typeof DEFENSES !== "undefined" && typeof defenseHtml === "function"){
        grid = DEFENSES.map(d => defenseHtml(d)).join("");
      }
    } catch(e){ grid = ""; }
    if (!grid) return "";
    return `<div class="card panel cc-block cc-defenses">
      <h2 class="cc-h">🛡️ Commandements planétaires <span class="muted small">— ${esc(planetName(activeId()))}</span></h2>
      <div class="shipyard-compact-grid">${grid}</div>
    </div>`;
  }

  function commandCenterView(){
    return `<div class="cc-page">
      <aside class="cc-left">
        ${empireBoard()}
        ${targetPanel()}
        ${missionsPanel()}
      </aside>
      <section class="cc-main">
        ${fleetByPlanet()}
        ${missionPlanner()}
        ${logisticsPanel()}
      </section>
    </div>`;
  }
  G.commandCenterView = commandCenterView;
  G.renderCommand = function(){
    const center = document.querySelector("#center") || document.querySelector("main");
    if (center) center.innerHTML = commandCenterView();
  };

  // ---------- Actions réelles ----------
  function liveRefresh(){
    try {
      const s = S();
      const power = (typeof selectedShipPower === "function") ? selectedShipPower() : {attack:0,cargo:0,count:0};
      const set = (sel, val) => { const el = document.querySelector(sel); if (el) el.textContent = f(val); };
      set("[data-cc-count]", power.count);
      set("[data-cc-attack]", power.attack);
      set("[data-cc-cargo]", power.cargo);
    } catch(e){}
  }

  function syncDraftFromInputs(){
    const s = S();
    s.missionDraft = s.missionDraft || { ships:{}, cargo:{titanium:0,xenite:0,antimatter:0} };
    document.querySelectorAll("#cc-ship-selector .cc-ship-input").forEach(inp => {
      const id = inp.getAttribute("data-ship");
      const v = Math.max(0, parseInt(inp.value || 0) || 0);
      if (typeof setMissionShip === "function") setMissionShip(id, v);
      else (s.missionDraft.ships = s.missionDraft.ships || {})[id] = v;
    });
    ["titanium","xenite","antimatter"].forEach(k => {
      const inp = document.getElementById("cc-cargo-" + k);
      if (!inp) return;
      const v = Math.max(0, parseInt(inp.value || 0) || 0);
      if (typeof setMissionCargo === "function") setMissionCargo(k, v);
      else (s.missionDraft.cargo = s.missionDraft.cargo || {})[k] = v;
    });
  }

  function resolveTarget(query){
    const s = S();
    const systems = Array.isArray(s.systems) ? s.systems : [];
    const q = String(query || "").trim();
    if (!q || !systems.length) return null;
    // Coordonnées "secteur-système" : 12-34, 12:34, 12 34
    const m = q.match(/^(\d+)\s*[:\-\s]\s*(\d+)$/);
    if (m){
      const a = parseInt(m[1], 10), b = parseInt(m[2], 10);
      let hit = systems.find(sy => num(sy.sector) === a && num(sy.system) === b);
      if (!hit) hit = systems.find(sy => num(sy.system) === b);
      if (hit) return hit;
    }
    // Numéro de système seul
    if (/^\d+$/.test(q)){
      const b = parseInt(q, 10);
      const hit = systems.find(sy => num(sy.system) === b);
      if (hit) return hit;
    }
    // Par nom / pseudo (exact puis approchant, insensible à la casse)
    const ql = q.toLowerCase();
    let hit = systems.find(sy => String(sy.name || "").toLowerCase() === ql);
    if (!hit) hit = systems.find(sy => String(sy.name || "").toLowerCase().includes(ql));
    if (!hit) hit = systems.find(sy => String(sy.owner || sy.player || sy.pseudo || "").toLowerCase() === ql);
    return hit || null;
  }

  function lockTarget(){
    const inp = document.getElementById("cc-target-input");
    const q = inp ? inp.value : "";
    const sys = resolveTarget(q);
    const s = S();
    if (!sys){
      if (typeof addLog === "function") addLog(`Cible introuvable : « ${q} ». Essaie des coordonnées (ex. 12-34) ou un nom de système.`);
      return;
    }
    if (sys.type === "home" || sys.owned){
      if (typeof addLog === "function") addLog("Cette destination t'appartient déjà — utilise la logistique inter-planètes pour tes propres planètes.");
      return;
    }
    s.selected = sys;
    if (typeof addLog === "function") addLog(`Cible verrouillée : ${sys.name} (${coordsLabel(sys)}).`);
    if (typeof render === "function") render();
  }

  function orderMission(missionType){
    syncDraftFromInputs();
    if (!targetSel()){
      if (typeof addLog === "function") addLog("Choisis d'abord une cible ennemie/neutre sur la carte Galaxie.");
      if (typeof render === "function") render();
      return;
    }
    if (typeof launchMission === "function") launchMission(missionType);
    else if (typeof render === "function") render();
  }

  function doTransfer(){
    const s = S();
    const fromEl = document.getElementById("cc-tr-from");
    const toEl = document.getElementById("cc-tr-to");
    const fromId = fromEl && fromEl.value;
    const toId = toEl && toEl.value;
    if (!fromId || !toId || String(fromId) === String(toId)){
      if (typeof addLog === "function") addLog("Choisis deux planètes différentes pour le transfert.");
      if (typeof render === "function") render();
      return;
    }
    if (typeof commitActiveResources === "function") commitActiveResources();
    if (typeof ensurePlanetResources === "function") ensurePlanetResources();
    const pr = s.planetResources || {};
    const src = pr[fromId], dst = pr[toId];
    if (!src || !dst){ if (typeof addLog === "function") addLog("Planète invalide."); return; }
    const moved = { titanium:0, xenite:0, antimatter:0 };
    ["titanium","xenite","antimatter"].forEach(k => {
      let amt = Math.max(0, Math.floor(Number((document.getElementById("cc-tr-" + k) || {}).value) || 0));
      amt = Math.min(amt, Math.floor(num(src[k])));
      src[k] = num(src[k]) - amt;
      dst[k] = num(dst[k]) + amt;
      moved[k] = amt;
    });
    if (typeof syncActiveResources === "function") syncActiveResources();
    if (typeof save === "function") save();
    const total = moved.titanium + moved.xenite + moved.antimatter;
    if (typeof addLog === "function") addLog(total > 0
      ? `Transfert logistique → ${planetName(toId)} : ${f(moved.titanium)} Ti, ${f(moved.xenite)} Xe, ${f(moved.antimatter)} AM.`
      : "Aucune ressource transférée (vérifie les quantités).");
    if (typeof render === "function") render();
  }

  const API = {
    view: commandCenterView,
    focusPlanet(pid){
      const s = S();
      if (typeof commitActiveResources === "function") commitActiveResources();
      s.activePlanetId = String(pid);
      if (typeof syncActiveResources === "function") syncActiveResources();
      if (typeof save === "function") save();
      if (typeof render === "function") render();
    },
    setShip(id, val){
      // Écriture directe dans le brouillon SANS passer par setMissionShip,
      // qui appelle fleetNoScroll149() -> active.blur() (perte de focus à chaque frappe).
      const s = S();
      s.missionDraft = s.missionDraft || { ships:{}, cargo:{titanium:0,xenite:0,antimatter:0} };
      s.missionDraft.ships = s.missionDraft.ships || {};
      const avail = num((typeof activePlanetShips === "function" ? activePlanetShips() : {})[id]);
      s.missionDraft.ships[id] = Math.max(0, Math.min(avail, parseInt(val || 0) || 0));
      liveRefresh();
    },
    setCargo(k, val){
      const s = S();
      s.missionDraft = s.missionDraft || { ships:{}, cargo:{titanium:0,xenite:0,antimatter:0} };
      s.missionDraft.cargo = s.missionDraft.cargo || { titanium:0, xenite:0, antimatter:0 };
      s.missionDraft.cargo[k] = Math.max(0, parseInt(val || 0) || 0);
      liveRefresh();
    },
    maxShip(id){
      if (typeof maxMissionShip === "function") maxMissionShip(id);
      if (typeof render === "function") render();
    },
    clearShips(){
      if (typeof clearMissionDraft === "function") clearMissionDraft();
      else { const s = S(); s.missionDraft = {ships:{},cargo:{titanium:0,xenite:0,antimatter:0}}; if (typeof render==="function") render(); }
    },
    order(missionType){ orderMission(missionType); },
    lockTarget(){ lockTarget(); },
    transfer(){ doTransfer(); }
  };
  G.StellarionCommandCenter = API;

  // Compat : anciens onclick StellarionCommandNative.*
  G.StellarionCommandNative = Object.assign(G.StellarionCommandNative || {}, {
    render(){ if (typeof render === "function") render(); },
    refresh(){ if (typeof render === "function") render(); },
    updatePreview(){ liveRefresh(); },
    maxShip(){},
    prepareMission(){ orderMission((document.getElementById("cmd-mission") || {}).value || "attack"); },
    prepareResourceTransfer(){ doTransfer(); }
  });

  // ETA live (léger et ciblé : uniquement quand la vue commandement est ouverte)
  setInterval(function(){
    try {
      const v = S().view;
      if (v !== "defenses" && v !== "command") return;
      const now = performance.now() / 1000;
      document.querySelectorAll("[data-cmd-eta]").forEach(el => {
        const end = num(el.getAttribute("data-cmd-eta"));
        const left = Math.max(0, end - now);
        el.textContent = (typeof fmtTime === "function") ? fmtTime(left) : Math.ceil(left) + "s";
      });
    } catch(e){}
  }, 1000);
})();
;

/* ---- bloc script (source: ligne ~26750) ---- */
(function(){
  "use strict";

  function n(v){ return Number(v || 0); }
  function fmt(v){ return Math.round(n(v)).toLocaleString("fr-FR"); }
  function S(){ return window.state || {}; }

  function planets(){
    return Array.isArray(S().planets) ? S().planets : [];
  }

  function activePlanet(){
    const ps = planets();
    const id = S().activePlanetId || S().currentPlanetId || S().selectedPlanetId || (ps[0] && ps[0].id);
    return ps.find(p => String(p.id) === String(id)) || ps[0] || null;
  }

  function getShipDefs(){
    return Array.isArray(window.SHIPS) ? window.SHIPS : [];
  }

  function planetShips(pid){
    if(typeof window.planetShips === "function"){
      try { return window.planetShips(pid) || {}; } catch(e){}
    }
    const s = S();
    return (s.planetShips && s.planetShips[pid]) ||
           (s.shipsByPlanet && s.shipsByPlanet[pid]) ||
           (s.fleetsByPlanet && s.fleetsByPlanet[pid]) ||
           {};
  }

  function shipAttack(id){
    const d = getShipDefs().find(x => String(x.id) === String(id)) || {};
    return n(d.attack || 0);
  }

  function shipDefense(id){
    // Dans ta DA : bouclier = défense. Sur la page flotte, la valeur affichée "Structure/Coque" est la défense.
    const d = getShipDefs().find(x => String(x.id) === String(id)) || {};
    return n(d.structure || d.hull || d.hp || d.defense || d.coque || 0);
  }

  function empireAttack(){
    return planets().reduce((sum,p) => {
      const sh = planetShips(p.id);
      return sum + Object.entries(sh).reduce((a,[id,q]) => a + n(q) * shipAttack(id), 0);
    }, 0);
  }

  function empireDefense(){
    return planets().reduce((sum,p) => {
      const sh = planetShips(p.id);
      return sum + Object.entries(sh).reduce((a,[id,q]) => a + n(q) * shipDefense(id), 0);
    }, 0);
  }

  function currentAttackDefense(){
    // Si le jeu a déjà ses propres fonctions exactes, elles sont prioritaires.
    let attack = null, defense = null;

    if(typeof window.empireFleetAttack === "function"){
      try { attack = n(window.empireFleetAttack()); } catch(e){}
    }
    if(attack === null && typeof window.empireFleetPower === "function"){
      try { attack = n(window.empireFleetPower()); } catch(e){}
    }
    if(attack === null) attack = empireAttack();

    if(typeof window.empireFleetDefense === "function"){
      try { defense = n(window.empireFleetDefense()); } catch(e){}
    }
    if(defense === null && typeof window.empireDefensePower === "function"){
      try { defense = n(window.empireDefensePower()); } catch(e){}
    }
    if(defense === null) defense = empireDefense();

    return { attack, defense, total: attack + defense };
  }

  function isRankingPage(){
    // Correctif anti-écrasement profil planète : ne jamais se baser sur tout le body.
    // Le topbar contient toujours « Classement/Militaire/Vapowh », donc l'ancien test
    // s'activait sur la page Planète et prenait la carte profil pour une ligne de classement.
    return !!document.querySelector(".ranking-v12,.ranking-grid-v12,.leaderboard,.lbf-shell,.lbf-list");
  }

  function patchRow(row){
    const txt = row.textContent || "";
    if(!/Vapowh|Vous|#3000/i.test(txt)) return;

    const stats = currentAttackDefense();

    // Cherche la cellule "Détail", celle qui contient déjà 🚀 et 🛡️.
    let detailCell = Array.from(row.querySelectorAll("td,div,span")).find(el => {
      const t = el.textContent || "";
      return /🚀|🛡️/.test(t) && t.length < 160;
    });

    if(!detailCell){
      const cells = Array.from(row.children || []);
      detailCell = cells.find(el => /Détail|🚀|🛡️/.test(el.textContent || "")) || cells[3] || row;
    }

    if(detailCell){
      detailCell.innerHTML = `
        <div class="rank-real-detail">
          <div class="rank-attack"><span>🚀 Attaque</span><b>${fmt(stats.attack)}</b></div>
          <div class="rank-defense"><span>🛡️ Défense</span><b>${fmt(stats.defense)}</b></div>
        </div>
      `;
    }

    // Score = total attaque + défense
    const scoreCell = Array.from(row.children || []).find(el => /Score/i.test(el.dataset?.label || "")) || Array.from(row.children || []).slice(-1)[0];
    if(scoreCell && scoreCell !== detailCell){
      const exactZero = Array.from(scoreCell.querySelectorAll("b,strong,span,div")).find(el => (el.textContent || "").trim() === "0");
      if(exactZero) exactZero.textContent = fmt(stats.total);
      else if((scoreCell.textContent || "").trim() === "0") scoreCell.textContent = fmt(stats.total);
    }

    row.dataset.rankingSyncedV2 = "1";
  }

  function patchRanking(){
    if(!isRankingPage()) return;

    const root = document.querySelector(".ranking-v12,.ranking-grid-v12,.leaderboard,.lbf-shell,.lbf-list");
    if(!root) return;

    const rows = Array.from(root.querySelectorAll(".ranking-row-v12,.ranking-row-v13,.leaderboard-row,.ranking-row,.lbf-row,tr"))
      .filter(el => {
        const t = el.textContent || "";
        return /Vapowh|Vous|#3000/i.test(t) && t.length < 1200;
      });

    rows.forEach(patchRow);

    // Note explicative injectée supprimée (parasitait le classement propre).
    document.querySelectorAll(".ranking-sync-note").forEach(e=>e.remove());
  }

  function patchFns(){
    ["renderRanking","renderLeaderboard","leaderboardView","rankingView","renderClassement"].forEach(name => {
      if(typeof window[name] === "function" && !window[name].__rankingSyncV2){
        const old = window[name];
        const wrap = function(){
          const res = old.apply(this, arguments);
          setTimeout(patchRanking, 0);
          return res;
        };
        wrap.__rankingSyncV2 = true;
        window[name] = wrap;
      }
    });
  }

  window.StellarionRankingSyncV2 = {
    patch: patchRanking,
    stats: currentAttackDefense
  };

  function boot(){
    patchFns();
    patchRanking();
  }

  if(document.readyState === "loading") document.addEventListener("DOMContentLoaded", boot);
  else boot();

  document.addEventListener("click", () => setTimeout(boot,0), true);
  setInterval(patchRanking, 1000);
})();
;

/* ---- bloc script (source: ligne ~26955) ---- */
(function(){
  "use strict";

  function N(v){return Number(v||0)}
  function F(v){try{if(typeof fmt==="function")return fmt(v||0)}catch(e){} return Math.round(N(v)).toLocaleString("fr-FR")}
  function E(v){return String(v??"").replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
  function S(){return window.state||{}}

  const ORIGINAL_SHIPS = (Array.isArray(window.SHIPS)?window.SHIPS:[]).map(s=>({...s}));

  function normalizeShip(ship){
    const s={...ship};
    s.cost=s.cost||{};
    ["titanium","xenite","antimatter"].forEach(k=>{
      if(s.cost[k]!==undefined)s.cost[k]=Math.max(1,Math.round(N(s.cost[k])));
      else if(s[k]!==undefined)s[k]=Math.max(1,Math.round(N(s[k])));
    });
    s.attack=Math.round(N(s.attack));
    if(s.structure!==undefined)s.structure=Math.round(N(s.structure));
    else if(s.hull!==undefined)s.structure=Math.round(N(s.hull));
    else if(s.hp!==undefined)s.structure=Math.round(N(s.hp));
    else if(s.defense!==undefined)s.structure=Math.round(N(s.defense));
    else s.structure=Math.max(1,Math.round(N(s.attack)*1.25));
    if(s.cargo!==undefined)s.cargo=Math.round(N(s.cargo));
    return s;
  }

  function installSingleShipSource(){
    if(!Array.isArray(window.SHIPS))return;
    // SHIPS is now the single truth. If a previous file already divided/multiplied values, keep them.
    window.SHIPS = window.SHIPS.map(normalizeShip);
    window.SHIP_BY_ID = Object.fromEntries(window.SHIPS.map(s=>[s.id,s]));
  }

  function shipDef(id){
    if(!window.SHIP_BY_ID)installSingleShipSource();
    return (window.SHIP_BY_ID&&window.SHIP_BY_ID[id]) || (Array.isArray(window.SHIPS)?window.SHIPS.find(s=>String(s.id)===String(id)):null) || {};
  }
  function shipName(id){const d=shipDef(id);return (d.icon?d.icon+" ":"")+(d.name||String(id).replace(/_/g," "))}
  function shipCost(id){return {...(shipDef(id).cost||{})}}
  function shipAttack(id){return N(shipDef(id).attack)}
  function shipDefense(id){const d=shipDef(id);return N(d.structure||d.hull||d.hp||d.defense)}
  function shipCargo(id){return N(shipDef(id).cargo)}
  function shipSpeed(id){return N(shipDef(id).speed||1)}
  function shipBuildTime(id){return N(shipDef(id).time||shipDef(id).buildTime||10)}

  function planets(){return Array.isArray(S().planets)?S().planets:[]}
  function planetShipsSafe(pid){
    if(typeof window.planetShips==="function"){try{return window.planetShips(pid)||{}}catch(e){}}
    const st=S();
    st.planetShips=st.planetShips||{};
    st.planetShips[pid]=st.planetShips[pid]||{};
    return st.planetShips[pid];
  }
  function countShips(ships){return Object.values(ships||{}).reduce((a,b)=>a+N(b),0)}
  function sumShips(ships,fn){return Object.entries(ships||{}).reduce((a,[id,q])=>a+N(q)*fn(id),0)}
  function cloneShips(ships){const out={};Object.entries(ships||{}).forEach(([id,q])=>{if(N(q)>0)out[id]=N(q)});return out}
  function empireAttack(){return planets().reduce((a,p)=>a+sumShips(planetShipsSafe(p.id),shipAttack),0)}
  function empireDefense(){return planets().reduce((a,p)=>a+sumShips(planetShipsSafe(p.id),shipDefense),0)}
  function empireCargo(){return planets().reduce((a,p)=>a+sumShips(planetShipsSafe(p.id),shipCargo),0)}

  window.shipPowerValue = shipAttack;
  window.shipDefenseValue = shipDefense;
  window.shipCargoValue = shipCargo;
  window.shipCostValue = shipCost;
  window.planetFleetPower = function(pid){return sumShips(planetShipsSafe(pid),shipAttack)};
  window.planetFleetDefense = function(pid){return sumShips(planetShipsSafe(pid),shipDefense)};
  window.planetFleetCargo = function(pid){return sumShips(planetShipsSafe(pid),shipCargo)};
  window.empireFleetPower = empireAttack;
  window.empireFleetAttack = empireAttack;
  window.empireFleetDefense = empireDefense;
  window.empireFleetCargo = empireCargo;

  function applyLosses(ships,ratio){
    const lost={},remaining={};
    Object.entries(ships||{}).forEach(([id,q])=>{
      q=N(q);
      const loss=Math.min(q,Math.max(0,Math.round(q*ratio)));
      if(loss>0)lost[id]=loss;
      if(q-loss>0)remaining[id]=q-loss;
    });
    return {lost,remaining};
  }

  function targetPower(target){
    target=target||{};
    const danger=N(target.danger||target.military||target.attack||target.power||target.level||1);
    const richness=N(target.richness||target.resources||1);
    return Math.round(Math.max(1,danger)*260 + Math.max(1,richness)*80);
  }
  function targetHull(target){
    target=target||{};
    const danger=N(target.danger||target.military||target.defense||target.level||1);
    return Math.round(Math.max(1,danger)*320);
  }
  function buildLoot(target,victory){
    if(!victory)return {titanium:0,xenite:0,antimatter:0,fragments:0};
    target=target||{};
    const richness=Math.max(1,N(target.richness||target.resources||1));
    const danger=Math.max(1,N(target.danger||target.military||1));
    return {
      titanium:Math.round(600*richness+140*danger),
      xenite:Math.round(320*richness+90*danger),
      antimatter:Math.round(70*richness+30*danger),
      fragments:target.aiThreat?2:0
    };
  }

  function simulateCombatClean(targetOrAttack,shipsOrDefense,opts){
    if(typeof targetOrAttack==="number" || typeof shipsOrDefense==="number"){
      const attackerPower=N(targetOrAttack), defenderPower=N(shipsOrDefense);
      const attackRoll=attackerPower*(0.90+Math.random()*0.20);
      const defenseRoll=defenderPower*(0.90+Math.random()*0.20);
      const victory=attackRoll>=defenseRoll;
      return {victory,attackerPower,defenderPower,attackRoll:Math.round(attackRoll),defenseRoll:Math.round(defenseRoll),attackerLossRatio:victory?0.18:0.55,defenderLossRatio:victory?0.65:0.18,captured:victory?0:Math.max(0,Math.floor(N(opts&&opts.shipCount)*0.08)),ransom:victory?0:Math.max(0,Math.round(attackerPower*1.5))};
    }
    const target=targetOrAttack||{};
    const sent=cloneShips(shipsOrDefense||{});
    const playerAttack=sumShips(sent,shipAttack);
    const playerDefense=sumShips(sent,shipDefense);
    const playerCargo=sumShips(sent,shipCargo);
    const enemyAttack=targetPower(target);
    const enemyDefense=targetHull(target);
    const attackRoll=playerAttack*(0.92+Math.random()*0.16);
    const defenseRoll=enemyDefense*(0.92+Math.random()*0.16);
    const victory=attackRoll>=defenseRoll;
    const playerLossRatio=victory?Math.min(0.38,enemyAttack/Math.max(1,playerAttack+playerDefense)*0.32):Math.min(0.92,enemyAttack/Math.max(1,playerDefense)*0.62);
    const enemyLossRatio=victory?Math.min(1,playerAttack/Math.max(1,enemyDefense)*0.92):Math.min(0.42,playerAttack/Math.max(1,enemyDefense)*0.35);
    const loss=applyLosses(sent,playerLossRatio);
    const enemyUnits=Math.max(1,Math.round((N(target.danger)||1)*12));
    const enemyLost=Math.max(0,Math.min(enemyUnits,Math.round(enemyUnits*enemyLossRatio)));
    return {
      version:"clean_core_v1",
      victory,targetName:target.name||"Cible inconnue",target,
      shipsSent:sent,playerLost:loss.lost,playerRemaining:loss.remaining,
      enemyLost:{unités:enemyLost,débris:Math.round(enemyDefense*enemyLossRatio*0.18)},
      loot:buildLoot(target,victory),
      playerAttack:Math.round(playerAttack),playerDefense:Math.round(playerDefense),playerCargo:Math.round(playerCargo),
      enemyAttack:Math.round(enemyAttack),enemyDefense:Math.round(enemyDefense),
      attackRoll:Math.round(attackRoll),defenseRoll:Math.round(defenseRoll)
    };
  }

  function rows(obj,mode){
    const entries=Object.entries(obj||{}).filter(([,v])=>N(v)>0);
    if(!entries.length)return '<div class="stc-empty">Aucune donnée</div>';
    return entries.map(([id,q])=>{
      const label=mode==="ships"?shipName(id):id;
      const cls=mode==="loss"?" loss":mode==="kill"?" kill":mode==="loot"?" loot":"";
      return `<div class="stc-row${cls}"><span>${E(label)}</span><b>${F(q)}</b></div>`;
    }).join("");
  }

  function renderCombatReport(target,result){
    result=result||{};
    target=target||result.target||{};
    const victory=!!result.victory;
    const title=target&&target.aiThreat?"Mission galactique":"Rapport de combat";
    const targetName=result.targetName||target.name||"Cible inconnue";
    const sent=result.shipsSent||result.sentShips||{};
    const remaining=result.playerRemaining||result.remainingShips||{};
    const lost=result.playerLost||result.losses||{};
    const enemyLost=result.enemyLost||result.defenderLost||{};
    const loot=result.loot||{};
    const playerAttack=N(result.playerAttack||result.attackerPower||sumShips(sent,shipAttack));
    const playerDefense=N(result.playerDefense||result.playerHull||sumShips(sent,shipDefense));
    const enemyAttack=N(result.enemyAttack||targetPower(target));
    const enemyDefense=N(result.enemyDefense||result.defenderPower||targetHull(target));
    return `<div class="stc-report">
      <div class="stc-head"><div><h2>${E(title)} : ${E(targetName)}</h2><div class="stc-sub">${new Date().toLocaleString("fr-FR")} · Combat orbital</div></div><div class="stc-result ${victory?"win":"loss"}">${victory?"✅ Victoire":"❌ Défaite"}</div></div>
      <div class="stc-kpis">
        <div class="stc-kpi"><small>Butin total</small><strong>${F(N(loot.titanium)+N(loot.xenite)+N(loot.antimatter)+N(loot.fragments))}</strong></div>
        <div class="stc-kpi"><small>Vaisseaux envoyés</small><strong>${F(countShips(sent))}</strong></div>
        <div class="stc-kpi"><small>Nos pertes</small><strong>${F(countShips(lost))}</strong></div>
        <div class="stc-kpi"><small>Vaisseaux revenus</small><strong>${F(countShips(remaining))}</strong></div>
      </div>
      <div class="stc-sections">
        <section class="stc-section"><h3>Butin récupéré</h3>${rows({Titane:loot.titanium,Xénite:loot.xenite,Antimatière:loot.antimatter,Fragments:loot.fragments},"loot")}</section>
        <section class="stc-section"><h3>Bilan de puissance</h3><div class="stc-row"><span>🚀 Attaque envoyée</span><b>${F(playerAttack)}</b></div><div class="stc-row"><span>🛡️ Défense envoyée</span><b>${F(playerDefense)}</b></div><div class="stc-row"><span>⚔️ Attaque ennemie</span><b>${F(enemyAttack)}</b></div><div class="stc-row"><span>🏰 Défense ennemie</span><b>${F(enemyDefense)}</b></div></section>
        <section class="stc-section"><h3>Vaisseaux envoyés</h3>${rows(sent,"ships")}</section>
        <section class="stc-section"><h3>Nos pertes</h3>${rows(lost,"loss")}</section>
        <section class="stc-section"><h3>Vaisseaux survivants</h3>${rows(remaining,"ships")}</section>
        <section class="stc-section"><h3>Pertes ennemies</h3>${rows(enemyLost,"kill")}</section>
      </div>
      <div class="stc-note">${victory?"Butin sécurisé : livraison au retour de la flotte.":"Défaite : renforce l’attaque ou envoie une flotte plus résistante."}</div>
    </div>`;
  }

  function legacyReportToClean(raw){
    const str=String(raw||"");
    const decoded=str
      .replace(/&lt;/g,"<")
      .replace(/&gt;/g,">")
      .replace(/&quot;/g,'"')
      .replace(/&#39;/g,"'")
      .replace(/&amp;/g,"&");
    if(/(?:stc-report|combat-report-pro1539|cr1539-)/.test(decoded)){
      return decoded
        .replace(/<script[\s\S]*?>[\s\S]*?<\/script>/gi,"")
        .replace(/\son\w+\s*=\s*(['"]).*?\1/gi,"")
        .replace(/\s(?:href|src)\s*=\s*(['"])\s*javascript:[\s\S]*?\1/gi,"");
    }
    return `<div class="stc-report"><div class="stc-head"><div><h2>Rapport de combat</h2><div class="stc-sub">Ancien rapport archivé</div></div><div class="stc-result loss">Archive</div></div><div class="stc-note">${E(str).replace(/\n/g,"<br>")}</div></div>`;
  }

  function formatMessageBody(selected){
    if(!selected)return "";
    const isCombat=selected.type==="combat"||(selected.meta&&selected.meta.context==="combat")||/Rapport de combat|Mission galactique|stc-report|cr1539-/i.test(String(selected.subject||"")+String(selected.body||""));
    if(isCombat){
      if(selected.meta&&selected.meta.result){
        const result=selected.meta.result;
        const target=result.target||result.system||selected.meta.target||null;
        if(typeof window.combatReportBody1539==="function"){
          try{return window.combatReportBody1539(target,result)}catch(e){}
        }
        return renderCombatReport(target,result);
      }
      return legacyReportToClean(selected.body||"");
    }
    return `<pre style="white-space:pre-wrap;line-height:1.45;background:rgba(0,0,0,.18);border:1px solid rgba(255,255,255,.08);border-radius:14px;padding:14px;color:#dbeafe">${E(String(selected.body||"").replaceAll("\\n","\n"))}</pre>`;
  }

  function messagesViewClean(){
    const messages=S().messages||[];
    const selectedId=S().selectedMessageId;
    const selected=messages.find(m=>m.id===selectedId)||messages[0];
    const rowsHtml=messages.length?messages.map(function(m){
      const sel=(selected&&m.id===selected.id)?'selected-row':'';
      const ico=(typeof messageIcon==='function'?messageIcon(m.type):'📩');
      return '<div class="row '+sel+'" onclick="state.selectedMessageId=\''+E(m.id)+'\'; if(typeof openMessage===\'function\')openMessage(\''+E(m.id)+'\')" style="cursor:pointer"><strong>'+ico+' '+E(m.subject)+'</strong><div class="small '+(m.read?'muted':'ok')+'">'+(m.read?'Lu':'Non lu')+' · '+new Date(m.createdAt).toLocaleString('fr-FR')+'</div></div>';
    }).join(''):'<p class="muted small">Aucun message pour le moment. Envoie une sonde pour recevoir un rapport.</p>';
    const detail=selected?'<span class="pill">'+(typeof messageIcon==='function'?messageIcon(selected.type):'📩')+' MESSAGE</span><h2>'+E(selected.subject)+'</h2><p class="small muted">'+new Date(selected.createdAt).toLocaleString('fr-FR')+'</p>'+formatMessageBody(selected)+'<div class="quick-message-actions">'+(selected.meta&&selected.meta.to?'<button class="btn" onclick="openReplyToMessage(\''+E(selected.id)+'\')">↩️ Répondre</button>':'')+'<button class="btn btn-ghost" onclick="deleteMessage(\''+E(selected.id)+'\')">Supprimer</button></div>':'<p class="muted">Sélectionne un message.</p>';
    return '<div class="messages-view message-layout" style="height:100%;display:grid;grid-template-columns:360px 1fr;gap:14px;padding:18px;overflow:hidden"><div class="card panel messages-list" style="overflow:auto"><span class="pill">MESSAGERIE · '+(typeof unreadCount==='function'?unreadCount():0)+' non lu(s)</span><div class="stellarion-compose-card-v16fix"><strong>Écrire à un joueur</strong><p class="small muted">Composer protégé.</p><button class="btn" style="width:100%;margin-top:8px" onclick="openStellarionMessageV16Fix()">✍️ Nouveau message</button></div>'+rowsHtml+'</div><div class="card panel message-detail" style="overflow:auto">'+detail+'</div></div>';
  }

  installSingleShipSource();
  window.simulateCombat=simulateCombatClean;
  window.combatReportBody=function(report){return renderCombatReport(report&&report.target,report||{})};
  window.safeCombatReportBody=function(target,result){return renderCombatReport(target,result||{})};
  window.stellarionFormatMessageBody=formatMessageBody;
  window.messagesView=messagesViewClean;

  window.StellarionCleanCoreV1={
    ships:function(){return window.SHIPS},
    shipDef,shipAttack,shipDefense,shipCargo,shipCost,shipSpeed,shipBuildTime,
    planetAttack:window.planetFleetPower,planetDefense:window.planetFleetDefense,planetCargo:window.planetFleetCargo,
    empireAttack,empireDefense,empireCargo,
    simulateCombat:simulateCombatClean,renderCombatReport
  };
})();
;

/* ---- bloc script (source: ligne ~27191) ---- */
(function(){
  "use strict";
  if(Array.isArray(window.SHIPS)){
    window.SHIP_BY_ID = Object.fromEntries(window.SHIPS.map(s => [s.id, s]));
  }
  window.shipPowerValue = function(id){
    const s = (window.SHIP_BY_ID && window.SHIP_BY_ID[id]) || (Array.isArray(window.SHIPS) ? window.SHIPS.find(x => x.id === id) : null) || {};
    return Number(s.attack || 0);
  };
  window.shipDefenseValue = function(id){
    const s = (window.SHIP_BY_ID && window.SHIP_BY_ID[id]) || (Array.isArray(window.SHIPS) ? window.SHIPS.find(x => x.id === id) : null) || {};
    return Number(s.structure || s.hull || s.hp || s.defense || 0);
  };
})();
