/* ---- bloc script (source: ligne ~27260) ---- */
(function(){
  "use strict";

  function N(v){ return Number(v || 0); }
  function F(v){
    try{ if(typeof fmt === "function") return fmt(v || 0); }catch(e){}
    return Math.round(N(v)).toLocaleString("fr-FR");
  }
  function S(){ return window.state || {}; }
  function E(v){ return String(v ?? "").replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m])); }

  function shipList(){
    return Array.isArray(window.SHIPS) ? window.SHIPS : [];
  }

  function rebuildShipIndex(){
    window.SHIP_BY_ID = Object.fromEntries(shipList().map(s => [s.id, s]));
    return window.SHIP_BY_ID;
  }

  function shipDef(id){
    if(!window.SHIP_BY_ID) rebuildShipIndex();
    return (window.SHIP_BY_ID && window.SHIP_BY_ID[id]) || shipList().find(s => String(s.id) === String(id)) || {};
  }

  function shipAttack(id){
    const s = shipDef(id);
    return N(s.attack || s.atk || s.power || 0);
  }

  function shipDefense(id){
    const s = shipDef(id);
    return N(s.structure || s.hull || s.hp || s.defense || s.coque || 0);
  }

  function shipCargo(id){
    const s = shipDef(id);
    return N(s.cargo || 0);
  }

  function shipName(id){
    const s = shipDef(id);
    return (s.icon ? s.icon + " " : "") + (s.name || String(id).replace(/_/g, " "));
  }

  function planets(){
    return Array.isArray(S().planets) ? S().planets : [];
  }

  function normalizeShips(obj){
    const out = {};
    if(!obj || typeof obj !== "object") return out;
    Object.entries(obj).forEach(([id, value]) => {
      if(value && typeof value === "object"){
        const sid = value.id || value.ship_id || value.shipId || value.type || id;
        const qty = value.count ?? value.qty ?? value.quantity ?? value.amount ?? value.owned ?? value.available ?? value.total ?? value.stock;
        if(N(qty) > 0) out[sid] = (out[sid] || 0) + N(qty);
      }else if(N(value) > 0){
        out[id] = (out[id] || 0) + N(value);
      }
    });
    return out;
  }

  function planetShipsRaw(planetId){
    const st = S();
    return (st.planetShips && st.planetShips[planetId]) ||
           (st.shipsByPlanet && st.shipsByPlanet[planetId]) ||
           (st.fleetsByPlanet && st.fleetsByPlanet[planetId]) ||
           (st.arsenalByPlanet && st.arsenalByPlanet[planetId]) ||
           {};
  }

  function planetShipsArrays(planetId){
    const st = S();
    const out = {};
    [
      st.ships,
      st.playerShips,
      st.ownedShips,
      st.shipInventory,
      st.arsenalShips,
      st.availableShips,
      st.fleetStock,
      st.vessels
    ].filter(Array.isArray).flat().forEach(row => {
      if(!row || typeof row !== "object") return;
      const pid = row.planet_id || row.planetId || row.base_planet_id || row.home_planet_id || row.location_planet_id;
      if(pid && planetId && String(pid) !== String(planetId)) return;
      const id = row.ship_id || row.shipId || row.type || row.key || row.id || row.name;
      const qty = row.count ?? row.qty ?? row.quantity ?? row.amount ?? row.owned ?? row.available ?? row.total ?? row.stock;
      if(id && N(qty) > 0) out[id] = (out[id] || 0) + N(qty);
    });
    return out;
  }

  function getPlanetShips(planetId){
    const a = normalizeShips(planetShipsRaw(planetId));
    const b = normalizeShips(planetShipsArrays(planetId));
    const out = {...a};
    Object.entries(b).forEach(([id,q]) => out[id] = (out[id] || 0) + N(q));
    return out;
  }

  function calculateMilitaryStats(scope){
    const ids = [];
    if(scope && typeof scope === "object" && scope.ships){
      ids.push({ id:"__direct__", ships: normalizeShips(scope.ships) });
    }else if(scope){
      ids.push({ id: scope, ships: getPlanetShips(scope) });
    }else{
      planets().forEach(p => ids.push({ id:p.id, ships:getPlanetShips(p.id) }));
      if(!ids.length && S().activePlanetId) ids.push({ id:S().activePlanetId, ships:getPlanetShips(S().activePlanetId) });
    }

    const byShip = {};
    const byPlanet = {};
    let ships = 0, attack = 0, defense = 0, cargo = 0;

    ids.forEach(p => {
      const pstats = { ships:0, attack:0, defense:0, cargo:0, military:0, byShip:{} };
      Object.entries(p.ships || {}).forEach(([id, qty]) => {
        qty = N(qty);
        if(qty <= 0) return;
        const a = qty * shipAttack(id);
        const d = qty * shipDefense(id);
        const c = qty * shipCargo(id);
        ships += qty; attack += a; defense += d; cargo += c;
        pstats.ships += qty; pstats.attack += a; pstats.defense += d; pstats.cargo += c;
        byShip[id] = byShip[id] || { id, name: shipName(id), qty:0, attack:0, defense:0, cargo:0 };
        byShip[id].qty += qty; byShip[id].attack += a; byShip[id].defense += d; byShip[id].cargo += c;
        pstats.byShip[id] = { id, name: shipName(id), qty, attack:a, defense:d, cargo:c };
      });
      pstats.military = pstats.attack + pstats.defense;
      byPlanet[p.id] = pstats;
    });

    return {
      ships,
      attack,
      defense,
      cargo,
      military: attack + defense,
      power: attack + defense,
      byShip,
      byPlanet,
      source: "planetShips + SHIPS",
      updatedAt: Date.now()
    };
  }

  let syncingStateStats = false;
  let lastSyncedStats = null;

  function syncStateStats(){
    if(syncingStateStats) return lastSyncedStats || calculateMilitaryStats();
    syncingStateStats = true;
    const stats = calculateMilitaryStats();
    try{
      const st = S();
      st.militaryStats = stats;
      st.attack = stats.attack;
      st.defense = stats.defense;
      st.military = stats.military;
      st.militaryScore = stats.military;
      st.fleetPower = stats.attack;
      st.fleetDefense = stats.defense;
      st.fleetCargo = stats.cargo;
      lastSyncedStats = stats;
    }finally{
      syncingStateStats = false;
    }
    return stats;
  }

  function patchRanking(){
    // Correctif anti-flicker / anti-profil vide : ce patch ne doit agir QUE dans le DOM du classement.
    // Avant, il scannait tout le document et remplaçait la carte profil planète car elle contient Vapowh.
    const root = document.querySelector(".ranking-v12,.ranking-grid-v12,.leaderboard,.lbf-shell,.lbf-list");
    if(!root) return;
    const stats = syncStateStats();

    const candidates = Array.from(root.querySelectorAll(".ranking-row-v12,.ranking-row-v13,.leaderboard-row,.ranking-row,.lbf-row,tr"))
      .filter(el => {
        const t = el.textContent || "";
        return /Vapowh|Vous|#3000/i.test(t) && t.length < 1400;
      });

    candidates.forEach(row => {
      const detailCell = Array.from(row.querySelectorAll("td,div,span")).find(el => {
        const t = el.textContent || "";
        return /🚀|🛡️|Attaque|Défense/i.test(t) && t.length < 220;
      }) || Array.from(row.children || [])[3] || row;

      if(detailCell){
        detailCell.innerHTML = `
          <div class="rank-real-detail">
            <div class="rank-attack"><span>🚀 Attaque</span><b>${F(stats.attack)}</b></div>
            <div class="rank-defense"><span>🛡️ Défense</span><b>${F(stats.defense)}</b></div>
            <div class="rank-total"><span>⭐ Militaire</span><b>${F(stats.military)}</b></div>
          </div>
        `;
      }

      // Replace obvious score 0 in current player row.
      Array.from(row.querySelectorAll("b,strong,span,td,div")).forEach(el => {
        const txt = (el.textContent || "").trim();
        const parentTxt = (el.parentElement && el.parentElement.textContent) || "";
        if(txt === "0" && !/Rang|#/.test(parentTxt) && el.children.length === 0){
          el.textContent = F(stats.military);
        }
      });
      row.dataset.militaryStatsSynced = "1";
    });
  }

  function patchCommandement(){
    // Nettoyage inconditionnel : retire la boîte de stats militaires injectée qui se
    // glissait dans le switcher de planète (il contient le mot « puissance ») et cassait
    // l'affichage. Fait sur toutes les pages, pas seulement le Centre de Commandement.
    document.querySelectorAll(".military-stats-mini").forEach(e => e.remove());
    return;
  }

  function patchFunctions(){
    const names = ["renderRanking","renderLeaderboard","leaderboardView","rankingView","renderClassement","commandCenterView","renderCommand","renderCommandement"];
    names.forEach(name => {
      if(typeof window[name] === "function" && !window[name].__militaryStatsEngineV1){
        const old = window[name];
        const wrap = function(){
          syncStateStats();
          const res = old.apply(this, arguments);
          setTimeout(()=>{patchRanking();patchCommandement();},0);
          return res;
        };
        wrap.__militaryStatsEngineV1 = true;
        window[name] = wrap;
      }
    });
  }

  rebuildShipIndex();
  window.calculateMilitaryStats = calculateMilitaryStats;
  window.syncMilitaryStats = syncStateStats;
  window.shipPowerValue = shipAttack;
  window.shipAttackValue = shipAttack;
  window.shipDefenseValue = shipDefense;
  window.shipCargoValue = shipCargo;
  window.planetFleetPower = function(pid){ return calculateMilitaryStats(pid).attack; };
  window.planetFleetAttack = function(pid){ return calculateMilitaryStats(pid).attack; };
  window.planetFleetDefense = function(pid){ return calculateMilitaryStats(pid).defense; };
  window.planetFleetCargo = function(pid){ return calculateMilitaryStats(pid).cargo; };
  window.empireFleetPower = function(){ return calculateMilitaryStats().attack; };
  window.empireFleetAttack = function(){ return calculateMilitaryStats().attack; };
  window.empireFleetDefense = function(){ return calculateMilitaryStats().defense; };
  window.empireFleetCargo = function(){ return calculateMilitaryStats().cargo; };
  window.empireMilitaryPower = function(){ return calculateMilitaryStats().military; };

  window.StellarionMilitaryStatsEngineV1 = {
    calculate: calculateMilitaryStats,
    sync: syncStateStats,
    patchRanking,
    patchCommandement,
    getPlanetShips,
    shipAttack,
    shipDefense,
    shipCargo
  };

  function boot(){
    syncStateStats();
    patchFunctions();
    patchRanking();
    patchCommandement();
  }

  if(document.readyState === "loading") document.addEventListener("DOMContentLoaded", boot);
  else boot();

  document.addEventListener("click", () => setTimeout(boot,0), true);
  setInterval(boot, 1000);
})();
;

