 const offerId=hasDuplicates && entries.some(([id])=>id===state.marketApparatOfferId)?state.marketApparatOfferId:(entries[0]&&entries[0][0])||"";
 const requestList=marketApparatCatalog().filter(a=>a&&a.id!==offerId&&(!offerId||a.rarity===(marketApparatById(offerId)||{}).rarity));
