function ensureLeaderboardState(){
 state.leaderboards = state.leaderboards || {
  power: [],
  wealth: [],
  victories: [],
  alliances: []
 };
 state.lastLeaderboardUpdate = state.lastLeaderboardUpdate || 0;
}

async function updateLeaderboards(){
 ensureLeaderboardState();
 const now = Date.now();
 if(now - state.lastLeaderboardUpdate < 60000) return; // Update max 1/min
 
 state.lastLeaderboardUpdate = now;
 
 if(!supa) return;
 
 try {
  // Récupérer top 50 par puissance
  const { data: powerTop } = await supa
      .from('player_stats')
   .select('player_id, player_name, total_power')
   .order('total_power', { ascending: false })
   .limit(50);
  
  state.leaderboards.power = (powerTop || []).map((p,i) => ({
   rank: i+1,
   ...p
  }));
  
  addLog("📊 Classements mis à jour.");
 } catch(e) {
  console.log('Erreur leaderboard:', e);
 }
}

