function ensureGlobalChatState(){
 state.globalChat = state.globalChat || [];
 state.directMessages = state.directMessages || {};
 state.mutedPlayers = state.mutedPlayers || [];
 state.currentDMWith = null;
}

async function sendGlobalMessage(text){
 ensureGlobalChatState();
 if(!text.trim() || text.length > 500) return false;
 
 const msg = {
  id: "msg_" + Date.now(),
  sender_id: state.userId,
  sender_name: playerDisplayName(),
  text: text.trim(),
  timestamp: Date.now(),
  reactions: []
 };
 
 state.globalChat.unshift(msg);
 if(state.globalChat.length > 1000) state.globalChat.pop(); // Garder 1000 derniers
 
 save();render();
 
 if(supa){
  try {
   await supa.from('global_chat').insert([msg]);
  } catch(e) {
   console.log('Erreur chat global:', e);
  }
 }
 return true;
}

async function sendDirectMessage(toPlayerId, text){
 ensureGlobalChatState();
 if(!text.trim()) return false;
 
 const convId = [state.userId, toPlayerId].sort().join('|');
 state.directMessages[convId] = state.directMessages[convId] || [];
 
 const dm = {
  id: "dm_" + Date.now(),
  from_id: state.userId,
  from_name: playerDisplayName(),
  to_id: toPlayerId,
  text: text.trim(),
  timestamp: Date.now(),
  read: false
 };
 
 state.directMessages[convId].unshift(dm);
 save();render();
 
 if(supa){
  try {
   await supa.from('direct_messages').insert([dm]);
  } catch(e) {
   console.log('Erreur DM:', e);
  }
 }
 return true;
}

