function ensureTerritoryState(){
 state.territories = state.territories || [];
 state.territoryWars = state.territoryWars || [];
 
 // Créer quelques territoires de test
 if(state.territories.length === 0){
  state.territories = [
   {id:"t1", name:"Secteur Alpha", region:"[0|0]", controlling_alliance_id:null, bonus_type:"titanium", bonus_percent:20},
   {id:"t2", name:"Secteur Beta", region:"[5|5]", controlling_alliance_id:null, bonus_type:"xenite", bonus_percent:20},
   {id:"t3", name:"Secteur Gamma", region:"[10|10]", controlling_alliance_id:null, bonus_type:"antimatter", bonus_percent:20},
   {id:"t4", name:"Secteur Delta", region:"[-5|-5]", controlling_alliance_id:null, bonus_type:"credits", bonus_percent:15}
  ];
 }
}

async function claimTerritory(territoryId, allianceId){
 ensureTerritoryState();
 
 if(!state.alliance || state.alliance.id !== allianceId){
  addLog("Votre alliance n'existe pas.");
  return false;
 }
 
 const territory = state.territories.find(t => t.id === territoryId);
 if(!territory){
  addLog("Territoire introuvable.");
  return false;
 }
 
 if(territory.controlling_alliance_id && territory.controlling_alliance_id !== allianceId){
  // Déclencher guerre
  addLog("⚔️ Guerre pour " + territory.name + " déclarée!");
  state.territoryWars.push({
   id: "war_" + Date.now(),
   territory_id: territoryId,
   attacker_id: allianceId,
   defender_id: territory.controlling_alliance_id,
   start_time: Date.now(),
   attacker_victories: 0,
   defender_victories: 0,
   end_time: null,
   winner_id: null
  });
 } else {
  // Claim direct
  territory.controlling_alliance_id = allianceId;
  state.allianceLogs.unshift("Territoire " + territory.name + " revendiqué!");
  addLog("✅ " + territory.name + " revendiqué pour l'alliance!");
 }
 
 save();render();
 saveAllianceToSupabase();
 
 return true;
}

function territoriesMapHtml(){
 ensureTerritoryState();
 const allianceId = state.alliance?.id;
 
 return `<div class="territory-panel">
  <span class="pill">🗺️ TERRITOIRES</span>
  <h2>Contrôle Galactique</h2>
  <p class="muted">Revendiquer des zones = bonus permanents pour l'alliance</p>
  
  <div class="territories-grid">
   ${state.territories.map(t => {
    const controlled = t.controlling_alliance_id === allianceId;
    return `<div class="territory-card ${controlled?'owned':''}">
     <div><strong>${t.name}</strong></div>
     <div class="small muted">${t.region}</div>
     <div class="small">+${t.bonus_percent}% ${t.bonus_type}</div>
     ${t.controlling_alliance_id ? 
      `<div class="small" style="color:#FFD54F">Contrôlé</div>` :
      `<button class="btn btn-ghost" style="width:100%;margin-top:8px;font-size:11px" onclick="claimTerritory('${t.id}', '${allianceId||''}')">Revendiquer</button>`
     }
    </div>`;
   }).join('')}
  </div>
  
  <h3>Guerres en cours</h3>
  <div class="wars-list">
   ${state.territoryWars.filter(w => !w.end_time).map(w => {
    const terr = state.territories.find(t => t.id === w.territory_id);
    return `<div class="war-card">
     <strong>${terr?.name}</strong>
     <div class="small muted">Attaquant vs Commandementur</div>
     <div class="war-progress">
      <div style="flex:${w.attacker_victories}">A: ${w.attacker_victories}</div>
      <div style="flex:${w.defender_victories}">D: ${w.defender_victories}</div>
     </div>
    </div>`;
   }).join('') || '<p class="muted small">Pas de guerres.</p>'}
  </div>
 </div>`;
}

