/* Alpha 1.5.42 V14 — horloge temps réel persistante sur toutes les pages */
(function(){
  if(window.__stellarionLiveClockV14)return;
  window.__stellarionLiveClockV14=true;
  function tick(){
    try{
      const now=new Date();
      const time=now.toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit',second:'2-digit'});
      const date=now.toLocaleDateString('fr-FR');
      document.querySelectorAll('#stellarion-live-time-v14,[data-live-time-v14]').forEach(el=>{el.textContent=time;});
      document.querySelectorAll('#stellarion-live-date-v14,[data-live-date-v14]').forEach(el=>{el.textContent=date;});
      const box=document.querySelector('[data-live-clock-v14]');
      if(box)box.setAttribute('title','Heure serveur en temps réel : '+time+' · '+date);
    }catch(e){}
  }
  tick();
  setInterval(tick,250);
  document.addEventListener('visibilitychange',tick);
  window.addEventListener('focus',tick);
})();
;

