    to=to.trim(); subject=subject.trim(); body=body.trim();
    if(!to||!subject||!body){alert('Message incomplet : destinataire, sujet et message obligatoires.');return false;}
    window.state=window.state||{}; state.messages=Array.isArray(state.messages)?state.messages:[];
    var msg={id:'msg_'+Date.now(),type:'player_sent',subject:'Message envoyé : '+subject,body:'À : '+to+'\n\n'+body,createdAt:Date.now(),read:true,meta:{to:to,folder:'sent'}};
    state.messages.unshift(msg); state.selectedMessageId=msg.id; state.messageDraft={to:'Commandant voisin',subject:'',body:''};
