      state.alliance={id:'ally_'+Date.now(),name:nm,tag:tg,description:de,founder:playerName(),createdAt:Date.now(),rank:'Fondateur',status:'open',members:[{name:playerName(),rank:'Fondateur',power:0,country:(state.profile&&state.profile.country)||state.country||'',status:'En ligne'}]};
      state.allianceLogs=state.allianceLogs||[]; state.allianceLogs.unshift('Alliance ['+tg+'] '+nm+' créée.');
      try{addLog('Alliance créée : ['+tg+'] '+nm+'.');}catch(x){}
