/* Alpha 1.5.45 - files d'attente sidebar: timers vivants + retrait automatique */
(function(){
  if(window.__stellarionQueueSidebarLiveFixV145)return;
  window.__stellarionQueueSidebarLiveFixV145=true;
  function formatQueueTimeV145(seconds){
    try{ if(typeof fmtTime==='function')return fmtTime(seconds); }catch(e){}
    seconds=Math.max(0,Math.ceil(Number(seconds)||0));
    var h=Math.floor(seconds/3600),m=Math.floor((seconds%3600)/60),sec=seconds%60;
    return h>0?(h+'h '+String(m).padStart(2,'0')+'m'):(m+'m '+String(sec).padStart(2,'0')+'s');
  }
  function processQueuesV145(){
    if(!window.state)return false;
    var beforeBuild=Array.isArray(state.buildQueue)?state.buildQueue.length:0;
    var beforeShips=Array.isArray(state.shipQueue)?state.shipQueue.length:0;
    try{ if(typeof processBuildQueue==='function')processBuildQueue(false); }catch(e){}
    try{ if(typeof processShipQueue==='function')processShipQueue(false); }catch(e){}
    var afterBuild=Array.isArray(state.buildQueue)?state.buildQueue.length:0;
    var afterShips=Array.isArray(state.shipQueue)?state.shipQueue.length:0;
    return beforeBuild!==afterBuild || beforeShips!==afterShips;
  }
  function updateDomTimersV145(){
    var now=Date.now();
    document.querySelectorAll('[data-finish-at]').forEach(function(el){
      var finish=Number(el.getAttribute('data-finish-at'))||0;
      var remain=Math.max(0,(finish-now)/1000);
      if(el.matches('[data-progress]')){
        if(el.textContent) el.textContent='';
        var start=Number(el.getAttribute('data-start-at'))||now;
        var total=Math.max(1,finish-start);
        var pct=Math.max(0,Math.min(100,100-Math.round(((finish-now)/total)*100)));
        el.style.width=pct+'%';
      }else{
        el.textContent=formatQueueTimeV145(remain);
      }
    });
  }
  function tickV145(){
    var changed=processQueuesV145();
    if(changed){
      try{ if(typeof save==='function')save(); }catch(e){}
      try{ if(typeof render==='function')render(); return; }catch(e){}
    }
    updateDomTimersV145();
  }
  setInterval(tickV145,1000);
  document.addEventListener('visibilitychange',function(){ if(!document.hidden)tickV145(); });
  window.addEventListener('focus',tickV145);
  setTimeout(tickV145,0);
})();

