      mission:row.mission||"mission",
      from:{name:row.player_name||"Départ",galaxyX:Number(row.from_x),galaxyY:Number(row.from_y)},
      to:{name:row.target_name||"Cible",galaxyX:Number(row.to_x),galaxyY:Number(row.to_y)},
      startTime:sec()-elapsed,
