    interceptor:      { name:"Ghost Blade",        icon:"⚔️", legacy:["Intercepteur"] },
    large_cargo:      { name:"Atlas MK-IV",        icon:"🚚", legacy:["Grand transporteur"] },
    heavy_fighter:    { name:"Spectre-X",          icon:"🛫", legacy:["Chasseur lourd"] },
    frigate:          { name:"Titanis",            icon:"🛡️", legacy:["Frégate","Fregate"] },
    cruiser:          { name:"Oblivion",           icon:"🚢", legacy:["Croiseur"] },
