  var G = window;
  var busy = false, lastRestore = 0, lastResult = null;
  var TABLES = { alliances:'alliances', members:'alliance_members', chat:'alliance_chat' };

  function st(){ G.state = G.state || {}; return G.state; }
  function client(){ try { return G.supa || (typeof supa !== 'undefined' ? supa : null); } catch(e){ return G.supa || null; } }
  function uid(){ try { return (typeof currentUser !== 'undefined' && currentUser && currentUser.id) || st().userId || ''; } catch(e){ return st().userId || ''; } }
  function isOnlineUser(){ var id = uid(); return !!(id && id !== 'local_player' && id !== 'invite'); }
  function esc(v){ return String(v == null ? '' : v).replace(/[&<>"']/g,function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]; }); }
