/* ---- Saisie clavier du nombre de vaisseaux en mission (1.5.71) ----
   Remplace l'ancien affichage <b> par un <input type="number"> tapable.
   Neutralise le blur() programmatique des couches scroll (151/153/154/156)
   pendant la saisie, sinon le champ perd le focus a chaque frappe. */
(function(){
  function commitQty(id,val){
    if(typeof state==="undefined")return 0;
    state.missionDraft=state.missionDraft||{ships:{},cargo:{titanium:0,xenite:0,antimatter:0}};
    state.missionDraft.ships=state.missionDraft.ships||{};
    var owned=Number((typeof activePlanetShips==="function"?(activePlanetShips()[id]||0):0))||0;
    var n=parseInt(val,10);
    if(!isFinite(n)||n<0)n=0;
    if(n>owned)n=owned;
    state.missionDraft.ships[id]=n;
    return n;
  }

  // Frappe en cours : maj live (puissance/cargo) sans re-render destructeur,
  // et SANS reformater le champ actif pour ne pas casser le curseur.
  window.missionQtyInput=function(el){
    if(!el)return;
    commitQty(el.getAttribute("data-id"),el.value);
    try{
      if(typeof updateMissionPlannerLive==="function")updateMissionPlannerLive();
      else if(typeof liveRefresh==="function")liveRefresh();
    }catch(e){}
  };

  // Validation (perte de focus naturelle ou Entree) : clamp visuel + save + render.
  window.missionQtyCommit=function(el){
    if(!el)return;
    var n=commitQty(el.getAttribute("data-id"),el.value);
    el.value=n;
    try{if(typeof save==="function")save();}catch(e){}
    try{if(typeof render==="function")render();}catch(e){}
  };

  // Tant que le champ est en saisie, on bloque uniquement les blur() PROGRAMMATIQUES.
  // Le changement de focus reel (clic/Tab) reste natif et fonctionne normalement.
  document.addEventListener("focusin",function(e){
    var el=e.target;
    if(!el||!el.classList||!el.classList.contains("missionQtyInput"))return;
    if(el.__qtyGuard)return;
    el.__qtyGuard=true;
    el.blur=function(){};
    el.addEventListener("keydown",function(ev){
      if(ev.key==="Enter"){ev.preventDefault();window.missionQtyCommit(el);}
    });
  },true);
})();


