/* STELLARION 1.5.96 - remove duplicated archived combat reports */
(function(){
  "use strict";
  if(window.__stellarionRemoveArchivedCombatDupes1596) return;
  window.__stellarionRemoveArchivedCombatDupes1596 = true;

  function S(){ try{return window.state || (typeof state!=="undefined"?state:null);}catch(e){return window.state||null;} }
  function isCombat(m){ return !!(m && /combat|rapport de combat|mission galactique/i.test(String(m.type)+" "+String(m.subject)+" "+String(m.body))); }
  function hasRichReport(m){
    var body=String(m&&m.body||"");
    return !!(m && m.meta && m.meta.result) || /stc-report|combat-report-pro|cr1539-|combatReportBody|<div/i.test(body);
  }
  function isArchivedFallback(m){
    if(!isCombat(m) || hasRichReport(m)) return false;
    var body=String(m&&m.body||"");
    return /Rapport de combat|Résultat\s*:|Butin|Stock apr[eè]s combat|Ce rapport est [eé]crit c[oô]t[eé] serveur/i.test(String(m&&m.subject||"")+" "+body);
  }
  function normalizedSubject(m){
    return String(m&&m.subject||"")
      .replace(/^[^\wÀ-ÿ]*(rapport de combat joueur|rapport de combat|mission galactique)\s*[:\-]\s*/i,"rapport de combat:")
      .replace(/\s+/g," ")
      .trim()
      .toLowerCase();
  }
  function createdBucket(m){
    var n=Number(m&&m.createdAt||0);
    return n ? Math.round(n/60000) : 0;
  }
  function rememberDeleted(m){
    try{
      var dbId=typeof window.serverMessageDbId==="function" ? window.serverMessageDbId(m) : "";
      if(!dbId && m && m.meta && m.meta.dbId) dbId=String(m.meta.dbId);
      if(!dbId) return;
      if(typeof window.rememberServerMessageDeleted==="function") window.rememberServerMessageDeleted(dbId);
      if(typeof window.syncServerMessageDeleted==="function") window.syncServerMessageDeleted(dbId);
    }catch(e){}
  }
  function cleanupArchivedCombatDupes(){
    var st=S(); if(!st || !Array.isArray(st.messages)) return 0;
    var groups=new Map();
    st.messages.forEach(function(m){
      if(!isCombat(m)) return;
      var key=normalizedSubject(m)+"|"+createdBucket(m);
      if(!groups.has(key)) groups.set(key,[]);
      groups.get(key).push(m);
    });
    var removeIds=new Set();
    groups.forEach(function(list){
      if(list.length<2) return;
      var rich=list.filter(hasRichReport);
      if(!rich.length) rich=list.filter(function(m){ return !isArchivedFallback(m); });
      if(!rich.length) return;
      list.forEach(function(m){
        if(isArchivedFallback(m)){
          removeIds.add(String(m.id));
          rememberDeleted(m);
        }
      });
    });
    if(!removeIds.size) return 0;
    st.messages=st.messages.filter(function(m){ return !removeIds.has(String(m&&m.id)); });
    if(st.selectedMessageId && removeIds.has(String(st.selectedMessageId))){
      st.selectedMessageId=(st.messages[0]&&st.messages[0].id)||"";
    }
    try{ if(typeof window.save==="function") window.save(); }catch(e){}
    try{ if(typeof window.updateNotificationBellLive==="function") window.updateNotificationBellLive(); }catch(e){}
    return removeIds.size;
  }

  var oldMessagesView=window.messagesView;
  if(typeof oldMessagesView==="function" && !oldMessagesView.__archivedCombatDedupe1596){
    var wrappedMessagesView=function(){
      cleanupArchivedCombatDupes();
      return oldMessagesView.apply(this,arguments);
    };
    wrappedMessagesView.__archivedCombatDedupe1596=true;
    window.messagesView=wrappedMessagesView;
    try{ messagesView=wrappedMessagesView; }catch(e){}
  }

  var oldAdd=window.addMessage;
  if(typeof oldAdd==="function" && !oldAdd.__archivedCombatDedupe1596){
    var addWrap=function(){
      var out=oldAdd.apply(this,arguments);
      setTimeout(cleanupArchivedCombatDupes,0);
      setTimeout(cleanupArchivedCombatDupes,800);
      return out;
    };
    addWrap.__archivedCombatDedupe1596=true;
    window.addMessage=addWrap;
    try{ addMessage=addWrap; }catch(e){}
  }

  var oldPoll=window.pollIncomingPlayerMessages;
  if(typeof oldPoll==="function" && !oldPoll.__archivedCombatDedupe1596){
    var pollWrap=function(){
      var out=oldPoll.apply(this,arguments);
      try{
        if(out && typeof out.then==="function") return out.then(function(v){ cleanupArchivedCombatDupes(); return v; });
        cleanupArchivedCombatDupes();
      }catch(e){}
      return out;
    };
    pollWrap.__archivedCombatDedupe1596=true;
    window.pollIncomingPlayerMessages=pollWrap;
    try{ pollIncomingPlayerMessages=pollWrap; }catch(e){}
  }

  setTimeout(cleanupArchivedCombatDupes,0);
  setTimeout(cleanupArchivedCombatDupes,1000);
  setInterval(cleanupArchivedCombatDupes,2500);
  window.stellarionArchivedCombatDedupeAudit1596=function(){
    var st=S()||{};
    return {
      patch:"remove-archived-combat-dupes-1.5.96",
      combatMessages:Array.isArray(st.messages)?st.messages.filter(isCombat).length:0,
      archivedFallbacks:Array.isArray(st.messages)?st.messages.filter(isArchivedFallback).map(function(m){return {id:m.id,subject:m.subject,createdAt:m.createdAt};}):[],
      removedNow:cleanupArchivedCombatDupes()
    };
  };
})();

